window.__Q=window.__Q||{};window.__Q["prev/8/A2"]=[{"q":"患者，女，18岁。双下肢对称性出血点1周，高出皮面，发痒，伴关节肿痛。血小板计数、出凝血时间及血块退缩试验均正常，凝血酶原消耗试验正常。尿蛋白（＋＋）。最可能的诊断是","o":["原发免疫性血小板减少症","过敏性紫癜","血管性血友病","单纯性紫癜","血小板功能异常"],"a":1,"e":"双下肢对称性、高出皮面伴瘙痒的紫癜，兼有关节肿痛及肾损害，为过敏性紫癜的典型表现。其血小板计数与凝血功能均正常，出血系血管壁功能异常所致；单纯性紫癜无关节与肾脏受累。"},{"q":"患者，男，30岁。眩晕、恶心3天。查体：眼球震颤阳性。患者最可能的诊断是","o":["晕动病","梅尼埃病","高血压病","眼肌麻痹","链霉素中毒"],"a":1,"e":"发作性旋转性眩晕伴恶心、呕吐及眼球震颤是梅尼埃病的核心表现，属周围性眩晕。其病理基础为膜迷路积水，常伴耳鸣与听力减退；晕动病仅在乘车船、航空时发作。"},{"q":"患者，男，48岁。突发阴囊疼痛4小时，向腹股沟区放射明显。查体：右侧阴囊明显红肿，皮温增高，触及睾丸附睾肿大呈一肿块，不易区分，触痛明显。该患者最可能的诊断是","o":["急性膀胱炎","急性前列腺炎","阴囊疝","急性附睾炎","附睾结核"],"a":3,"e":"急性附睾炎时附睾肿痛明显并常伴睾丸肿大，二者分界不清，阴囊皮肤红肿、皮温升高。附睾结核多为无痛性硬结伴输精管串珠样改变，与本例急性炎症过程不符。"},{"q":"患者，男，65岁。进行性排尿困难5年，不能自行排尿8小时，膀胱膨隆伴轻压痛。首选的治疗方法应该是","o":["药物治疗","针灸","耻骨上膀胱穿刺","导尿并保留导尿管","耻骨上膀胱造瘘"],"a":3,"e":"急性尿潴留解除梗阻的首选措施是留置导尿，可迅速排空膀胱、缓解胀痛并观察尿量。一次放尿不宜超过1000ml，以免腹压骤降引起虚脱或膀胱内出血。"},{"q":"患者，男，38岁。1天前感冒、发热，自服对乙酰氨基酚1片，1小时前出现呕血，量约50ml，平素身体健康，无腹痛。查体：肝脾不大。引起呕血最可能的病因是","o":["消化性溃疡","急性胃黏膜病变","食管-胃底静脉曲张","食管贲门黏膜撕裂综合征","食管炎"],"a":1,"e":"服用对乙酰氨基酚等非甾体抗炎药后突然呕血、平素无腹痛，符合药物损伤胃黏膜屏障所致的急性胃黏膜病变。消化性溃疡多有长期规律性上腹痛及溃疡病史。"},{"q":"75岁男性脑梗死患者，进行溶栓治疗，治疗初期，会出现","o":["纤维蛋白/纤维蛋白原降解产物阴性，D-二聚体阴性","纤维蛋白/纤维蛋白原降解产物阳性，D-二聚体阴性","纤维蛋白/纤维蛋白原降解产物阴性，D-二聚体阳性","纤维蛋白/纤维蛋白原降解产物阳性，D-二聚体阳性","纤维蛋白/纤维蛋白原降解产物阴性，D-二聚体可能阳性或者阴性"],"a":3,"e":"溶栓治疗使纤维蛋白及纤维蛋白原同时被降解，故纤维蛋白降解产物与D-二聚体均升高。D-二聚体是交联纤维蛋白降解的特异性标志物，其升高提示继发性纤溶。"},{"q":"图为一NHL患者的骨髓涂片，按恶性淋巴瘤的分期该患者应为","o":["Ⅰ期","Ⅱ期","Ⅲ期","Ⅳ期","Ⅱ期或Ⅲ期"],"a":3,"e":"官方题库缺失图片"},{"q":"青年男性，无明显诱因突发胸痛，呼吸困难。查体：瘦长体型，右侧胸廓饱满，呼吸运动减弱，气管向左侧偏移，叩诊鼓音。最可能的诊断为","o":["支气管哮喘","肺气肿","胸腔积液","气胸","支气管扩张"],"a":3,"e":"瘦长体型青年突发胸痛与呼吸困难，患侧胸廓饱满、呼吸运动减弱、叩诊鼓音、气管移向健侧，为自发性气胸的典型体征。胸腔积液叩诊为浊音或实音，气管亦移向健侧但语颤减弱更明显。"},{"q":"患者，女，30岁。乏力、恶心、食欲缺乏2周。查体：T 38℃，皮肤黄染，巩膜黄染，肝肋下1cm，质软，轻触痛。实验室检查：ALT 3000U/L，MAO 15U/L，HBsAg阳性。患者最可能的诊断是","o":["溶血性黄疸","慢性活动性肝炎","急性重型肝炎","肝硬化","梗阻性黄疸"],"a":2,"e":"HBsAg阳性、黄疸迅速加深伴ALT极度升高，提示乙型病毒性肝炎肝细胞广泛坏死；坏死肝细胞逸出MAO使血清MAO升高，符合急性重型肝炎。溶血性黄疸以间接胆红素升高为主，肝酶多正常。"},{"q":"23岁女性，游走性关节痛10年，胸闷、气短2年，心脏彩超提示风湿性心脏病。关节痛应属于","o":["主诉","现病史","既往史","系统回顾","个人史"],"a":2,"e":"既往史记录患者过去所患疾病与健康状况，风湿性心瓣膜病者应追问有无反复咽痛、游走性关节痛。本次发病的症状及演变过程才归入现病史。"},{"q":"患者，女，30岁，常感乏力、心悸、胸痛。查体：颈动脉搏动明显，心尖部可闻及柔和递减型舒张中晚期杂音，无震颤，胸骨右缘第2肋间可闻及舒张期叹息样杂音。X线心影呈靴形心，左室增大。可能的诊断是","o":["二尖瓣狭窄","主动脉瓣狭窄","主动脉瓣关闭不全","肥厚性心肌病","高血压心脏病"],"a":2,"e":"胸骨右缘第2肋间舒张期叹气样杂音、颈动脉搏动增强及靴形心是主动脉瓣关闭不全的典型表现，心尖部柔和递减型杂音为Austin Flint杂音。二尖瓣狭窄为心尖区舒张中晚期递增型隆隆样杂音。"},{"q":"患者，男，54岁。肝硬化出现腹水入院5天。今起出现发热、腹痛、腹胀明显。诊断为自发性细菌性腹膜炎。该患者腹水检验的特点是","o":["漏出性腹水","细胞总数小于200/μl","蛋白质含量为20g/L","乳酸脱氢酶含量为100U/L","分类时，中性粒细胞为75%"],"a":4,"e":"自发性细菌性腹膜炎属渗出性积液，腹水多形核中性粒细胞≥250/μl是诊断依据，分类以中性粒细胞为主。漏出液细胞数少、蛋白低，不符合感染性积液。"},{"q":"患者，男，58岁。乏力、上腹痛2个月。查体：心肺无异常，肝肋下2cm，触痛，脾不大。化验检查ALT、ALP、GGT和MAO均增高，A/G比值减低，AFP阳性。患者最可能的诊断是","o":["急性肝炎","慢性肝炎","肝硬化","原发性肝癌","化脓性梗阻性胆管炎"],"a":3,"e":"AFP阳性伴ALP、GGT显著升高而ALT升高不明显，提示肝内占位性病变，结合肝大触痛考虑原发性肝癌。急性肝炎以ALT升高为主，AFP一般阴性。"},{"q":"一患者主要因震颤入院。查体发现患者静止时震颤明显，运动时减轻，睡眠后消失，多有肌张力增高。属于以下哪种神经体征","o":["运动性震颤","静止性震颤","意向性震颤","手足徐动","舞蹈样运动"],"a":1,"e":"静止时明显、运动时减轻、睡眠后消失并伴肌张力增高，是静止性震颤的特点，见于帕金森病。意向性震颤在动作接近目标时加重，见于小脑病变。"},{"q":"患者，女，38岁。患风湿性心脏病二尖瓣狭窄3年。近1个月出现咳嗽及咳痰，伴夜间阵发性呼吸困难。查体：BP 120/80mmHg，P 90次/min，双肺底少许水泡音，心尖部闻及舒张中、晚期隆隆样杂音伴第一心音亢进及舒张期开瓣音。下一步处理首选","o":["二尖瓣置检术","经皮二尖瓣球囊扩张术","二尖瓣分裂术","冠状动脉造影术","继续观察"],"a":1,"e":"风湿性二尖瓣狭窄出现肺淤血症状而瓣叶活动度尚好者，首选经皮二尖瓣球囊扩张术，创伤小且能有效扩大瓣口面积。开瓣音存在提示瓣叶柔软，适合球囊扩张。"},{"q":"患者，男，42岁。节律性中上腹痛13年。每于餐后半小时发作，下次进餐前缓解；服硫糖铝症状可缓解。近3个月疼痛规律消失，服上药无效，且食欲减退。为明确诊断，应首选的检查是","o":["胃肠钡餐检查","血清促胃液素测定","胃液分析","癌胚抗原（CEA）测定","纤维胃镜检查加胃黏膜组织活检"],"a":4,"e":"疼痛规律改变、抑酸治疗失效伴食欲减退提示溃疡恶变可能，须行胃镜检查并取黏膜活检病理确诊。钡餐仅显示轮廓与黏膜形态，无法取得组织学证据。"},{"q":"患儿，男，1岁，出生1个月时儿保发现心脏杂音。查体：于胸骨左缘2肋间及3/6级粗糙收缩期杂音，伴P2增强，S2固定分裂。患儿可伴有","o":["发绀、杵状指","心尖冲动向左移位","双侧心界扩大","强迫蹲踞位","梨形心"],"a":1,"e":"胸骨左缘第2肋间收缩期杂音、P2增强伴S2固定分裂是房间隔缺损的表现，左向右分流致右心室容量负荷增加，右心室增大使心尖冲动向左侧移位。发绀与杵状指见于右向左分流。"},{"q":"患者因呼吸困难1周入院，查X线示右侧中等量胸腔积液，最不可能出现的体征是","o":["右侧呼吸运动受限","气管移向健侧","右侧语音震颤增强","叩诊右肺呈浊音","右侧肋间隙丰满"],"a":2,"e":"中等量胸腔积液时液体隔开肺组织，患侧呼吸运动受限、语音震颤减弱、叩诊浊音、肋间隙饱满，纵隔与气管被推向健侧。语音震颤增强见于肺实变或接近胸膜的巨大空腔。"},{"q":"患者，男，36岁。发作性胸痛1年，M型超声心动图检查，可见室间隔与左室后壁之比为1.6∶1，左室流出道28mm，SAM现象阳性。下列哪项体征具有诊断意义","o":["心尖区舒张中晚期隆隆样杂音，左侧卧位时增强","主动脉瓣第二听诊区舒张期叹气样杂音，呼气末增强","肺动脉瓣舒张期吹风样递减型杂音，卧位时增强","胸骨左缘第3、4肋间收缩期杂音，VALSALVA动作时增强","胸骨左缘第4、5肋间舒张期隆隆样杂音，吸气时增强"],"a":3,"e":"室间隔非对称性肥厚伴SAM征为肥厚型梗阻性心肌病的特征，杂音位于胸骨左缘第3、4肋间，Valsalva动作使左室容量减少、梗阻加重而杂音增强。主动脉瓣狭窄的杂音在Valsalva动作时减弱。"},{"q":"患者，男，40岁。突发性上腹部疼痛2小时来院急诊。查体：腹部平坦，全腹均有压痛，腹部触诊呈板状，肠鸣音消失，肝浊音界缩小。该患者肠鸣音消失的主要原因是","o":["肠坏死","机械性肠梗阻","肠运动障碍","剧痛而不敢腹式呼吸","炎症刺激而致肠麻痹"],"a":4,"e":"全腹板状腹、肝浊音界缩小提示急性胃肠穿孔并发弥漫性腹膜炎，腹膜炎症刺激使肠管运动受抑制，出现麻痹性肠梗阻而肠鸣音消失。机械性肠梗阻早期肠鸣音亢进。"},{"q":"患者，女，66岁，间断低热、盗汗、咳嗽3月，需排除肺结核。若结核菌素皮试是检测哪一型超敏反应","o":["Ⅰ","Ⅱ","Ⅲ","Ⅳ","Ⅵ"],"a":3,"e":"结核菌素皮试属迟发型超敏反应，由致敏T淋巴细胞介导，为Ⅳ型超敏反应。Ⅰ型由IgE介导，Ⅲ型由免疫复合物沉积致病。"},{"q":"神经系统查体时，发现患者肢体在被动伸曲时起始阻力明显增加，终末时阻力突发减弱。考虑损伤以下哪个部位","o":["锥体束","锥体外系","小脑","周围神经","脊髓前角"],"a":0,"e":"被动伸屈肢体时起始阻力大、终末阻力突然减弱，称折刀样肌张力增高，为锥体束损害所致。锥体外系损害表现为铅管样或齿轮样强直，各方向阻力均匀一致。"},{"q":"患者，男，28岁。3年来反复上腹部疼痛伴反酸未治疗，2小时前突然上腹剧痛，深呼吸时腹痛加重，出冷汗，来诊。此时最应注意的体征是","o":["肠鸣音是否亢进","肝浊音界是否消失","腹壁有否柔韧感","胃泡鼓音区是否扩大","前倾位腹痛是否减轻"],"a":1,"e":"长期规律性上腹痛突发持续剧痛伴板状腹，应警惕消化性溃疡急性穿孔，查肝浊音界是否消失最有意义。膈下积气使肝浊音界缩小或消失而代之以鼓音。"},{"q":"患者，男，25岁。全身反复皮疹3年，冬天加剧，夏日缓解，自觉瘙痒。查体发现头皮及躯干、四肢伸侧散在圆形胡豆至胡桃大小的红色斑丘疹，上附白色小片鳞屑，刮去鳞屑，基底潮红，少许出血点，无渗出。诊断考虑","o":["季节性皮炎","银屑病","神经性皮炎","头癣","湿疹"],"a":1,"e":"冬季加重、夏季缓解的红色斑丘疹覆银白色鳞屑，刮去鳞屑可见薄膜现象与点状出血，为银屑病特征。湿疹渗出明显、瘙痒剧烈，无银白色鳞屑。"},{"q":"患者，女，50岁，发现血脂升高、大量蛋白尿、水肿1年，诊断为肾病综合征，该患者尿中不可见的是","o":["透明管型","白细胞管型","肾小管上皮细胞管型","蜡样管型","脂肪管型"],"a":1,"e":"肾病综合征可见透明管型、脂肪管型、蜡样管型及肾小管上皮细胞管型。白细胞管型提示肾盂肾炎等肾间质化脓性炎症，不属肾小球病变的表现。"},{"q":"患者，男，32岁，因咽痛伴吞咽困难3天入院。查体：咽红，双侧扁桃体肿大超过咽腭弓，扁桃体隐窝内可见少许黄白色分泌物。该患者扁桃体为","o":["无明显肿大","Ⅰ度肿大","Ⅰ度与Ⅱ度之间","Ⅱ度肿大","Ⅲ度肿大"],"a":3,"e":"扁桃体肿大超过咽腭弓但未达咽后壁中线为Ⅱ度，Ⅰ度不超过咽腭弓，Ⅲ度达咽后壁中线。隐窝内黄白色分泌物提示急性化脓性炎症。"},{"q":"患者，男，32岁，因高楼跌下致多发伤就诊。查体：神志清楚，下腹部压痛，下肢肌力肌张力正常。观察2小时后，患者诉上厕所尿不出，查体在耻骨上触及肿胀的膀胱，尿道口出现轻微血渍。首先应采取的处理措施是","o":["试插导尿管","膀胱造瘘","逆行性尿道造影","急查膀胱镜","急诊手术"],"a":0,"e":"下腹部外伤后出现排尿困难、膀胱胀满且尿道口带血，提示后尿道损伤，应先行试插导尿管引流并起支撑作用。试插失败时再行尿道造影或耻骨上膀胱穿刺。"},{"q":"患者，男，73岁，基础风湿性心脏病、二尖瓣狭窄，间断活动后气短数年来诊，入室心电图如下所示，进一步需完善","o":["B型脑钠肽","冠状动脉CTA","超声心动图","动态心电图","胸部正侧位"],"a":2,"e":"风湿性二尖瓣狭窄出现活动后气短，提示肺淤血及肺动脉高压，需超声心动图评估瓣口面积、跨瓣压差与心功能，为选择干预方式提供依据。瓣口面积是判断狭窄程度的关键指标。"},{"q":"患者，男，60岁，出现进行性排尿困难，最常见的原因是","o":["前列腺癌","前列腺增生","膀胱颈纤维性增生","膀胱结石","尿道结石"],"a":1,"e":"老年男性尿线变细、进行性排尿困难最常见于良性前列腺增生，增大的前列腺压迫尿道所致。前列腺癌多伴结节、质硬及PSA升高，膀胱结石表现为尿流突然中断。"},{"q":"患者，男，36岁。水肿，尿少1周，血压120/80mmHg。尿常规：蛋白（＋＋＋＋），血浆白蛋白25g/L，24小时尿蛋白定量为9g。最可能的诊断是","o":["右心衰竭","肝硬化","肾病综合征","重度营养不良","急性肾炎综合征"],"a":2,"e":"大量蛋白尿超过3.5g/d、血浆白蛋白低于30g/L，伴水肿与高脂血症，构成肾病综合征的诊断要素。急性肾炎综合征以血尿、高血压为主，尿蛋白多低于3.5g/d。"},{"q":"患者，男，18岁。身高183cm，体重75kg。实验室检查：空腹血糖6.9mmol/L，2次餐后2小时血糖15.3mmol/L，血胰岛素增高。该患者最可能的诊断是","o":["1型糖尿病","胰岛素分泌不足为主的2型糖尿病","胰岛素抵抗为主的2型糖尿病","糖耐量减低","空腹血糖减损"],"a":2,"e":"两次餐后2小时血糖均≥11.1mmol/L可诊断糖尿病，患者体型正常而胰岛素水平升高，提示以胰岛素抵抗为主。1型糖尿病胰岛素绝对缺乏，胰岛素水平降低。"},{"q":"患者，男，60岁，2型糖尿病病史10年。自行停用胰岛素后出现流涕，呕吐，腹泻，血气分析可见酸中毒。该患者最可能出现的呼吸节律改变是","o":["潮式呼吸","叹气样呼吸","抑制性呼吸","端坐呼吸","Kussmaul呼吸"],"a":4,"e":"停用胰岛素后出现呕吐、腹泻及酸中毒，为糖尿病酮症酸中毒。代谢性酸中毒时深长而规则的Kussmaul呼吸通过排出CO2进行代偿。潮式呼吸见于中枢性呼吸抑制。"},{"q":"患者，男，48岁，10年少量饮酒史。近1个月上腹疼痛，饥饿时加重，呈现疼痛－进食－缓解的规律。最可能的诊断是","o":["食管炎","十二指肠球炎","胆囊炎","慢性胃炎","十二指肠溃疡"],"a":4,"e":"饥饿时疼痛、进食后缓解的节律提示十二指肠溃疡，其疼痛规律为疼痛-进食-缓解。胃溃疡多为餐后半小时至1小时疼痛，呈进食-疼痛-缓解。"},{"q":"患儿，男，1岁。额、顶、颞及枕部突出膨大呈圆形，颈静脉充盈，对比之下颜面很小，双目下视，巩膜外露。该患儿的诊断为","o":["小儿佝偻病","变形性骨炎","脑积水","肢端肥大症","马方综合征"],"a":2,"e":"额、顶、颞及枕部膨大呈圆形，颜面相对较小，双目下视、巩膜外露呈落日现象，为巨颅表现，见于脑积水。方颅见于小儿佝偻病或先天性梅毒。"},{"q":"患者，女，24岁，发热10天，右侧胸痛，胸片示右胸腔中等量积液，则胸部叩诊可发现的阳性体征不包括","o":["Damoiseau线","Garland三角区","Traube区增大","Skoda浊鼓音区","Grocco三角区"],"a":2,"e":"中等量胸腔积液时积液上界呈外高内低的弧形线，可形成Garland三角、Damoiseau线、Skoda浊鼓音区及Grocco三角等体征。Traube鼓音区位于左腋前线下方胃泡处，右胸腔积液不使其增大。"},{"q":"患者，男，70岁，进行性吞咽困难2个月入院。胃镜提示食管中下段不规则充盈缺损，管壁僵硬，病变段长约5.5cm。查见哪种浅表淋巴结肿大对诊断意义最大","o":["颈前后淋巴结","耳前后淋巴结","Virchow淋巴结","右锁骨上淋巴结","腋窝淋巴结"],"a":2,"e":"食管中下段癌经胸导管转移至左锁骨上淋巴结，该处为胸导管入颈静脉角处，肿大者称Virchow淋巴结，是胃癌、食管癌转移的重要标志。右锁骨上淋巴结转移多见于肺癌。"},{"q":"患者，男，24岁。数日前去公共泳池游泳，后出现尿急、尿频、尿痛等症状，医生疑为细菌性尿道炎。采集清洁中段尿进行细菌检查，常规培养条件为","o":["需氧培养","厌氧培养","微需氧培养","二氧化碳培养","含高浓度氢气的空气"],"a":0,"e":"尿液细菌培养以需氧培养为常规，泌尿系感染的主要病原体为大肠埃希菌等兼性需氧革兰阴性杆菌。厌氧培养仅用于怀疑厌氧菌感染的特定情况。"},{"q":"老年患者，有糖尿病史12年，糖尿病视网膜病变1年，查尿常规正常。为尽早发现患者糖尿病肾脏损害，应选择下列哪项检查协助诊断","o":["尿微量清蛋白","24h尿蛋白定量","尿液浓缩稀释功能","尿渗透压","尿比重"],"a":0,"e":"糖尿病患者尿常规蛋白阴性时尿微量清蛋白已可升高，是发现早期糖尿病肾病最敏感的指标。24小时尿蛋白定量在常规蛋白阴性时不够灵敏。"},{"q":"患者，男，3年前因高热、咳痰、咳嗽、胸痛，诊断为肺炎。10天前出现高热，咳嗽、咳痰，门诊诊断为肺炎。病历书写时，你认为3年前的肺炎应写入","o":["主诉","现病史","既往史","个人史","一般项目"],"a":2,"e":"既往史记录患者过去的健康与疾病情况，已治愈的疾病归入既往史，本次患病经过与症状演变写入现病史。故数年前的肺炎应列为既往史。"},{"q":"患者，男，65岁。着凉后出现发热、咳嗽、咳痰、呼吸困难。既往慢性阻塞性肺疾病病史15年。该患者不可能出现的体征是","o":["桶状胸","听诊可闻及湿啰音","叩诊呈过清音","气管居中","管性呼吸音"],"a":4,"e":"COPD患者因气道阻塞、肺泡弹性减退及肺过度充气，出现桶状胸、叩诊过清音、呼吸音减弱，急性加重时可闻及干湿啰音，气管仍居中。管性呼吸音见于肺实变。"},{"q":"24岁男性，发热、咳嗽1周来诊。下述问诊问题不恰当的是","o":["发烧有几天了","有没有咯血","咳嗽什么情况下重","体温最高多少","咳嗽有没有时间规律"],"a":1,"e":"问诊应使用通俗语言，避免医学术语造成误解，患者多不理解“咯血”，宜问“痰里有没有血”。发热与咳嗽的起病时间、诱因及规律均属应问内容。"},{"q":"患者，男，40岁，腹痛、发热、皮肤黄染入院。既往胆道疾病病史多年。查体有少量腹腔积液。诊断为急性化脓性梗阻性胆管炎。那么该患者腹腔积液LDH含量可能为","o":["＜100U/L","＜150U/L","＜200U/L","＞200U/L","＞300U/L"],"a":3,"e":"化脓性梗阻性胆管炎所致腹腔积液为渗出液，LDH＞200U/L、积液LDH与血清LDH比值＞0.6，蛋白及细胞数均高。漏出液LDH＜200U/L。"},{"q":"患者，32岁，女。消瘦、怕热、多汗半年余，突眼1个月就诊。查体：T 36.5℃，P 98次/min，R 22次/min，BP 120/62mmHg。甲状腺检查发现甲状腺肿大，但未超过胸锁乳突肌外缘。下列说法错误的是","o":["该患者最可能诊断是甲亢","该患者甲状腺Ⅱ度肿大","该患者甲状腺Ⅲ度肿大","该患者甲状腺上可能听到收缩期动脉杂音","该患者甲状腺可能触及震颤"],"a":2,"e":"甲状腺肿大未超过胸锁乳突肌外缘为Ⅱ度，超过外缘为Ⅲ度。甲亢时腺体血流增多，可闻及收缩期动脉杂音并触及震颤，本例不应判定为Ⅲ度。"},{"q":"患者，女，48岁。反复心悸，持续时间不等。体格检查示心率150次/min，心律不齐，第一心音强弱不等。下列哪种情况患者不能使用胺碘酮","o":["P波等电位线消失","RR间期不等","QTc 560ms","QRS波时限130ms","心动过速时可见“R-ON-T”现象"],"a":2,"e":"QTc＞500ms时胺碘酮进一步延长心室复极，易诱发尖端扭转型室速，为用药禁忌。该药可用于房颤复律与维持窦律，QRS增宽或RR间期不等并非禁忌。"},{"q":"一患儿郊游后出现鼻痒、流涕，第2天出现呼吸困难、不能平卧。查体：胸廓饱满，两肺满布大量干鸣音，可能出现","o":["触觉语颤增强","两肺叩诊浊音","触觉语颤减弱","两肺叩诊实音","两肺听觉语颤增强"],"a":2,"e":"支气管哮喘急性发作时气道广泛痉挛、肺过度充气，语音传导减弱，故触觉语颤减弱、叩诊过清音、两肺满布干啰音。语颤增强见于肺实变。"},{"q":"患者，男，22岁，头痛伴畏寒、发热5天入院。查体：胸腹部可见散在数十个鲜红色圆形斑疹，压之皮疹可消退。该患者的诊断可能是","o":["流行性脑脊髓膜炎","伤寒","猩红热","风疹","丹毒"],"a":1,"e":"胸腹部散在鲜红色圆形斑疹、压之退色为玫瑰疹，是伤寒的特征性皮疹，多于病程第7～14日出现。猩红热为弥漫性充血性皮疹。"},{"q":"32岁男性患者，腹痛来诊，下列问诊不恰当的是","o":["您哪儿不舒服","您腹痛有多久","您什么时间开始起病的","您大便是黑色的吗","您曾经有过类似的腹痛吗"],"a":3,"e":"问诊宜先开放后封闭，避免诱导性提问，“大便是黑色的吗”易使患者顺着医生的暗示作答。应先询问大便颜色再行核实。"},{"q":"患者，男，38岁，急性白血病。化疗后全血细胞减少，出现发热，血浆降钙素原水平200ng/ml，血压90/50mmHg，考虑感染性休克可能。以下哪种检查结果不会出现","o":["血浆组织型纤溶酶原激活剂测定减低","ATPP延长","纤维蛋白原下降","3P试验阴性","D-二聚体增高"],"a":0,"e":"感染性休克并发DIC时纤溶系统激活，t-PA活性升高而非减低。DIC消耗凝血因子使APTT延长、纤维蛋白原下降，D-二聚体升高而3P试验可呈阴性。"},{"q":"患者，男，30岁。骨折后进行手术，术后出现大片皮肤瘀斑、血肿、关节出血，可能原因是","o":["血管舒缩功能紊乱","血小板质的异常","血小板量的减少","凝血因子缺乏","弥散性血管内凝血"],"a":4,"e":"骨折术后出现大片瘀斑、血肿及关节出血，提示弥散性血管内凝血，创伤使组织因子大量释放激活凝血系统，凝血因子与血小板消耗而致出血。血友病为自幼发病。"},{"q":"患者，女，45岁，体检发现尿糖（＋＋＋），为区别该患者肾性糖尿和糖尿病性糖尿，应加做","o":["尿定性实验","空腹血糖及糖耐量实验","尿沉渣镜检","尿蛋白分析","超声检查"],"a":1,"e":"尿糖阳性而血糖正常者为肾性糖尿，系肾糖阈降低所致；血糖升高者为糖尿病性糖尿。测空腹血糖及糖耐量试验可直接判断血糖水平而加以鉴别。"},{"q":"患儿，男，1岁，出生1个月时发现心脏杂音。查体：于胸骨左缘2肋间及3/6级粗糙收缩期杂音，伴P2增强，S2固定分裂。患儿最可能是","o":["生理性杂音","肺动脉瓣狭窄","肺动脉瓣关闭不全","房间隔缺损","室间隔缺损"],"a":3,"e":"胸骨左缘第2肋间收缩期杂音伴P2增强及S2固定分裂是房间隔缺损的典型听诊表现，右心室容量负荷增加使肺动脉瓣关闭延迟，且分裂不受呼吸影响。"},{"q":"患者，男，60岁。面黄、消瘦2个月。查体：皮肤巩膜黄染，腹软，肝脾不大。腹部B超见胰腺头部占位性病变，胆管扩张。该患者尿中主要的胆红素是","o":["游离胆红素","胆红素-Y蛋白","葡萄糖醛酸胆红素","胆红素-清蛋白复合物","胆红素-Z蛋白"],"a":2,"e":"胰头占位压迫胆总管致梗阻性黄疸，结合胆红素反流入血，其为水溶性，可经肾小球滤过，故尿中出现葡萄糖醛酸胆红素。游离胆红素与白蛋白结合，不能从尿排出。"},{"q":"患者，男，35岁。上腹部规律性疼痛5年，多于秋季出现。1周以来每晚12点左右出现上腹痛。3小时前，患者进食后突然出现持续性剧烈腹痛，以上腹正中为重，不敢呼吸。腹部查体：板状腹，全腹压痛（＋），反跳痛（＋），肝浊音界消失，肠鸣音减弱。该患者可能的诊断为","o":["急性胰腺炎","肠梗阻","十二指肠球部溃疡急性穿孔","幽门梗阻","急性胆囊炎"],"a":2,"e":"夜间空腹痛提示十二指肠溃疡，突发持续剧痛伴板状腹、肝浊音界消失及肠鸣音减弱，为溃疡急性穿孔致弥漫性腹膜炎。急性胰腺炎多有酗酒或胆石诱因，血淀粉酶升高。"},{"q":"中年女性，咳嗽、右侧胸痛3天。查体：右侧可闻及胸膜摩擦音。该患者首先应考虑下列哪种疾病","o":["右侧自发性气胸","右侧少量胸腔积液","右下肺不张","右侧大量胸前积液腔","慢性支气管炎"],"a":1,"e":"胸膜摩擦音是纤维蛋白性胸膜炎的体征，积液量少时脏、壁层胸膜仍能相互摩擦而闻及，积液增多将两层胸膜分开后摩擦音消失。气胸叩诊为鼓音。"},{"q":"患者，男，17岁。受凉后咽痛、发热，10天后出现颜面及双下肢水肿，查尿蛋白（＋＋），尿红细胞满视野，红细胞异形率达80%。最可能的诊断是","o":["紫癜性肾炎","急性肾小球肾炎","感染性间质性肾炎","败血症","狼疮性肾炎"],"a":1,"e":"链球菌感染后1～3周出现血尿、蛋白尿与水肿，尿红细胞异形率＞80%提示肾小球源性血尿，符合急性肾小球肾炎。紫癜性肾炎须有皮肤紫癜及相应病史。"},{"q":"患者，男，70岁。因头晕胸痛半月来诊，既往有10年高血压病史。查体血压160/75mmhg，心率102次/min，S1增强，心界左侧扩大，伴抬举样搏动。该患者叩诊心界可见","o":["梨形心","普大心","烧瓶心","心界随体位呈动态变化","靴型心"],"a":4,"e":"长期高血压致左心室肥厚扩大，心浊音界向左下扩大、心腰凹陷，形成靴形心，心尖搏动呈抬举样。梨形心见于二尖瓣狭窄，烧瓶心见于心包积液。"},{"q":"患者，女，66岁，既往冠状动脉粥样硬化性心脏病史30年。今晨练后出现胸痛，疼痛后3小时入院，心电图如图，最可能的诊断为","o":["急性前壁心肌梗死，陈旧性下壁心肌梗死","急性前间壁、前壁心肌梗死","变异性心绞痛","急性下壁心肌梗死，陈旧性前壁心肌梗死","陈旧性前壁、下壁心肌梗死伴前壁室壁瘤形成"],"a":1,"e":"官方题库缺失图片"},{"q":"面部不适患者入院进行神经系统查体，发现右侧面部痛觉减退，右侧咀嚼肌无力。考虑损伤以下哪条神经","o":["右侧面神经","右侧舌咽神经","右侧三叉神经","右侧动眼神经","右侧副神经"],"a":2,"e":"三叉神经为混合性神经，其运动支支配咀嚼肌，感觉支分布于面部。右侧面部痛觉减退伴右侧咀嚼肌无力，提示右侧三叉神经损害。面神经主要支配面部表情肌。"},{"q":"患者，男，47岁，发热1周，查见颈部多处淋巴结无痛性肿大，检查方法错误的是","o":["可站在被检查者前面，手指紧贴检查部位","由浅入深滑动触诊","触诊时让被检查者头稍高，或偏向检查侧的对侧","检查时注意淋巴结的部位、大小、硬度、压痛、活动度等","颈部检查完后，还要检查其他部位"],"a":2,"e":"检查颈部淋巴结应嘱患者头稍低或偏向检查侧，使皮肤与肌肉松弛以利触诊。头稍抬高或偏向对侧会使肌肉紧张，妨碍触诊。"},{"q":"患者，男，42岁，上腹烧灼样痛，进食后可缓解，反酸。最可能的诊断是","o":["胆囊炎","急性胰腺炎","慢性痢疾","肠梗阻","消化性溃疡"],"a":4,"e":"上腹烧灼样痛、进食后缓解并伴反酸，是消化性溃疡的典型症状，胃酸对溃疡面的刺激是疼痛的主要机制。胆囊炎疼痛多位于右上腹并放射至右肩背部。"},{"q":"A患者由于肾小球肾炎引起的血尿，B患者由于溶血引起的血红蛋白尿，二者尿液颜色接近，用下列哪个实验可以加以区分","o":["尿液颜色观察","尿胆原测试实验","尿沉渣镜检","尿三杯实验","尿潜血实验"],"a":2,"e":"血红蛋白尿系红细胞破坏后游离血红蛋白经肾排出，尿沉渣中无红细胞；血尿者尿沉渣镜检可见大量红细胞，且变形红细胞提示肾小球源性，二者据此可明确区分。"},{"q":"患儿，男，5岁，鼻出血1天。有反复皮肤黏膜出血病史。血常规基本正常，出血时间延长，APTT、PT基本正常，血管性血友病因子减低，FⅧ:C降低，该患者最可能的诊断是","o":["血小板无力症","血友病A","血友病B","血管性血友病","过敏性紫癜"],"a":3,"e":"出血时间延长而血小板计数正常、APTT与PT基本正常，伴血管性血友病因子减低及FⅧ:C降低，为血管性血友病的典型改变。血友病A仅FⅧ:C降低，血管性血友病因子正常。"},{"q":"患者，男，23岁。右胸刀刺伤1小时，呼吸困难、发绀，胸部广泛皮下气肿，脉细速，右胸叩诊鼓音，呼吸音消失，气管左偏。该患者最可能的诊断是","o":["支气管哮喘","大叶性肺炎","急性左心衰竭","气胸","肺不张"],"a":3,"e":"胸部刀刺伤后呼吸困难、发绀、广泛皮下气肿，患侧叩诊鼓音、呼吸音消失、气管向健侧移位，为外伤性气胸。肺不张叩诊浊音且气管向患侧移位。"},{"q":"患者，男，76岁。长期慢性阻塞性肺疾病史，因“基底肺炎”入院。动脉血气：pH 7.25，PaCO2 90mmHg，HCO3－ 38mEq/L，PaO2 34mmHg。该患者可能发生了","o":["急性呼吸性酸中毒并发慢性呼吸性酸中毒","呼吸性碱中毒失代偿期","代谢性酸中毒部分代偿期","代谢性碱中毒部分代偿期","抽取的是静脉血"],"a":0,"e":"COPD患者长期CO2潴留使HCO3-代偿性升高至38mEq/L，此次pH 7.25、PaCO2 90mmHg提示在慢性呼吸性酸中毒基础上急性加重。代谢性酸中毒时HCO3-应降低。"},{"q":"患者，男，56岁，间断大便带血。查体：心肺及腹部无异常。拟进行直肠指诊（肛诊）检查，下列描述正确的是","o":["可确定乙状结肠内病变","可采取肘膝位，左侧卧位，仰卧位","先检查尿道括约肌紧张度","剧烈触痛提示有痔疮出血","触及包块即为癌性肿块"],"a":4,"e":"官方答案为【触及包块即为癌性肿块】，但依据教材，正确答案为【可采取肘膝位，左侧卧位，仰卧位】。直肠指诊可依病情选用肘膝位、左侧卧位或仰卧位，触及包块须结合硬度、活动度及活检判断性质，不能直接断为癌。"},{"q":"患者，女，45岁。平日素食。查体：双手指甲呈匙状。该患者最可能的病因是","o":["组织缺钙","组织缺镁","组织缺铁","组织缺锌","外伤"],"a":2,"e":"指甲变薄、中央凹陷而边缘翘起呈匙状，即反甲，是缺铁性贫血的典型体征，与组织缺铁致上皮营养障碍有关。缺钙主要引起手足搐搦与骨软化。"},{"q":"患者，女，36岁，诊断为急性白血病（M4），在中华骨髓库配型成功，准备骨髓移植。预防骨髓移植GVHR有效方法是","o":["ABO血型配型","减少供体骨髓中的T细胞","HLA配型","减少供体骨髓中的B细胞","诱导特异性免疫耐受"],"a":4,"e":"GVHR的本质是供体T细胞识别宿主同种异型抗原后增殖并攻击宿主组织，诱导供者对宿主移植抗原的特异性免疫耐受可使植入物存活而不发生GVHR。ABO配型仅防溶血反应。"},{"q":"患者，男，45岁，主诉头痛1个月。查体：BP 170/90mmHg，心界不大，心率75次/min，律齐有力，未及明确杂音，未发现神经系统异常。患者还可能有的体征是","o":["P2增强","上腹部血管杂音","靴形心","S2通常分裂","双下肢水肿"],"a":2,"e":"长期高血压使左心室肥厚、心腔扩大，心浊音界向左下扩大、心腰凹陷呈靴形，为左心室增大的典型改变。主动脉瓣关闭不全亦可出现靴形心。"},{"q":"患者，女，24岁。近2个月来找工作不顺利，常出现呼吸加快，伴叹气样呼吸，偶伴手足搐搦。该患者出现的呼吸困难最常见于下列哪种疾病","o":["脑出血","脑外伤","焦虑症","休克","脑膜炎"],"a":2,"e":"呼吸快而浅、伴叹息样呼吸及手足搐搦是精神性呼吸困难的表现，过度通气致呼吸性碱中毒而引起搐搦，常见于焦虑症与癔症。颅脑疾病所致呼吸困难另有定位体征。"},{"q":"患者，女，22岁。受凉后出现咽痛、发热1周。查体示咽充血，扁桃体Ⅱ度肿大。医生建议查血清抗“O”抗体，其检测结果增高的临床意义，下列哪项是错误的","o":["近期A群溶血性链球菌感染及链球菌感染相关疾病","抗体由高滴度逐步下降时，可认为疾病好转","抗体滴度恒定在高水平时，多为相关疾病的活动期","特异性高，无假阳性","假阴性可见于金葡菌感染或铜绿假单胞菌感染时"],"a":3,"e":"抗链球菌溶血素O抗体检测存在假阳性，高胆固醇血症、肝炎及标本污染均可致滴度升高，故“特异性高、无假阳性”的说法错误。抗体滴度逐步下降提示病情好转。"},{"q":"患者，男，67岁，1个月来鲜血便伴黏液，近来消瘦明显。查体：腹软，肝、脾未及，腹部未及包块。首选的检查是","o":["腹部超声","腹部CT","肛门指诊","胃肠透视","腹平片"],"a":2,"e":"中老年出现鲜血便伴黏液及消瘦，应首先行肛门指诊，可直接触及直肠下段及肛管病变，简单易行且阳性率高。直肠癌多数位于指诊可及范围内。"},{"q":"一个医生给患者检查时轻夹患者手指向上、下移动，询问患者“向上”“向下”。这主要是检测","o":["运动觉","位置觉","触觉","震动觉","实体觉"],"a":0,"e":"轻夹手指并上下移动、令受检者说出方向，检测的是运动觉，属深感觉，其传导通路为脊髓后索。位置觉是判断肢体所处姿势，触觉与实体觉属皮质感觉。"},{"q":"患者，男，65岁。尿线变细，排尿不畅5年。查体：前列腺触诊发现前列腺略增大，中央沟变浅，表面光滑、质韧，未及无压痛及粘连。该患者最可能的诊断是","o":["正常前列腺","急性前列腺炎","良性前列腺肥大","前列腺癌","前列腺钙化"],"a":2,"e":"前列腺增大、中央沟变浅、表面光滑质韧且无压痛及粘连，是良性前列腺增生的触诊特点。前列腺癌质硬、表面有硬结节；急性前列腺炎有明显压痛。"},{"q":"患儿，男，5岁。于胸骨左缘第2肋间闻及S2分裂，吸气相明显，呼气相消失，则最可能是","o":["S2固定分裂","肺动脉高压","S2生理性分裂","房间隔缺损","S2反常分裂"],"a":2,"e":"青少年吸气时胸腔负压增大、右心回心血量增多，肺动脉瓣关闭延迟，S2分裂于吸气相明显、呼气相消失，属生理性分裂。固定分裂见于房间隔缺损。"},{"q":"患者，女，18岁，2月前重感冒，近1月来心悸气短，进行性加重。查体：BP 90/60mmhg，交替脉，心界双侧扩大，心律120次/min，可闻及舒张期奔马律，心音低弱，未及确切杂音。则诊断最可能是","o":["甲状腺功能低下","缩窄性心包炎","心包积液","大面积心肌梗死","心肌炎"],"a":4,"e":"病毒感染后1～3周出现心悸气短、心界扩大、交替脉、舒张期奔马律及心音低弱，为心肌炎的典型表现。心包积液心音遥远但无奔马律，心界随体位改变。"},{"q":"患者，女，16岁，未婚，因月经期鼻出血3个月就诊。该患者于同年6月月经初潮，连续3个月均出现月经期鼻出血，持续4～5天，总出血约100ml。应考虑诊断","o":["原发性高血压","再生障碍性贫血","维生素K缺乏","维生素C缺乏","子宫内膜异位症"],"a":4,"e":"子宫内膜异位灶可种植于鼻黏膜，随月经周期激素波动而出血，表现为周期性经期鼻出血，属盆腔外子宫内膜异位症。凝血因子缺乏者出血无周期性。"},{"q":"患者，男，46岁。诉平日尿量增多而比重增高，空腹血糖10.8mmol/L。考虑的疾病是","o":["尿崩症","糖尿病","慢性肾盂肾炎","急性肾小球肾炎","急性肾衰竭"],"a":1,"e":"空腹血糖10.8mmol/L已达糖尿病诊断标准，血糖超过肾糖阈使尿量增多、尿比重增高，为渗透性利尿所致。尿崩症尿比重降低而非增高。"},{"q":"患者，女，60岁。体检时发现空腹血糖6.4mmol/L，作葡萄糖耐量试验，OGTT 2hPG为8、6mmol/L。下列叙述正确的是","o":["可诊断糖尿病","可排除糖尿病","应重复葡萄糖耐量试验","患者空腹血糖过高","患者糖耐量减低"],"a":4,"e":"空腹血糖6.4mmol/L属空腹血糖受损，OGTT 2小时血糖8.6mmol/L处于7.8～11.1mmol/L之间，诊断为糖耐量减低。2小时血糖≥11.1mmol/L方可诊断糖尿病。"},{"q":"患者，男，64岁。胸骨后疼痛伴痰中带血2周，近2个月体重减轻2kg。查体：T 36.2℃，双肺呼吸音粗，未闻及干湿性啰音。患者最可能的诊断是","o":["急性心肌梗死","肺癌","食管炎","肺梗死","纵隔肿瘤"],"a":1,"e":"中年男性胸骨后疼痛伴痰中带血及体重下降，为支气管肺癌的典型表现，肿瘤侵犯支气管黏膜致少量咯血。急性心肌梗死以剧烈胸痛为主，多无血痰。"},{"q":"患者，男，51岁，基础高血压病史，长期吸烟。胸骨后疼痛1小时来诊，入室心电图如图所示，目前发病血管首先考虑","o":["左主干","左前降支","左旋支","右冠脉","左乳内动脉"],"a":0,"e":"官方题库缺失图片"},{"q":"患者，女，28岁，已婚。因消瘦、乏力、多食、心悸3个月就诊。查体：甲状腺Ⅱ度肿大，双上极可闻及血管杂音。该患者不会出现以下哪项阳性体征","o":["眼球突出","Stellwag征","Mobius征","眼球震颤","Joffory征"],"a":3,"e":"甲亢可有眼球突出及Stellwag征（瞬目减少）、Mobius征（辐辏减弱）、Joffroy征（上视时额纹消失）等眼征，眼球震颤不属甲亢眼部表现，多见于耳源性眩晕与小脑病变。"},{"q":"患者，男，62岁。反复咳嗽、咳痰3周，发热1周。查体双肺散在干湿性啰音。为确定何种细菌感染，应首选哪项检查","o":["痰细菌检查","痰物理性质检查","X片检查","血清学实验","组织病理学检查"],"a":0,"e":"确定致病菌需行痰涂片革兰染色及痰培养，可明确菌种并做药敏试验。X线仅显示肺部病变部位与形态，血清学与病理检查不能直接确定细菌种类。"},{"q":"某3岁患儿，额、顶、颞及枕部突出膨大呈圆形，颈静脉充盈，颜面显小，双目下视，巩膜外露。该患儿最可能的疾患是","o":["呆小病","佝偻病","唐氏综合征","脑积水","先天性梅毒"],"a":3,"e":"巨颅伴颜面相对较小、双目下视巩膜外露的落日现象，为颅内压增高压迫眼球所致，见于脑积水。佝偻病表现为方颅而非巨颅。"},{"q":"患者，女，38岁。于卧位起立时突然感觉头晕。查体：站立位BP 50/40mmHg，心肺无异常。有关这种情况的描述错误的是","o":["发生于某些长期站立于固定位置及长期卧床者","发生于服用氯丙嗪、胍乙啶等药物者","发生于交感神经切除术后患者","是由于各种刺激通过迷走神经反射引起","由于卧位或蹲位突然站起时发生"],"a":3,"e":"该表现属直立性低血压，系体位骤变时交感神经调节失效、血管收缩不足致脑供血减少。长期卧床、交感神经切除术后及应用氯丙嗪、胍乙啶均可致此，与迷走神经反射无关。"},{"q":"患者，男，20岁。腰骶、腰背部疼痛2年，伴晨僵，弯腰受限。查体见脊柱生理弯曲消失。最可能的疾病是","o":["脊椎结核","类风湿关节炎","强直性脊柱炎","腰椎间盘突出症","脊椎肿瘤"],"a":2,"e":"青年男性腰骶部疼痛伴晨僵、弯腰受限及脊柱生理弯曲消失，为强直性脊柱炎的表现，骶髂关节受累最早。腰椎间盘突出症多伴下肢放射痛。"},{"q":"患者，男，40岁，有高血压和大量吸烟病史。突发胸闷3小时就诊，心电图如图所示，首先考虑","o":["急性前壁心肌梗死","急性前间壁心肌梗死","变异型心绞痛","急性广泛前壁心肌梗死","急性重症心肌炎"],"a":3,"e":"官方题库缺失图片"},{"q":"患者，男，68岁，发现黄疸1个月伴恶心、发热。经抗感染治疗后恶心、发热等症状消失，但黄疸逐渐加深，胆囊显著增大，近2日出现呕少量血。该患者最可能的诊断是","o":["急性胰腺炎","急性胆囊炎","胰头肿瘤","胆囊癌","胆总管结石"],"a":2,"e":"黄疸进行性加深伴胆囊无痛性显著肿大，即库瓦西耶征阳性，提示胰头癌压迫胆总管。胆总管结石虽可致黄疸，但胆囊常因慢性炎症纤维化而不肿大。"},{"q":"患者，男，20岁，平时身体健康。右侧肋骨骨折1小时入院，面色苍白，胸痛、气促。查体：呼吸35次/min，心率105次/min，血压95/58mmHg，气管左移，右肺叩诊鼓音，右肺呼吸音明显降低。该患者出现呼吸困难最可能的原因是","o":["急性左心衰竭","大叶性肺炎","急性冠脉综合征","主动脉夹层","气胸"],"a":4,"e":"肋骨骨折后突发胸痛、气促，患侧叩诊鼓音、呼吸音明显降低、气管移向健侧，为骨折刺破胸膜所致的气胸，呼吸困难的直接原因是肺受压萎陷。"},{"q":"患者，女，因下肢发凉入院检查。医生给患者全身涂抹碘、蓖麻油和酒精混合制剂，之后再敷淀粉，应用毛果芸香碱发汗。该医生给患者做的检查是以下哪项检查","o":["皮肤划痕症","竖毛反应","发汗实验","病理反射","感觉平面检查"],"a":2,"e":"碘与淀粉遇汗液变蓝，皮下注射毛果芸香碱作用于交感神经节后纤维引起出汗，据此判断交感神经损害范围，即发汗试验。竖毛反射以冰块置颈后观察鸡皮。"},{"q":"患者，女，39岁，血尿2天，尿常规镜下均为畸形红细胞，但除外","o":["皱缩红细胞","大型红细胞","细胞质有葫芦状外展内有细颗粒","浅黄色双面圆盘形红细胞","胞膜破裂及部分细胞质丢失"],"a":3,"e":"肾小球源性血尿的红细胞受挤压及渗透压影响而变形，表现为皱缩、大型、胞膜破裂及芽胞样外展等畸形。浅黄色双面圆盘形为正常红细胞形态，不属畸形红细胞。"},{"q":"患者，男，46岁，突发腰痛3小时，呈剧烈绞痛。查体：急性病容，右肾区叩痛。尿常规示红细胞＋/HPF。该患者最可能的诊断是","o":["尿路结石","肾盂肾炎","急性肾炎","前列腺炎","腰椎间盘突出"],"a":0,"e":"突发腰部剧烈绞痛、肾区叩痛伴镜下血尿，为尿路结石的典型表现，结石嵌顿致输尿管痉挛而疼痛剧烈。肾盂肾炎以发热及尿路刺激征为主。"},{"q":"患儿，女，出生后30天。足月顺产，第1胎，否认有传染病接触史。入院前5天无明显诱因发热、呼吸及吞咽困难，拒乳。查体发现咽部充血红肿，扁桃体Ⅱ度肿大，并附着有难剥离的片状假膜。诊断考虑","o":["鹅口疮","慢性咽炎","急性化脓性扁桃体炎","咽白喉","急性咽炎"],"a":3,"e":"咽部片状假膜不易剥离、强行剥离易出血，是咽白喉的特征；急性化脓性扁桃体炎的分泌物易擦去且不出血。婴幼儿未接种疫苗者更应警惕白喉。"},{"q":"患者，男，26岁。2周前感冒后出现口干、多饮、多尿，未重视。1天前因口干饮用大量碳酸饮料后突发昏倒，不能正确辨别时间、地点和周围亲人，但能保持简单的精神活动。患者意识状态应诊断为","o":["昏睡","嗜睡","意识模糊","谵妄","轻度昏迷"],"a":2,"e":"能保持简单精神活动而对时间、地点、人物定向力障碍，为意识模糊。嗜睡是最轻的意识障碍，昏睡需强刺激方能唤醒，谵妄伴幻觉与躁动不安。"},{"q":"患者，女，61岁。慢性咳嗽、咳痰20年，加重伴呼吸困难3天，曾明确诊断为“慢性阻塞性肺疾病”。该患目前最有可能出现的体征是","o":["可闻及干、湿啰音","呼吸运动增强","语音共振增强","叩诊呈浊音","呼气相缩短"],"a":0,"e":"COPD急性加重时气道炎症与分泌物增多，双肺可闻及干、湿啰音，并伴桶状胸、叩诊过清音、语音共振减弱及呼气相延长。呼吸运动增强不符合肺气肿。"},{"q":"患者，男，58岁。原发性高血压5年，平时饮酒500g/d。要想评价该患者发生冠心病的风险，主要关注的脂蛋白是","o":["乳糜微粒","极低密度脂蛋白","低密度脂蛋白","高密度脂蛋白","中间密度脂蛋白"],"a":3,"e":"高密度脂蛋白参与胆固醇逆向转运，具抗动脉粥样硬化作用，其水平降低是冠心病独立的危险因素，长期大量饮酒与吸烟可使其降低，故评价风险须重点关注。"},{"q":"一患者神经系统查体发现患者右侧角膜直接对光反射消失，间接对光反射存在。考虑患者损伤的是","o":["右侧三叉神经","右侧面神经","左侧三叉神经","左侧面神经","右侧动眼神经"],"a":1,"e":"角膜反射的传入为三叉神经眼支、传出为面神经。刺激右眼角膜时右眼不闭合而左眼闭合，说明右侧面神经传出障碍，三叉神经传入完好。"},{"q":"下列哪种药物可用于本例患者发作心房颤动时的治疗","o":["毛花苷C","美托洛尔","普罗帕酮","胺碘酮","腺苷"],"a":2,"e":"普罗帕酮为ⅠC类抗心律失常药，可抑制旁路传导，适用于心房颤动的复律，尤其合并预激综合征时。毛花苷C与美托洛尔仅控制心室率，预激伴房颤时禁用洋地黄。"},{"q":"患者，男，72岁。上腹疼痛2天，发热1天，最高达38℃。下列疾病中可能性最小的是","o":["胆囊炎","十二指肠溃疡穿孔","急性心肌梗死","胰腺炎","肠结核"],"a":4,"e":"肠结核为慢性过程，主要表现为右下腹痛、腹泻与低热盗汗，不以突发上腹痛伴发热起病，故可能性最小。急性起病伴发热的上腹痛多考虑胆囊炎、胰腺炎等急症。"},{"q":"患者，女，28岁，怕热多汗伴消瘦2个月，体检颈前区肿大且可闻及血管杂音。该患者的面容可能是","o":["面色苍白，颜面水肿","面色晦暗，额部有褐色色素沉着","表情淡漠，反应迟钝呈无欲状态","面色苍白，表情疲惫","面容惊愕，眼裂增宽，目光闪亮"],"a":4,"e":"甲亢面容表现为面容惊愕、眼裂增宽、眼球突出、目光炯炯及兴奋烦躁，与甲状腺激素增多致交感神经兴奋性增高有关。黏液性水肿面容见于甲状腺功能减退症。"},{"q":"患者，男，40岁。高脂饮食后中上腹部疼痛8小时入院，淀粉酶1044U/L。患者可出现下列查体表现，除外","o":["肠鸣音减弱","腰部皮肤呈蓝色","蠕动波增加","腹式呼吸减弱","中上腹压痛"],"a":2,"e":"急性胰腺炎时腹膜后炎症刺激致肠麻痹，肠鸣音减弱、腹式呼吸减弱，中上腹压痛明显，出血坏死型可见腰部皮肤呈蓝色的Grey-Turner征。蠕动波增加见于胃肠道梗阻。"},{"q":"患者，女，55岁，8年前因“心脏病”而提前退休。入院前1日夜间于睡眠中突然憋醒，不能平卧，自觉呼吸困难。查体：心尖部可闻及舒张期隆隆样杂音，双肺布满干、湿啰音。此患者最可能咳","o":["白色泡沫样痰","粉红色泡沫样痰","黄脓痰","铁锈色痰","砖红色黏稠痰"],"a":1,"e":"急性左心衰竭肺水肿时肺泡及支气管内充满浆液性渗出，与气体混合形成粉红色泡沫样痰；二尖瓣狭窄所致肺淤血是常见基础。"},{"q":"患者，男，45岁，主诉头痛1个月。查体：BP 170/90mmHg，心界不大，心率75次/min，律齐有力，未及明确杂音，未发现神经系统异常。该患者诊断最可能是","o":["原发性高血压2级","原发性高血压1级","原发性高血压3级","单纯收缩期高血压","正常高值"],"a":0,"e":"收缩压170mmHg落在160～179mmHg区间为2级高血压，舒张压90mmHg仅1级，分级以较高者为准；非同日3次超标即可确诊。"},{"q":"6岁男童，因水肿2周就诊，外院检查发现尿蛋白阳性。为明确诊断，以下哪项检查不是首先考虑的","o":["尿常规","肾功能","24h尿蛋白定量","肾活检","血白蛋白"],"a":3,"e":"肾活检为有创检查，儿童原发性肾病综合征多对激素敏感，先行尿常规、24小时尿蛋白定量、血白蛋白及肾功能评估，疗效不佳时才考虑穿刺。"},{"q":"患者，男，20岁，突然呼吸困难来诊。查体端坐呼吸，胸廓饱满，诊断为支气管哮喘。最典型的听诊特点是","o":["双肺干啰音","双肺哮鸣音","水泡音","肺泡呼吸音增强","可听到病理性呼吸音"],"a":1,"e":"哮喘发作时气道弥漫性痉挛、黏膜水肿，呼气时气流形成湍流，故双肺满布哮鸣音且呼气相延长，为最有诊断价值的听诊特点。"},{"q":"患者，男，36岁。左胫骨骨折内固定术后3周，气促、呼吸困难4天，胸痛、咯血1天入院。查体：双肺呼吸音粗，未闻及啰音，心率98次/min，律齐，左下肢水肿。该患者首先考虑诊断为","o":["院内获得性肺炎","急性支气管炎","肺血栓栓塞症","脂肪栓塞","急性上呼吸道感染"],"a":2,"e":"长期制动使下肢静脉血流淤滞形成血栓，脱落后阻塞肺动脉即肺血栓栓塞，出现呼吸困难、胸痛、咯血及患肢水肿；脂肪栓塞多在伤后1～3天发生。"},{"q":"患者，女，36岁。劳力性心累、气短半个月。既往关节肿痛史。查体：血压110/75mmHg，脉搏85次/min，心率145次/min，心律不齐，心音强弱不等。超声心动图提示二尖瓣重度粘连，未见钙化，开放受限。患者听诊的典型杂音为","o":["心尖区全收缩期粗糙吹风样杂音向左腋下传导","心尖区舒张中晚期隆隆样杂音","心尖区舒张早期叹气样递减性杂音","胸骨左缘第3、4肋间舒张早期叹气样递减性杂音","胸骨右缘第2肋间全收缩期递增递减性杂音"],"a":1,"e":"二尖瓣开放受限即狭窄，舒张期左房血液经狭窄瓣口产生湍流，形成局限于心尖区的低调隆隆样舒张中晚期递增型杂音，左侧卧位更明显。"},{"q":"患者，男，72岁。大便秘结，便血3个月。查体：直肠指检示肛门口上5cm触及质硬结节，大小约3cm×2cm，表面凹凸不平。该患者最可能的诊断是","o":["直肠息肉","直肠癌","肛周脓肿","痔疮","直肠感染"],"a":1,"e":"质硬、表面凹凸不平的直肠内包块提示癌组织浸润生长；息肉质软可活动，痔为柔软静脉团，肛周脓肿有压痛及波动感。"},{"q":"患者，女，28岁，低热、咳嗽半个月，体检右侧Kronig峡为2cm，诊断首先考虑的是该患者的肺尖部有","o":["气胸","肺气肿","肺大疱","肺尖结核","胸膜炎"],"a":3,"e":"正常肺尖清音带即Kronig峡宽4～6cm，肺尖部结核浸润使局部含气量减少、叩诊变浊，清音带因而变窄至2cm。"},{"q":"患者，女，29岁，因发热伴关节痛2周收入院。查体见面颊局部皮肤发红、呈蝶形、未突出皮肤表面。该患者最可能的诊断是","o":["猩红热","药物疹","伤寒","麻疹","系统性红斑狼疮"],"a":4,"e":"面颊部对称性蝶形红斑、不高出皮面是系统性红斑狼疮的特征性皮损，常伴发热、关节痛和多器官损害；猩红热皮疹为弥漫充血性。"},{"q":"患者，男，57岁。剧烈头痛1小时，头痛程度较重，无减轻，伴有意识障碍。查体：T 36.2℃，颈项强直（＋）。患者最可能的诊断是","o":["病毒性脑膜炎","血管神经性头痛","蛛网膜下腔出血","肌紧张性头痛","脑肿瘤"],"a":2,"e":"无发热而突发剧烈头痛并伴意识障碍与脑膜刺激征，符合颅内血管性疾病，尤以蛛网膜下腔出血最典型；脑膜炎多有发热。"},{"q":"患者，女，20岁，因咳嗽、咳痰伴发热5天入院。胸片示右下肺斑片状浸润影、右侧少量胸腔积液。该患者可能采取的体位是","o":["自主体位","被动体位","强迫侧卧位","强迫仰卧位","强迫坐位"],"a":0,"e":"无剧烈胸痛及大量积液限制、活动自如者属自主体位；强迫侧卧位见于一侧胸膜炎或大量胸腔积液，用以减轻患侧胸廓活动。"},{"q":"患儿，女，1岁。因“呕吐2天，发热伴腹泻1天”入院。呕吐非喷射性，5～6次/d；腹泻8次/d，为稀水样便，量多；近1天尿少，无不洁饮食史。查体：T 37.8℃，P 110次/min，R 26次/min，BP 80/60mmHg，神志清，精神倦，唇干，皮肤干燥，前囟凹陷，颈软，双侧瞳孔等大等圆，对光反射灵敏，双肺呼吸音清，心音有力，心律齐，未闻及杂音，腹软，未及包块，肝肋下1cm，质软，脾未触及，肠鸣音7～8次/min，四肢暖，病理征未引出。血清电解质：血钠130mmol/L，血钾3、5mmol/L，血氯90mmol/L，HCO3-18mmol/L。尿常规：酮体＋＋。大便常规：白细胞＋。下列符合患儿表现的是","o":["中度低渗性脱水，轻度酸中毒，低钠低氯血症","重度等渗性脱水，中度酸中毒，低钠低氯血症","轻度等渗性脱水，中度酸中毒，低氯血症","中度低渗性脱水，轻度酸中毒，低钠高氯血症","重度等渗性脱水，重度酸中毒，高钠高氯血症"],"a":0,"e":"血钠130mmol/L属低渗性脱水且程度为中度，HCO3-18mmol/L轻度降低提示轻度代谢性酸中毒，血氯90mmol/L为低氯血症，三者并存。"},{"q":"一女性患者因左侧下肢麻木入院，接诊医生进行神经系统查体发现左侧腹部平肚脐以下存在痛觉减退。考虑患者损伤的是以下哪个部位","o":["皮质脊髓侧束","皮质丘脑束","脊髓丘脑侧束","脊髓丘脑前束","脊髓后索"],"a":2,"e":"痛觉与温度觉经脊髓丘脑侧束传导，一侧受损产生对侧躯体痛温觉减退；后索损害表现为深感觉障碍，皮质脊髓束损害为运动障碍。"},{"q":"患者，女，32岁，因面色出现色素斑而来皮肤科就诊。查体发现其鼻梁部皮肤出现红色斑块，病损部高起皮面并向两侧面颊部扩展。最可能是下列哪种疾病","o":["黑热病","肝脏疾病","系统性红斑狼疮","风湿性心脏病","酒渣鼻"],"a":2,"e":"鼻梁部红色斑块、高起皮面并向两侧面颊扩展为系统性红斑狼疮的特征；酒渣鼻的潮红和毛细血管扩张局限于鼻尖、鼻翼。"},{"q":"患者，男，58岁。长期抽烟，近1个月来痰中带血，体重下降，X线胸片示左上肺密度较高圆形阴影。若该患者出现浅表淋巴结肿大，最先肿大的区域是","o":["左颈后淋巴结群","右颈前淋巴结群","左锁骨上窝淋巴结","右锁骨上窝淋巴结","左颈前淋巴结群"],"a":3,"e":"肺癌的淋巴转移多沿右锁骨上窝和腋窝进行，胸腔恶性肿瘤穿刺也常选右锁骨上淋巴结；胃癌则转移至左锁骨上窝Virchow淋巴结。"},{"q":"患者，男，16岁，3天前淋雨后出现高热、咳嗽、咳铁锈色痰。关于该患者体格检查，描述错误的是","o":["患侧语颤增强","患侧叩诊浊音","患侧呼吸音减弱","患侧常可闻及弥漫干啰音","患侧有时可听到胸膜摩擦音"],"a":3,"e":"大叶性肺炎实变期语颤增强、叩诊浊音并可闻支气管呼吸音，累及胸膜时出现胸膜摩擦音；干啰音由气道狭窄产生，非肺实变体征。"},{"q":"患者，女，36岁，消瘦伴有畏热多汗，性情急躁，心悸，多考虑哪种疾病导致的消瘦","o":["肾上腺皮质功能减退症","希恩综合征","1型糖尿病","甲状腺功能亢进症","神经精神疾病"],"a":3,"e":"畏热多汗、性情急躁、心悸伴消瘦反映甲状腺激素增多所致的高代谢状态，是甲亢的典型表现；肾上腺皮质功能减退多伴低血压和色素沉着。"},{"q":"患者，男，56岁，2年前患者反复出现多关节疼痛，疼痛时伴晨僵，查体在肘关节鹰嘴突周围可见大小不一、质硬、无压痛的皮下小结。该患者的皮下结节可能是","o":["风湿结节","痛风结节","结节性红斑","动脉炎结节","Osler结节"],"a":0,"e":"风湿结节位于关节及骨隆突附近，质硬、无压痛、大小不等，为风湿热的特征性皮下结节；痛风结节质硬但有压痛，常伴局部红肿灼热。"},{"q":"患者，男，60岁，突发鼻出血入院。查体：BP 200/100mmHg，心肺正常。血常规正常。需要立即给予的处理是","o":["局部填塞止血","降压","注射止血药","冷水敷脸","补液"],"a":1,"e":"血压200/100mmHg属3级高血压，鼻黏膜血管在高压下破裂出血，须迅速降压并配合局部压迫填塞；单纯止血药和冷敷不能去除病因。"},{"q":"患者，女，32岁。发热、盗汗、乏力12天，呼吸困难2天。查体：T 38℃，右下肺叩诊浊音，呼吸音消失。患者最可能的诊断是","o":["右胸膜间皮细胞瘤","右干酪性肺炎","右结核性胸膜炎","右大叶性肺炎","右胸膜肥厚粘连"],"a":2,"e":"低热、盗汗、乏力伴胸腔积液征象，以结核性胸膜炎最常见；大叶性肺炎起病急、高热、咳铁锈色痰，胸腔积液少见。"},{"q":"患者，男，32岁。自幼患麻疹后，经常咳嗽、咳痰、痰中带血，诊断为支气管扩张。该患可出现的体征是","o":["气管向患侧移位","双肺广泛干啰音","佝偻胸","肋间隙缩窄","局限固定的湿啰音"],"a":4,"e":"支气管扩张的病灶局限且反复感染，听诊为固定于某一部位的局限性湿啰音；双肺广泛干啰音见于哮喘、慢性支气管炎。"},{"q":"患者，男，65岁。吸烟40余年，慢性咳嗽，咳痰20余年。双肺呼吸音减弱，肺下界下移。最可能的诊断是","o":["肺炎","慢性阻塞性肺疾病","胸腔积液","支气管哮喘","气胸"],"a":1,"e":"长期吸烟及慢性咳痰史伴肺下界下移、呼吸音减弱，提示肺组织弹性减退、肺过度充气，符合慢性阻塞性肺疾病；积液和气胸不使肺下界下移。"},{"q":"3岁儿童，高热、昏迷、抽搐2天急诊入院，疑为乙脑和中毒性痢疾。为及时诊断，应立即进行的检查是","o":["大便培养","肛拭子或盐水灌肠镜检","脑脊液常规","头颅CT","乙脑特异性IgM测定"],"a":1,"e":"中毒性痢疾进展迅速，及早取黏液脓血便镜检见大量白细胞即可确诊并指导抢救；便培养耗时，脑脊液和头颅CT无特异性。"},{"q":"患者，男，10岁，活动后心悸，气促8年。查体：心前区隆起，胸骨左缘3～4肋间触及收缩期震颤，同时该处闻及4/6级收缩期杂音。最可能的诊断是","o":["房间隔缺损","动脉导管未闭","室间隔缺损","法洛四联症","三尖瓣狭窄"],"a":2,"e":"胸骨左缘第3、4肋间收缩期震颤并伴响亮粗糙的收缩期杂音，是室间隔缺损的典型体征；房间隔缺损和动脉导管未闭的震颤部位不同。"},{"q":"患者，男，39岁，夜尿增多半年，乏力1个月就诊。尿常规示尿蛋白＋＋＋，肾功能示尿素氮45.2mmol/L，肌酐987μmol/L。现进行移植前准备，为预防超急性排斥反应，应行下列哪项检查","o":["HLA血清学定型","HLA细胞学定型","HLA基因定型","PHA激发的淋巴细胞转化试验","淋巴细胞交叉毒性试验"],"a":4,"e":"淋巴细胞毒交叉配合试验检测受者血清中预存的抗供者HLA抗体，阳性者移植后易发生超急性排斥；HLA定型仅反映配型相合程度。"},{"q":"患者，男，54岁，诊断为酒精性肝硬化3年。现发热并意识恍惚2小时。有助于判断患者有无肝性脑病的血液化验指标是","o":["球蛋白","丙氨酸氨基转移酶","白蛋白","血小板计数","血氨"],"a":4,"e":"氨在肝内经鸟氨酸循环合成尿素解毒，肝细胞严重损害时尿素合成减少、血氨升高并透过血脑屏障损害中枢，故血氨可判断肝性脑病。"},{"q":"患儿，男，12岁，因“左膝关节肿痛8年，再发7天”来诊。血常规：白细胞10.5×109/L，N 80%，L 17%，M 3%，Hb 130g/L，PLT 140×109/L。肝功能正常。为进一步确诊，应该首先进行的检查是","o":["Ⅷ因子测定","Ⅹ因子测定","Ⅺ因子测定","D-二聚体测定","纤维蛋白降解产物测定"],"a":0,"e":"男性儿童反复关节腔出血而无外伤史提示血友病A，由Ⅷ因子缺乏引起，测定Ⅷ因子活性可确诊；关节畸形是反复出血的后果。"},{"q":"患者，女，17岁，春游时出现支气管哮喘急性发作，下列体征最有助于诊断的是","o":["语音震颤减弱","叩诊呈过清音","肺部散在干啰音","两肺弥漫哮鸣音","两肺底水泡音"],"a":3,"e":"哮喘急性发作时气道弥漫性痉挛，两肺满布哮鸣音并呼气延长，是最有诊断价值的体征；散在干啰音多见于支气管炎。"},{"q":"患者，男，67岁。间断大便带血2个月。要想进行肛门直肠检查，不常采用的体位是","o":["肘膝位","左侧卧位","截石位","蹲位","平卧位"],"a":4,"e":"肛门直肠检查多取肘膝位、左侧卧位、截石位或蹲位以充分暴露肛管直肠下段；平卧位暴露不良，故不常采用。"},{"q":"患者，女，23岁。双肘、腕、膝等关节疼痛2个月，伴脱发、口腔溃疡、光敏感。最可能的疾病是","o":["类风湿关节炎","系统性红斑狼疮","骨关节炎","化脓性关节炎","关节结核"],"a":1,"e":"育龄女性多关节痛伴脱发、口腔溃疡及光敏感，符合系统性红斑狼疮；类风湿关节炎以对称性小关节肿痛、晨僵为主，无光过敏。"},{"q":"患者，女，24岁。因习惯性流产入院，考虑诊断为继发性抗心磷脂综合征。目前哪项检测最有意义","o":["ACA","APTT","TT","AT","PT"],"a":0,"e":"抗心磷脂抗体特异性较强，与抗磷脂综合征密切相关，约70%未经治疗的阳性者可发生自发性流产和宫内死胎，故检测ACA最有意义。"},{"q":"26岁哺乳期女性，近两日出现发热、大汗、寒战，右侧乳房有红、肿、热、痛，触诊有包块，质硬、最可能的诊断是","o":["急性乳腺炎","乳腺癌","乳腺囊肿","乳腺脓肿","乳腺纤维腺瘤"],"a":0,"e":"哺乳期乳房局限性红肿热痛并触及硬结，伴寒战高热，为急性乳腺炎的典型表现；乳腺癌多无炎症表现，肿块质硬固定。"},{"q":"患儿，男，11岁，晨起眼睑水肿，血尿、少尿1周。血压180/105mmHg，既往无肾病史，尿沉渣：红细胞满视野，大小不一，可见大红细胞，棘形红细胞。患者血尿类型为","o":["均一性血尿","非均一性血尿","血红蛋白尿","肾后性血尿","暂时性血尿"],"a":1,"e":"红细胞经肾小球滤过膜挤压变形，尿中大小不一、形态多样并见棘形红细胞，即非均一性血尿，是肾小球源性出血的标志。"},{"q":"患者，男，36岁，反复上腹烧灼样痛5年。近1个月来上腹胀痛，恶心、呕吐胃内容物，吐后胀痛可缓解。最可能的诊断是","o":["急性胰腺炎","幽门梗阻","胰腺癌","慢性胆囊炎","胃黏膜脱垂"],"a":1,"e":"幽门梗阻时胃排空受阻，反复呕吐大量酸酵宿食后腹胀暂时缓解，为其主要症状；胃癌多有消瘦及持续上腹痛。"},{"q":"患者，男，77岁，因出血及呼吸困难就诊。胸部X线片在右肺部表现出广泛的异常阴影，不过不清楚这种阴影是由血液（与血液渗透）、肺炎或其他潜在疾病引起的。动脉血气：pH 7、50，PaCO2 31mmHg，HCO3－ 24mEq/L，PaO2 88mmHg。该患者可能发生了","o":["呼吸性碱中毒失代偿期","呼吸性酸中毒和低氧血症代偿期","代谢性酸中毒部分代偿期","代谢性碱中毒部分代偿期","抽取的是静脉血"],"a":0,"e":"pH 7.50升高、PaCO2 31mmHg降低而HCO3-正常，为急性呼吸性碱中毒且尚未代偿；PaO2 88mmHg未达呼吸衰竭标准。"},{"q":"患者，女，26岁，患慢性肾小球肾炎。目前检测结果：尿蛋白＋，血Ccr 40ml/min，Cr 200μmol/L，BUN 10mmol/L。目前患者肾功能状态为","o":["肾功能正常","肾衰竭代偿期","肾衰竭失代偿期","肾衰竭期","尿毒症期"],"a":2,"e":"血肌酐200μmol/L中度增高、尿素氮10mmol/L超过9mmol/L，符合肾衰竭失代偿期；代偿期尿素氮小于9mmol/L，尿毒症期肌酐可达1.8mmol/L。"},{"q":"患者，女，56岁，反复多关节疼痛3年。1天前再次出现四肢多关节疼痛，伴晨僵，体温37、5℃，在肘关节鹰嘴突周围可见大小不一、质硬、无压痛的皮下小结。该患者的诊断可能是","o":["痛风","结节性多动脉炎","类风湿关节炎","囊虫病","系统性红斑狼疮"],"a":2,"e":"对称性多关节肿痛伴晨僵及肘鹰嘴处质硬无压痛皮下小结，符合类风湿关节炎；痛风伴高尿酸及局部红肿灼热，风湿性关节炎呈游走性。"},{"q":"患者，女，20岁。近2年间断出现抽搐发作，今晨洗漱时突然出现意识丧失，全身强直，呼吸暂停，继而四肢发生阵挛性抽搐，尿、便失禁，发作约1min后缓解。该患者最可能的诊断为","o":["低钙抽搐","癫痫大发作","癔症性发作","癫痫小发作","低血糖状态"],"a":1,"e":"意识丧失、全身强直后阵挛性抽搐、呼吸暂停及大小便失禁，发作约1分钟自行停止，为癫痫大发作；癔症性发作无尿失禁和发绀。"},{"q":"患者，女，38岁，面色苍白4年。实验室检查：Hb 88g/L，血清铁5μmol/L，血清总铁结合力410μmol/L，血清铁蛋白10μg/L，网织红细胞计数0.015，血清铁饱和度15%。该患者最可能的诊断是","o":["缺铁性贫血","巨幼细胞贫血","铁粒幼细胞贫血","地中海贫血","阵发性睡眠性血红蛋白尿"],"a":0,"e":"血清铁蛋白10μg/L、转铁蛋白饱和度15%显著降低，伴小细胞低色素性贫血，是缺铁性贫血的诊断依据；巨幼细胞贫血为大细胞性。"},{"q":"患者，女，18岁。患上呼吸道感染1周后，感心悸，气短，乏力，心率98次/min。心电图示P-R间期为0、22s，应诊断为","o":["窦性心动过速","窦性心律不齐","二度Ⅰ型房室传导阻滞","二度Ⅱ型房室传导阻滞","一度房室传导阻滞"],"a":4,"e":"成人PR间期超过0.20秒即诊断一度房室传导阻滞，每个P波后均有QRS波；二度阻滞会出现QRS波脱漏，可与之鉴别。"},{"q":"患者，男，30岁。近10年来常有空腹痛和夜间痛，服用制酸剂可使腹痛减轻，1小时前餐后突感上腹持续性剧痛而入院。查体发现腹肌紧张。该患者查体最有诊断意义的是","o":["右上腹有压痛","肝浊音界消失","腹式呼吸消失","肠鸣音消失","腹部有移动性浊音"],"a":1,"e":"空腹及夜间痛、制酸剂可缓解提示消化性溃疡，突发持续剧痛伴腹肌紧张为急性穿孔，游离气体聚集膈下使肝浊音界消失，最具诊断价值。"},{"q":"患者，男，35岁，因血尿就诊，无畏寒发热、咽痛、肌痛、关节痛。查体无肾区叩击痛。既往有哮喘20余年。否认肾病家族史。尿常规检查提示尿蛋白（＋），白细胞（－），亚硝酸盐（－），镜检提示红细胞30～50个/HPF；血肌酐正常。该患者最可能的诊断为","o":["IgA肾病","肾结石","膀胱移行细胞癌","韦格纳肉芽肿","急性肾小球肾炎"],"a":0,"e":"青年男性反复无痛性血尿伴蛋白尿而肾功能正常，无感染及结石证据，最符合IgA肾病；急性肾小球肾炎多有水肿和高血压。"},{"q":"患者，男，28岁。反复节律性中上腹痛3年，常反酸嗳气。近2日，大便柏油样，粪便OB（＋＋＋＋）。为明确诊断，首选的辅助检查是","o":["急诊胃镜检查","X线胃肠钡餐造影","纤维结肠镜检查","逆行胰胆管造影","腹部超声检查"],"a":0,"e":"柏油样便伴溃疡病史提示上消化道出血，急诊胃镜可明确出血部位并同时止血，为首选；出血期不宜行钡餐检查。"},{"q":"患者，男，26岁。上床时突觉右侧胸痛、气短。查体可见：气管左移，右侧胸廓膨隆，右肺语音震颤减弱，右肺叩诊呈鼓音，右肺呼吸音减弱。该患者最可能的诊断为","o":["大叶性肺炎","右侧气胸","右侧胸腔积液","支气管哮喘","心绞痛"],"a":1,"e":"胸膜腔积气使患侧语颤传导减弱、叩诊呈鼓音、呼吸音减弱，气管被推向健侧，符合气胸；胸腔积液叩诊为浊音而非鼓音。"},{"q":"患者，男，38岁，无明显诱因出现皮肤黏膜黄染伴瘙痒，无腹痛，无发烧。查体：神志清楚，巩膜黄染，皮肤无出血，腹软，无压痛，肝脾未触及。下列哪项检查支持原发性胆汁肝硬化的诊断","o":["粪便黄色加深","血清结合胆红素增加","尿胆原增加","血清碱性磷酸酶减低","血清胆固醇降低"],"a":1,"e":"原发性胆汁性肝硬化属胆汁淤积性黄疸，以结合胆红素升高为主，伴皮肤瘙痒、碱性磷酸酶和胆固醇升高；尿胆原减少、粪色变浅。"},{"q":"患者，男，62岁，尿频、尿急、排尿不畅2个月。前列腺液非染色涂片白细胞成堆，红细胞110个/HPF，磷脂酰胆碱小体消失。考虑该患者为","o":["肾炎","尿道炎","前列腺炎","精囊炎","膀胱炎"],"a":2,"e":"前列腺液白细胞成堆、超过10个/HPF，磷脂酰胆碱小体减少或消失，是前列腺炎的典型表现；精囊炎以前列腺液红细胞增多为主。"},{"q":"患者，男，30岁，因低热伴干咳1个月来诊。查体右上肺叩诊稍浊，可闻及支气管肺泡呼吸音和湿性啰音，PPD试验强阳性。若该患者出现浅表淋巴结肿大，最先肿大的区域可能是","o":["颌下淋巴结","颏下淋巴结","颈部淋巴结","耳后淋巴结","腋窝淋巴结"],"a":2,"e":"颈部淋巴结收纳气管、支气管的淋巴回流，肺结核的淋巴转移多首先累及颈部；肺癌则多转移至右锁骨上窝淋巴结。"},{"q":"患者，男，56岁。腹胀3天，结肠癌术后持续胃肠减压，胃液引流通畅。若患者出现低钠、低钾、低氯血症，最可能的化验指标是","o":["血钠145mmol/L，血钾3、5mmol/L，血氯90mmol/L","血钠130mmol/L，血钾3、0mmol/L，血氯92mmol/L","血钠150mmol/L，血钾5、5mmol/L，血氯105mmol/L","血钠140mmol/L，血钾4、5mmol/L，血氯99mmol/L","血钠135mmol/L，血钾3、5mmol/L，血氯95mmol/L"],"a":1,"e":"持续胃肠减压丢失大量胃液，钠、钾、氯随之丢失，血钠130mmol/L、血钾3.0mmol/L、血氯92mmol/L均低于正常下限，最符合。"},{"q":"患者，男，15岁，反复皮肤巩膜黄染、上腹不适、水肿伴浓茶样尿3个月。入院查体：全身皮肤巩膜黄染，角膜边缘出现棕褐色的色素环。骨髓检查正常，肝炎病毒两次检查阴性。考虑下列何种原因可能性大","o":["先天性因素","类脂质蛋白沉积症","铜代谢障碍","维生素A缺乏","角膜血管增生"],"a":2,"e":"角膜边缘棕褐色色素环即Kayser-Fleischer环，由铜代谢障碍致铜沉积形成，见于肝豆状核变性，常伴肝损害与溶血。"},{"q":"患者，男，68岁，既往多年吸烟史。诉咳嗽、咳痰3个月。为明确诊断，首先应进行","o":["胸部CT","胸部增强CT","胸部磁共振","纤维支气管镜检查及活检","胸部X线检查"],"a":4,"e":"长期吸烟者出现咳嗽咳痰需排除肺癌，胸部X线检查简便经济，为筛查首选，发现异常再行CT或支气管镜活检。"},{"q":"患者，女，23岁。低热、乏力、盗汗伴咳嗽、痰中带血3个月。胸片示右上肺大片状阴影，密度不均，其内可见薄壁空洞，痰抗酸杆菌阳性。应考虑","o":["右上肺脓肿","浸润性肺结核空洞形成","右上肺炎","慢性纤维空洞肺结核","亚急性血行播散性肺结核"],"a":1,"e":"低热、盗汗、痰中带血伴右上肺密度不均大片影及薄壁空洞、痰抗酸杆菌阳性，是浸润性肺结核空洞形成的典型表现。"},{"q":"患者，男，66岁。进行性排尿困难1年余。近3个月来尿频，每日排尿10余次，且尿道外口有尿液溢出。查体：下腹部隆起，叩诊浊音，直肠指诊前列腺4cm×5cm大小，质韧，中央沟消失。测残余尿300ml。根据上述病史，应考虑为","o":["遗尿","真性尿失禁","压力性尿失禁","急迫性尿失禁","间歇性尿失禁"],"a":4,"e":"前列腺增生致膀胱出口梗阻、残余尿增多，膀胱过度充盈后尿液间断溢出，属充溢性（间歇性）尿失禁；压力性尿失禁与腹压增加有关。"},{"q":"一老年患者，发现尿色呈鲜红色2天，每次排尿为开始尿色正常，末段尿为红色，有排尿困难，无发热和腹痛。该患者病变最有可能在","o":["肾脏","肝脏","血液系统","膀胱颈部或前列腺","肾脏或输尿管"],"a":3,"e":"排尿初始尿色正常、末段变红为终末血尿，提示出血位于膀胱颈部、三角区或后尿道前列腺部；全程血尿多来自肾脏或输尿管。"},{"q":"患者，男，29岁，发热、咳痰伴咯血1周入院。查体：贫血貌，全身多处出血点，胸骨后压痛，肝脾大。血常规：白细胞40×109/L，血小板30×109/L。该患者最可能的诊断是","o":["急性白血病","败血症","血小板减少性紫癜","淋巴瘤","再生障碍性贫血"],"a":0,"e":"发热、贫血、出血伴胸骨压痛、肝脾肿大及白细胞显著增高，是急性白血病的典型表现；再生障碍性贫血无肝脾肿大和白细胞增高。"},{"q":"患者，男，60岁。鼻塞及涕中带血半年，无其他不适。查体：耳前淋巴结肿大，鼻中隔无偏曲。最可能的诊断是","o":["鼻窦炎","鼻咽癌","鼻炎","鼻中隔偏曲","血液系统疾病"],"a":1,"e":"单侧鼻塞、涕中带血伴耳前淋巴结肿大，应高度怀疑鼻咽癌；鼻炎多为双侧流涕，鼻窦炎有脓涕及头痛。"},{"q":"患者，男，32岁，慢性肾衰竭，肾移植，需做配型。人白细胞抗原交叉配型的目的是","o":["检测供者血清有无针对受者人白细胞抗原的抗体","检测受者血清有无针对供者人白细胞抗原的抗体","检测供者淋巴细胞表面的人白细胞抗原","检测受者淋巴细胞表面的人白细胞抗原","检测供受者血型抗原"],"a":1,"e":"交叉配型检测受者血清中是否存在针对供者淋巴细胞HLA抗原的抗体，以预防超急性排斥反应，要求死亡细胞少于15%。"},{"q":"患者，女，54岁，胸闷入院，查体可见叹气样呼吸，余未见异常，该患者最可能的诊断是","o":["酸中毒","心功能不全","急性胸膜炎","抑郁症","大叶性肺炎"],"a":3,"e":"叹气样呼吸是在正常节律中插入一次深大呼吸并伴叹息声，属功能性改变，多见于神经衰弱、精神紧张和抑郁症。"},{"q":"患儿，男，6岁。发病第1天体温为37.5℃，伴咽痛，未予治疗；第2天体温达40.5℃，伴神志恍惚及抽搐；经输液、抗生素等治疗，第3天体温降至38.2℃。其体温变化过程是","o":["低热→超高热→中等热","中等热→高热→中等热","低热→高热→高热","中等热→超高热→中等热","低热→高热→中等热"],"a":4,"e":"37.5℃为低热，40.5℃落在39.1～41℃区间为高热，38.2℃为中等度热；故体温变化过程为低热→高热→中等热。"},{"q":"患者，男，20岁，下腰背痛2年，伴足跟痛。其父有类似病史，已驼背。该患者的诊断可能是","o":["结核性脊柱炎","椎间盘突出","强直性脊柱炎","腰肌劳损","类风湿关节炎"],"a":2,"e":"青年男性慢性下腰背痛伴足跟附着点痛，有家族史及驼背强直，符合强直性脊柱炎；结核性脊柱炎多有结核中毒症状及成角畸形。"},{"q":"患者，女，58岁。近1个月来经常腹痛、腹泻，粪便呈果酱样伴腥臭味，右下腹压痛明显。最可能的诊断是","o":["细菌性痢疾","急性胰腺炎","急性阑尾炎","食物中毒","阿米巴痢疾"],"a":4,"e":"果酱样腥臭粪便伴右下腹压痛是阿米巴痢疾的典型表现，病变多在回盲部；细菌性痢疾为黏液脓血便伴里急后重。"},{"q":"患者，女，30岁，腹胀大2年，近期加重。查体：腹胀大如足月妊娠大小，腹中部浊音，两侧鼓音，且浊音不随体位而改变，腹无压痛，肝脾未触清。为明确诊断，首选哪项检查","o":["肝功能化验","腹腔穿刺液检查","腹部X线平片检查","X线钡餐检查","妇科B超检查"],"a":4,"e":"腹中部浊音、两侧鼓音且浊音不随体位移动，提示巨大卵巢囊肿而非腹腔积液，妇科B超可明确其来源和性质，为首选。"},{"q":"患者，男，54岁。大便秘结，便中带血3个月。查体：直肠指检于肛门外口见紫红色柔软包块，用力时可突出增大。该患者最可能的诊断是","o":["直肠息肉","直肠癌","肛周脓肿","痔疮","直肠感染"],"a":3,"e":"肛门外口紫红色柔软包块、用力时突出增大，为外痔或混合痔；直肠癌质硬凹凸不平，直肠息肉位于齿状线以上。"},{"q":"患者，女，45岁。劳力性呼吸困难10年，间断双下肢水肿5年，突发咯血200ml入院。查体：双肺底可闻及湿啰音，心率132次/min，第一心音强弱不等。胸片提示：肺动脉段突出，心影呈梨型。该患者咯血的原因考虑为","o":["肺毛细血管破裂","支气管动脉破裂","急性肺水肿","支气管静脉破裂","合并支气管扩张"],"a":3,"e":"二尖瓣狭窄致左房压及肺静脉压升高，支气管黏膜下静脉曲张破裂可咯出大量鲜血；肺毛细血管破裂多为痰中带血。"},{"q":"患者，女，48岁，突发性恶心，头晕，随之呕吐鲜红色血液约1000ml。查体：BP 8/6kPa（1kPa≈7.5mmHg），P 110次/min，面色苍白，神志淡漠，无巩膜黄染，心肺未见异常，腹软，无压痛，肝脾未触及，移动性浊音阴性。下列支持肝硬化食管静脉曲张破裂出血的诊断的是","o":["服用非甾体类药物史","伴腹部剧痛","伴寒战，高烧","呕血中有凝血块","出血早期即出现血红蛋白下降"],"a":3,"e":"食管静脉曲张破裂出血量大、血液在胃内停留时间短，呕血常混有凝血块；出血早期血红蛋白尚未被稀释，可无明显下降。"},{"q":"患者，女，27岁。停经50天，腹痛、阴道流血3小时就诊。既往有2次自然流产史。该患者最应进行以下哪项检测","o":["血小板计数","血小板功能","凝血因子活性测定","凝血酶原时间测定","抗心磷脂抗体测定"],"a":4,"e":"反复自然流产伴停经后腹痛、阴道流血，应检测抗心磷脂抗体，其阳性提示抗磷脂综合征致胎盘血栓形成，是流产的重要原因。"},{"q":"某患者，突然呼吸困难，发绀，叩诊右侧呈鼓音，听诊呼吸音消失，可诊为","o":["右胸腔积液","右侧气胸","右大叶肺炎","肺梗死","支气管哮喘"],"a":1,"e":"胸膜腔大量积气使患侧叩诊呈鼓音、呼吸音消失，符合气胸；胸腔积液叩诊为浊音，大叶性肺炎可闻支气管呼吸音。"},{"q":"患者，男，54岁。意识不清3小时。查体：昏迷，呼吸缓慢，双侧瞳孔缩小，对光反射存在。该患者最可能的诊断是","o":["颠茄类中毒","有机磷农药中毒","酒精中毒","氰化物中毒","一氧化碳中毒"],"a":1,"e":"昏迷伴呼吸缓慢、双侧瞳孔缩小而对光反射存在，是有机磷农药中毒的典型表现；颠茄类和酒精中毒多瞳孔散大。"},{"q":"患者，女，70岁，拔牙后伤口渗血不止3天。既往有高血压、冠心病病史，长期服用阿司匹林等药物。下列哪项表现最符合患者病情","o":["血红蛋白增高","凝血因子Ⅷ活性减低","PAgT/PAdT减低","血块收缩试验增高","vWF:Ag增高"],"a":2,"e":"阿司匹林抑制血小板环氧化酶，使血小板聚集和黏附功能下降，故PAgT、PAdT减低而凝血因子活性正常，出血时间延长。"},{"q":"患者，男，30岁。近1年来反复上腹痛，进食半小时后腹痛明显，伴反酸、胃灼热，1小时前突发上腹部剧烈疼痛，伴恶心、呕吐。该患者当前最可能出现何种体征","o":["腹式呼吸增强，肠鸣音活跃","腹式呼吸增强，肠鸣音减弱","腹式呼吸减弱，肠鸣音活跃","腹式呼吸减弱，肠鸣音减弱","腹式呼吸减弱，肠鸣音高亢"],"a":3,"e":"溃疡穿孔引起弥漫性腹膜炎，腹肌紧张使腹式呼吸减弱，肠麻痹使肠鸣音减弱；肠鸣音亢进见于机械性肠梗阻。"},{"q":"患者，女，频发晕厥，神经系统查体发现患者由立位到卧位脉搏减少达20次/min。这提示","o":["交感神经兴奋性增强","交感神经兴奋性减弱","迷走神经兴奋性增强","迷走神经兴奋性减弱","锥体束损伤"],"a":2,"e":"卧立位试验中由立位到卧位脉率减慢超过12次/分，提示迷走神经兴奋性增高；卧位到立位脉率增快超过12次/分为交感兴奋性增高。"},{"q":"患者，男，40岁，反复饥饿时中上腹部隐痛10年，伴反酸嗳气，在进食和服制酸剂后可缓解，今晨中上腹剧痛后腹痛持续存在。如进行腹部检查，最具诊断价值的腹部体征是","o":["腹肌紧张","腹壁柔韧感","肠鸣音亢进","肝浊音上界消失","Murphy征阳性"],"a":3,"e":"空腹及夜间痛符合十二指肠溃疡，突发持续剧痛为急性穿孔，游离气体使肝浊音界消失，是穿孔最有诊断价值的体征。"},{"q":"患者，女，25岁，服用某“减肥茶”后腹泻3天，食欲缺乏，查血钾2.8mmol/L，其心电图可能表现为","o":["QT间期延长","QRS波群增宽","u波倒置","ST段压低，T波低平，u波增高","T波倒置"],"a":3,"e":"血钾2.8mmol/L为低钾血症，心电图表现为ST段压低、T波低平、u波增高及QT-u间期延长；血钾更低时QRS波群增宽。"},{"q":"患者，女，27岁，因为乏力、尿色偏深1周入院。查体示皮肤巩膜轻度黄染，浅表淋巴结未触及，肝脾不大。检查显示中度贫血及血小板减少。发病前无特殊用药史，既往有2次自发流产史。以下检查最有意义的是","o":["APTT","PT","TT","血浆蛋白C活性测定","抗磷脂抗体测定"],"a":4,"e":"年轻女性溶血性贫血伴血小板减少及反复自然流产，符合抗磷脂综合征，抗体与血细胞膜磷脂结合致破坏，故检测抗磷脂抗体最有意义。"},{"q":"患者，男，19岁。打篮球时突然感右侧胸部剧烈疼痛、气短，逐渐加重，前来就诊。该患者还可能出现下列哪项体征","o":["右侧胸廓凹陷","右侧触觉语颤减弱","右侧胸廓运动增强","右侧触觉语颤增强","右侧叩诊清音"],"a":1,"e":"剧烈运动后突发胸痛气短提示自发性气胸，胸膜腔积气使语音传导减弱，故患侧触觉语颤减弱、叩诊呈鼓音。"},{"q":"53岁女性，主诉“胸闷、胸痛2天”入院。现病史不应包括哪项内容","o":["有无头痛、头晕","有无心慌、气短","疼痛的部位、性质、持续时间","胸闷、胸痛的病因及诱因","兄弟姐妹有无类似病史"],"a":4,"e":"现病史记录本次发病的诱因、部位、性质、持续时间及伴随症状；兄弟姐妹有无类似疾病属家族史内容。"},{"q":"患者，女，63岁，基础风湿性心脏病、二尖瓣狭窄、糖尿病病史。呕吐半日，共计3次，每次量约200ml，胸痛3小时来诊，入室BP 65/40mmHg，HR 141次/min，SpO279%；入室心电图如图所示。进一步治疗首选","o":["积极补液、抗休克治疗","洋地黄类控制心室率","直流电复律","抗休克同时尽早行急诊冠状动脉介入治疗","抗休克，待血流动力学稳定后择期行冠状动脉造影"],"a":3,"e":"官方题库缺失图片"},{"q":"患者，男，19岁，反复多饮、多尿6年，近半个月出现乏力入院。查血糖4.7mmol/L，血肌酐70μmol/L，血钾2.9mmol/L，血钙1.9mmol/L，血磷0.8mmol/L，血氯120mmol/L，二氧化碳结合力18mmol/L，尿pH 6.4，尿糖阴性，尿比重1.020，B超检查双肾多发结石。为明确病因，还应该做的检查是","o":["酚红排泄试验","碳酸氢根重吸收试验","氯化铵负荷试验","内生肌酐清除率试验","尿液稀释-浓缩试验"],"a":2,"e":"低钾、低钙、高氯性代谢性酸中毒伴肾结石而尿pH不能酸化，提示远端肾小管泌氢障碍，氯化铵负荷试验可证实，为确诊依据。"},{"q":"患者，男，20岁。近3天来出现皮肤紫癜，下肢为主，鲜红色，突出皮面，伴有关节痛。既往无出血病史。出血时间延长，束臂试验阳性，尿常规示红细胞＋＋/HPF。血常规基本正常。凝血功能检测示PT、APTT均正常。该患者最可能的诊断是","o":["过敏性紫癜","血管性血友病","深静脉血栓形成","弥散性血管内凝血","血小板无力症"],"a":0,"e":"双下肢对称性、高出皮面的紫癜伴关节痛和血尿，血小板及凝血功能正常、束臂试验阳性，为过敏性紫癜的典型表现。"},{"q":"患者，男，50岁，无特殊基础疾病，长期吸烟。间断胸闷8年，短暂意识丧失2次，胸闷发作时自测心率变慢，完善Holter如图所示，目前诊断首先考虑","o":["病态窦房结综合征","冠状动脉粥样硬化性心脏病","房室传导阻滞","冠状动脉痉挛","血管迷走性晕厥"],"a":3,"e":"官方题库缺失图片"},{"q":"患者，男，18岁，全身水肿，少尿1周。血浆蛋白减低。为确诊首先应做的检验是","o":["血常规","尿常规","内生肌酐清除率","浓缩稀释试验","酚红排泄试验"],"a":1,"e":"全身水肿、少尿伴血浆蛋白降低提示肾源性水肿，尿常规可发现蛋白尿和血尿，是明确肾脏病变最简便的首选检查。"},{"q":"周边型肺癌患者，病变直径2、5cm，病灶距胸部表面深约6cm，其叩诊音应为","o":["清音","浊音","实音","浊鼓音","空瓮音"],"a":0,"e":"叩诊对深部病灶不敏感，距胸壁5cm以上或直径小于3cm者常无叩诊音改变，故该病灶叩诊仍为清音。"},{"q":"患者，女，22岁。误服有机磷农药，神志不清，皮肤潮湿多汗，面部肌肉束颤动，瞳孔缩小，双肺布满湿啰音。患者最可能出现","o":["端坐呼吸","Kussmaul呼吸","潮式呼吸","浅快呼吸","深大呼吸"],"a":2,"e":"有机磷农药抑制胆碱酯酶，引起呼吸中枢抑制及呼吸节律异常，出现潮式呼吸；双肺湿啰音提示合并肺水肿。"},{"q":"患儿，男，12岁。发热、咽痛2周后出现晨起眼睑和颜面水肿，随后出现全身水肿，尿呈泡沫状，无呼吸困难，无皮肤黏膜和巩膜黄染和尿黄。该患儿首先要做的检查是","o":["血清肌酐","尿常规","肝功能","甲状腺功能","心脏彩超"],"a":1,"e":"呼吸道感染后出现眼睑水肿及泡沫尿提示急性肾小球肾炎，尿常规可见蛋白尿和镜下血尿，为最简便的首选检查。"},{"q":"患者，女，50岁，有风湿性心脏病史。近期上呼吸道感染后觉心悸、气促，心电图如图所示。首先考虑","o":["心房颤动","心房扑动3∶1～4∶1下传","心房扑动2∶1～4∶1下传","心房颤动2∶1～4∶1下传","房性心动过速"],"a":2,"e":"官方题库缺失图片"},{"q":"患者，女，20岁。发热38、5℃，右胸痛，伴呼吸运动减弱，语音震颤减弱，右下肺叩诊呈浊音，呼吸音减弱。诊断应首先考虑","o":["大叶性肺炎","胸腔积液","肺栓塞","浸润性肺结核","支气管哮喘"],"a":1,"e":"患侧呼吸运动减弱、语颤减弱、叩诊浊音、呼吸音减弱，符合胸腔积液；大叶性肺炎语颤增强并可闻支气管呼吸音。"},{"q":"患者，男，48岁，10年少量饮酒史。近1个月上腹疼痛，饥饿时加重，呈现疼痛－进食－缓解的规律。若胃镜下所见溃疡面较大，周边不整齐，底部不平，触之质硬，黏膜脆易出血，有可能是","o":["溃疡愈合期","溃疡瘢痕期","恶性溃疡","慢性肥厚性胃炎","慢性浅表性胃炎"],"a":2,"e":"溃疡面大、周边不整齐、底部不平、质硬脆易出血是恶性溃疡（溃疡型胃癌）的表现；良性溃疡边缘整齐、底部平坦。"},{"q":"患者，男，45岁，明确诊断为金黄色葡萄球菌肺炎。今晨患者查体前胸部可触及握雪感，该患者可能存在下列何种并发症","o":["急性乳腺炎","乳腺癌","皮下气肿","大量胸腔积液","少量胸腔积液"],"a":2,"e":"胸部皮下积气时按压皮肤出现捻发感或握雪感，即皮下气肿，多因肺部感染形成肺大疱破裂、气体沿组织间隙逸出所致。"},{"q":"患者，男，23岁，低热、盗汗、乏力、食欲缺乏、消瘦3个月余，最可能的诊断是","o":["肺结核","慢性肠炎","糖尿病","甲状腺功能亢进症","慢性胃炎"],"a":0,"e":"低热、盗汗、乏力、食欲缺乏及消瘦超过3个月为结核中毒症状，以肺结核最常见；甲亢有高代谢表现，糖尿病有多饮多尿。"},{"q":"患者，男，45岁。反复以低血钾性周期性瘫痪入院，伴尿量增多，骨痛不适。查尿常规正常，尿pH 6.5，血pH 7.35，血钾3.0mmol/L，血氯110mmol/L。此时对诊断最有帮助的检查是","o":["肾功能检测","氯化铵负荷试验","碳酸氢钠重吸收试验","内生肌酐清除率","骨骼X线摄片检查"],"a":1,"e":"顽固低钾伴多尿、骨痛及高氯性代谢性酸中毒而尿pH偏碱，提示远端肾小管酸中毒，氯化铵负荷试验后尿pH不能降至5.5以下可确诊。"},{"q":"患者，女，28岁，低热、骨关节肿胀3天。入院检查：关节腔积液腺苷脱氨酶活性明显增高。该患者可能的诊断为","o":["结核性关节炎","反应性关节炎","系统性红斑狼疮","强直性脊柱炎","类风湿性关节炎"],"a":0,"e":"关节腔积液腺苷脱氨酶活性明显增高对结核性关节炎特异性较高，结合低热和关节肿胀可诊断；类风湿关节炎该酶不升高。"},{"q":"患者，女，28岁。尿频、尿急、尿痛2天，无发热及腰痛，既往无类似发作史。查体：双肾区无叩击痛。实验室检查：血WBC 5.4×109/L，尿WBC 30～40个/HPF，RBC 10～15个/HPF，亚硝酸盐（＋）。该患者首先考虑的诊断是","o":["急性肾小球肾炎","急性肾盂肾炎","急性膀胱炎","急性间质性肾炎","尿道综合征"],"a":2,"e":"尿频、尿急、尿痛伴尿白细胞增多、亚硝酸盐阳性，无发热及肾区叩痛，提示感染局限于膀胱，为急性膀胱炎；肾盂肾炎多有高热腰痛。"},{"q":"患者，女，16岁。劳力性呼吸困难8年，二维超声心动图检查可见房间隔中部有5mm的连续中断。下列哪项体征有诊断意义","o":["双侧胸廓不对称，有心前区隆起","心前区有抬举性搏动","肺动脉瓣区第二心音亢进并有固定性分裂","心尖部内上方舒张早期奔马律","三尖瓣区舒张期隆隆样杂音"],"a":2,"e":"房间隔缺损时右心容量负荷增加、肺血增多，肺动脉瓣关闭延迟且不受呼吸影响，故肺动脉瓣区第二心音亢进并固定分裂。"},{"q":"患者，男，62岁，进食海鲜后3小时出现皮肤瘙痒伴有全身皮疹红斑，自服马来酸氯苯那敏后无改善，出现口渴、视物模糊、乏力，1小时前出现胸部压迫窒息感，持续不缓解，急诊来院。测血压80/50mmHg，ECG见图像，诊断考虑","o":["过敏性皮炎","过敏性休克","过敏性休克合并急性心肌梗死","过敏性休克合并心绞痛","急性心肌梗死心源性休克"],"a":2,"e":"官方题库缺失图片"},{"q":"患者，女，26岁。因右耳外耳道疼痛、流脓，并高热3天就诊。查体发现右侧鼓膜充血穿孔，见脓液自穿孔处流出。首先考虑诊断为","o":["外耳道炎","外耳道疖肿","急性中耳炎","颅底骨折","颅内感染"],"a":2,"e":"外耳道流脓伴高热、鼓膜充血穿孔并有脓液自穿孔处流出，为急性化脓性中耳炎；外耳道炎无鼓膜穿孔。"},{"q":"患者，男，60岁，剧烈腹痛2小时。查体：板状腹。腹部平片示有少量腹腔积液。血液生化检查：AMY 11000U/L，LPS 2200U/L。下列符合腹腔积液特点的是","o":["蛋白定量＜25g/L","LDH＜200U/L","细胞计数＜100×106/L","浆液性","积液LDH/血清LDH＞0.6"],"a":4,"e":"急性胰腺炎所致腹腔积液为渗出液，蛋白及LDH明显升高，积液LDH/血清LDH大于0.6，细胞数常超过500×10^6/L。"},{"q":"患者，女，38岁，皮肤黏膜出血点1个月，发热、面色苍白。胸骨压痛阳性，外周血WBC 70.0×109/L，可见幼稚细胞，Hb 80g/L，PLT 50×109/L。下列哪项检查有助诊断","o":["细胞外铁","细胞内铁","过氧化酶染色","叶酸","维生素B12"],"a":2,"e":"白细胞显著增高并见幼稚细胞，伴贫血、血小板减少及胸骨压痛，提示急性白血病，过氧化物酶染色可鉴别粒细胞与淋巴细胞型。"},{"q":"患者，男，54岁。突发剧烈头痛2小时，伴惊厥。查体：颈项强直，双侧凯尔尼格征阳性。该患者的诊断最可能是","o":["颅脑外伤","蛛网膜下腔出血","颅内占位性病变","高血压脑病","败血症"],"a":1,"e":"突发剧烈头痛伴惊厥、颈项强直及凯尔尼格征阳性，为血液刺激脑膜所致，符合蛛网膜下腔出血；高血压脑病以血压极高、意识障碍为主。"},{"q":"患者，男，30岁，右侧第一跖趾关节突发红肿、疼痛难忍1天入院。辅助检查：血尿酸为650μmol/L，血肌酐75μmol/L，血尿素氮8.1mmol/L。目前患者最可能的诊断是","o":["慢性肾小球肾炎","急性肾小球肾炎","痛风性关节炎","类风湿关节炎","风湿性关节炎"],"a":2,"e":"第一跖趾关节突发红肿热痛伴血尿酸显著升高，为痛风性关节炎的典型表现；类风湿关节炎多为对称性小关节肿痛。"},{"q":"患者，男，50岁。1周前支气管镜检查示左主支气管被肿物完全阻塞。胸片示左肺肺不张。该患者不可能出现的体征是","o":["左肺触觉语颤减弱","左肺可闻及管状呼吸音","左肺肺泡呼吸音减弱","左肺叩诊浊音","左侧呼吸运动减弱"],"a":1,"e":"主支气管完全阻塞致阻塞性肺不张，患侧语颤减弱、叩诊浊音、呼吸音减弱；管状呼吸音见于肺实变而非肺不张。"},{"q":"患者，女，55岁。黄疸伴肝大、皮肤瘙痒与心动过缓。粪色变浅、呈陶土色。最可能的诊断是","o":["溶血性黄疸","先天性非溶血性黄疸","隐性黄疸","肝细胞性黄疸","胆汁淤积性黄疸"],"a":4,"e":"黄疸伴皮肤瘙痒、心动过缓及陶土色粪便，是胆汁淤积性黄疸的表现，以结合胆红素升高为主，尿胆红素阳性。"},{"q":"患者，男，24岁。查体时发现包皮翻起后，龟头不能露出。该患者最可能的诊断是","o":["尿道下裂","假两性畸形","包茎","包皮过长","包皮过短"],"a":2,"e":"包皮翻起后仍不能露出阴茎头即为包茎，多因先天性包皮口狭窄或炎症、外伤后粘连所致；包皮虽超过阴茎头但翻起后能露出阴茎头者才称包皮过长。"},{"q":"患者，女，17岁，双下肢皮肤见多个红色点状改变，直径不超过2mm，压之不褪色，不凸出表面，应诊断为","o":["瘀点","蜘蛛痣","紫癜","充血性皮疹","斑疹"],"a":0,"e":"皮下出血直径不超过2mm者称瘀点，压之不褪色且不凸出皮肤；皮疹受压多褪色，小红痣虽不褪色但触之稍高于皮面且表面光亮。"},{"q":"患者，男，38岁。3年前患结核性渗出性心包炎，近2个月来呼吸困难、腹胀、水肿。查体：颈静脉怒张。X线示左、右心缘变直及心包钙化。该患者颈静脉怒张是由于","o":["上腔静脉阻塞","下腔静脉阻塞","静脉向右房回流受阻","右心房压力增高","右心室压力增高"],"a":2,"e":"缩窄性心包炎使心包增厚钙化、心室舒张受限，静脉血回流入右心房受阻，体循环静脉压升高而出现颈静脉怒张；上腔静脉阻塞另有头面部水肿。"},{"q":"患者，男，45岁。有高血压史，因“阵发性心悸2天”来诊。查体：血压120/70mmHg，心率180次/min，律齐，心音正常，无杂音。1min后心率降至80次/min，律齐。30秒后又复至180次/min。最可能的诊断为","o":["窦性心动过速","阵发性心房颤动","阵发性室上性心动过速","阵发性心房扑动","三度房室传导阻滞"],"a":2,"e":"心率180次/min、节律齐、突发突止且心音正常，符合阵发性室上性心动过速；窦性心动过速多有渐起渐止过程，心房颤动则心律绝对不齐。"},{"q":"患者发热、无力、食欲缺乏，腹痛，以左下腹明显，腹泻，早期稀便，大便次数增多后转为黏液脓血便，并有里急后重。应诊断为","o":["急性胃肠炎","急性细菌性痢疾","肠伤寒","食物中毒","肠阿米巴痢疾"],"a":1,"e":"左下腹痛、黏液脓血便伴里急后重提示病变位于直肠与乙状结肠，为急性细菌性痢疾的典型表现；阿米巴痢疾粪便呈暗红色果酱样，里急后重不明显。"},{"q":"患者，男，54岁。腹胀、少尿半个月，呕血1小时入院。既往有乙肝病史，未正规治疗。以下检测结果正确的是","o":["凝血酶时间缩短","凝血酶时间延长，且不被甲苯胺蓝纠正","凝血酶时间延长，且被甲苯胺蓝纠正","凝血酶活性增高","蛋白C活性增高"],"a":2,"e":"严重肝病时血中类肝素物质增多使凝血酶时间延长，加入甲苯胺蓝可中和该物质而使TT缩短，故延长可被纠正；纤维蛋白原减低所致者不被纠正。"},{"q":"1岁患儿，头部向左侧偏斜，颜面偏向右侧，颈部活动较困难，应考虑为","o":["先天性斜颈","重症肌无力","脑膜炎","颈椎结核","进行性肌萎缩"],"a":0,"e":"头向一侧偏斜、颈部活动受限而患侧胸锁乳突肌挛缩变短，是先天性斜颈的表现；将其头位复正时患侧胸锁乳突肌胸骨端隆起为特征性体征。"},{"q":"患者，女，双下肢水肿，血浆白蛋白26g/L，尿常规结果显示尿蛋白（4＋），该患者蛋白尿类型为","o":["肾小球性蛋白尿","肾小管性蛋白尿","功能性蛋白尿","组织性蛋白尿","偶然性蛋白尿"],"a":0,"e":"尿蛋白4＋、血白蛋白26g/L伴水肿，以白蛋白为主的蛋白尿提示肾小球滤过膜通透性增高，属肾小球性蛋白尿；肾小管性者以α1-微球蛋白等小分子蛋白为主。"},{"q":"患者，男，56岁，食欲减退，乏力、消瘦伴右上腹隐痛，加重1天入院。皮肤、巩膜黄染，血清胆红素520μmol/L，结合胆红素480μmol/L，粪便呈白陶土样。首先考虑下列哪种疾病","o":["梗阻性黄疸","溶血性黄疸","消化道出血","消化不良","肝硬化"],"a":0,"e":"结合胆红素占总胆红素绝大部分且粪便呈白陶土样，提示胆道完全梗阻、胆红素不能排入肠道，为梗阻性黄疸；溶血性黄疸以非结合胆红素升高为主。"},{"q":"患者，女，51岁，慢性阻塞性肺疾病20多年。2小时前剧烈咳嗽后突然胸部剧痛，继之呼吸困难，发绀、大汗、烦躁，气管右移，左肺呼吸音减低。最可能的诊断是","o":["大叶性肺炎","急性肺梗死","自发性气胸","休克性肺炎","急性心肌梗死"],"a":2,"e":"慢阻肺病人剧烈咳嗽后突发胸痛与呼吸困难，气管移向对侧、患侧呼吸音减低，符合脏层胸膜破裂所致的自发性气胸。"},{"q":"患者，女，45岁。反复上腹痛20年，近1周出现频繁呕吐，呕吐量大，呕吐物为宿食，不含胆汁。查体：可见胃型，振水音阳性。最可能的诊断是","o":["十二指肠憩室","幽门梗阻","十二指肠梗阻","小肠梗阻","食管裂孔疝"],"a":1,"e":"反复上腹痛多年后出现大量呕吐宿食、不含胆汁，伴胃型与振水音，是幽门梗阻的特征；呕吐物含胆汁则提示梗阻位于十二指肠乳头以下。"},{"q":"患儿，男，5岁。3天前无诱因出现发热，体温最高39、5℃；2天前出现皮疹，呈密集而均匀红色细小丘疹，初见颈部，24小时内遍及全身，周身皮肤潮红，伴痒感。查血常规：WBC 8.23×109/L，L% 10.6%，N% 80.1%，Hb 131g/L，PLT 333×109/L。患儿可能出现的舌部体征为","o":["地图舌","裂纹舌","草莓舌","牛肉舌","镜面舌"],"a":2,"e":"密集均匀的细小丘疹自颈部迅速遍及全身、皮肤潮红伴痒感，为猩红热表现，其舌乳头红肿突起形成草莓舌；地图舌与裂纹舌见于其他疾病。"},{"q":"患者，66岁，既往5年高血压病史。主诉心悸1年，劳力性心累胸闷2个月。查体：心音强弱快慢绝对不齐。常规心电图示心室率，125次/min，等电位线消失，P波不可见，QRS呈正常形态。住院期间患者诉头晕胸闷明显，发作时脉搏缓慢整齐，则心电图表现最可能为","o":["窦性心动过缓","一度房室传导阻滞","二度Ⅰ型房室传导阻滞","二度Ⅱ型窦房传导阻滞","三度房室传导阻滞"],"a":4,"e":"房颤病人出现缓慢而规则的心室率，提示心房激动不能下传、心室由低位起搏点控制，为三度房室传导阻滞；心电图上P波与QRS波互不相关。"},{"q":"患者，男，20岁。发热、腹痛1天，入院检查粪便为黏液脓血便，诊断细菌性痢疾，最有价值的细胞是","o":["吞噬细胞","中性粒细胞","上皮细胞","红细胞","嗜酸粒细胞"],"a":0,"e":"急性细菌性痢疾时粪便白细胞大量增多并见成堆脓细胞，吞噬细胞的出现是其诊断的主要依据之一；溃疡性结肠炎虽也可见，但脓血便特征不同。"},{"q":"患者，女，33岁，经常心悸、乏力，稍微活动即自觉心悸。图中上方为入院时心电图，下方为服用普萘洛尔（30mg）后90min的心电图。请问入院时上方心电图的诊断为","o":["窦性心律，心电图正常","窦性心动过速，T波改变","窦性心动过速，陈旧性心肌梗死","窦性心动过速，右室肥厚","窦性心动过速，不完全性右束支传导阻滞"],"a":1,"e":"官方题库缺失图片"},{"q":"患者，女，32岁，外阴瘙痒、白带增多5天，分泌物呈豆腐渣样，有凝乳状小块，考虑该患者为","o":["滴虫性阴道炎","阴道加德纳菌感染","真菌性阴道炎","细菌性阴道炎","宫颈炎"],"a":2,"e":"豆腐渣样、凝乳块状分泌物是念珠菌性阴道炎的典型性状；滴虫性阴道炎多为泡沫样稀薄脓性黄绿色分泌物，细菌性阴道病呈奶油样匀质稀薄。"},{"q":"某患者查体所见：右胸饱满，呼吸运动减弱，语颤消失，叩诊实音，呼吸音消失。此征符合","o":["右肺大叶性肺炎","右侧胸腔积液","右气胸","右肺不张","右肺大空洞"],"a":1,"e":"患侧胸廓饱满、语颤消失、叩诊实音、呼吸音消失，为大量胸腔积液的典型体征；气胸叩诊呈鼓音，肺不张则气管向患侧移位、肋间隙变窄。"},{"q":"45岁女性，反复夜间胃部胀痛2个月，既往史应包括","o":["有无胆囊炎病史","有无恶心、呕吐病史","有无腹痛、腹泻病史","药物不良饮食习惯","有无吸烟史"],"a":0,"e":"既往史应记录与现病密切相关的旧疾，胆囊炎可引起右上腹及上腹疼痛，与夜间胃痛需鉴别；吸烟史属个人史，恶心呕吐属现病史。"},{"q":"一老年患者，60岁，反复咳嗽、咳痰10余年，加剧3天入院。查体：桶状胸，呼气相延长，两肺可闻及干、湿啰音。该患者还可能出现","o":["双肺触觉语颤增强","双肺呼吸动度增强","双肺肺泡呼吸音增强","双肺听到较弱的支气管呼吸音","叩诊肺肝界下移"],"a":4,"e":"桶状胸、呼气相延长、双肺干湿啰音提示肺气肿，肺组织含气量增多使肺下界下移，故肺肝相对浊音界下移；语颤与肺泡呼吸音均减弱。"},{"q":"患者，女，35岁。多食、多汗、消瘦半年，心率106次/min，颈部可见肿大。该患者查体最可能出现的体征是","o":["甲状腺结节性肿大，无震颤或杂音","甲状腺弥漫性肿大，伴有震颤","甲状腺肿大并结节感，质地硬","颈静脉怒张","Oliver征"],"a":1,"e":"多食、多汗、消瘦伴心率增快与甲状腺肿大，符合甲状腺功能亢进，其腺体弥漫性肿大且因血流丰富可触及震颤、闻及血管杂音。"},{"q":"患者，女，62岁，反复右上腹疼痛，发热伴尿黄4年。2天前又出现右上腹绞痛，发冷、发热、尿黄来诊。下列表现均对本病诊断有意义，但除外","o":["胆囊肿大","墨菲征阳性","胆囊点压痛阳性","巩膜黄染","季肋点压痛阳性"],"a":4,"e":"右上腹痛、发热、尿黄反复发作提示胆道感染，胆囊可肿大并出现墨菲征与胆囊点压痛、巩膜黄染；季肋点压痛反映肾脏病变，与本例无关。"},{"q":"患者，女，34岁，双手关节痛伴晨僵2个月就诊。目前诊断类风湿关节炎的标志抗体是","o":["抗Sm抗体","抗SSB抗体","抗环瓜氨酸抗体","抗dsDNA抗体","抗RNP抗体"],"a":2,"e":"抗环瓜氨酸肽抗体对类风湿关节炎特异性高，是早期诊断与预后判断的标志抗体；抗Sm抗体、抗dsDNA抗体见于系统性红斑狼疮。"},{"q":"患者，女，37岁，患有风湿性心脏病，二尖瓣双病变。近半年来常有活动后心悸、气紧，双下肢水肿，夜间不能平卧。腹部检查：肝在右肋下3cm、剑突下5cm，表面光滑，质地稍韧，边缘圆钝，有弥漫性压痛，肝颈静脉反流征阳性。最可能的诊断是","o":["肝脓肿","肝淤血","脂肪肝","原发性肝癌","肝棘球蚴病"],"a":1,"e":"风心病伴右心衰竭时肝静脉回流受阻，肝脏淤血肿大、边缘圆钝、质稍韧并有弥漫性压痛，肝颈静脉回流征阳性为其特征；肝脓肿多有高热与局限性隆起。"},{"q":"患者，男，40岁。突起呕吐鲜血40ml，解柏油样便约300ml。既往查体提示脾大，HbSAg阳性。该患者查体一般不可能出现","o":["蜘蛛痣","肝大、质软","腹水","血压12.0/8.0kPa（90/60mmhg）","肠鸣音亢进"],"a":1,"e":"乙肝后肝硬化门静脉高压可致脾大、腹水、蜘蛛痣及食管静脉曲张破裂出血，肝脏因纤维化缩小变硬，故不会出现肝大而质软。"},{"q":"患者，女，34岁。因昏迷而被送往急诊，被怀疑有药物过量服用。动脉血气：pH 7、15，HCO3－ 28mEq/L，PaCO2 80mmHg，PaO2 65mmHg。该患者可能发生了","o":["急性呼吸性酸中毒并发严重的低氧血症","呼吸性碱中毒失代偿期","代谢性碱中毒部分代偿期","抽取的是静脉血","代谢性酸中毒部分代偿期"],"a":0,"e":"PaCO2 80mmHg伴pH显著下降、碳酸氢根仅轻度升高，符合急性CO2潴留所致的呼吸性酸中毒，同时PaO2降低提示低氧血症；代谢性酸中毒时碳酸氢根应明显降低。"},{"q":"患者，女，60岁，心悸2小时来急诊，心电图提示R-R间期绝对不齐，最可能的诊断是","o":["心房扑动不等比下传","心房颤动","房性心动过速伴房室结文氏传导","室性心动过速","心室颤动"],"a":1,"e":"RR间期绝对不齐、P波消失代之以f波，是心房颤动的特征性心电图表现；心房扑动呈规律锯齿状F波，室性心动过速QRS波宽大畸形。"},{"q":"患者，女，32岁。面黄、酱油色尿1周。查体：中度贫血貌，巩膜黄染，肝肋下未触及，脾肋下1cm。该患者最不可能出现的是","o":["结合胆红素轻度增高","非结合胆红素明显增高","总胆红素明显增高","尿胆原明显增高","尿胆红素阳性"],"a":4,"e":"酱油色尿伴黄疸、脾大提示血管内溶血，非结合胆红素升高而结合胆红素仅轻度增高、尿胆原增多，非结合胆红素不能经肾排出故尿胆红素阴性。"},{"q":"患者，女，25岁，关节疼痛、面部红斑、乏力半个月余。血常规示血红蛋白110g/L、血小板75×109/L，出血时间延长，束臂试验阳性，PT、APTT正常。抗核抗体阳性，抗双链DNA阳性，血小板P-选择素增高，尿常规示尿蛋白（＋）。该患者可能的诊断是","o":["原发免疫性血小板减少症","急性肾小球肾炎","慢性肾小球肾炎","肝硬化","系统性红斑狼疮"],"a":4,"e":"面部红斑、关节痛及多系统损害，伴抗核抗体与抗双链DNA抗体阳性，是系统性红斑狼疮的诊断依据；血小板减少与蛋白尿均为其脏器受累表现。"},{"q":"患者，男，35岁。反酸、胃灼热20天，伴饥饿痛。就诊消化科，怀疑消化性溃疡，行胃镜检查。其症状可能与下列哪种细菌感染有关","o":["空肠弯曲菌","痢疾志贺氏菌","幽门螺杆菌","胎儿弯曲菌","大肠弯曲菌"],"a":2,"e":"幽门螺杆菌定植于胃黏膜，是胃炎、胃溃疡与十二指肠溃疡的主要病因，饥饿痛伴反酸符合十二指肠溃疡；空肠弯曲菌多引起急性肠炎。"},{"q":"患者，男，37岁，饮酒后突发上腹部剧痛20min，伴恶心、呕吐、腹胀。查体：强迫体位，上腹部带状压痛，轻度肌紧张，无反跳痛。诊断首先考虑","o":["消化性溃疡穿孔","急性胰腺炎","急性胆囊炎","急性胃肠炎","急性阑尾炎"],"a":1,"e":"饮酒后突发上腹剧痛并向腰背放射，上腹带状压痛伴轻度肌紧张，符合急性胰腺炎；溃疡穿孔多有板状腹与膈下游离气体。"},{"q":"患者，女，54岁，活动后胸闷憋气20年，查体颊红，心尖部可及舒张期隆隆样杂音。该患者心电图最可能出现的改变是","o":["P波高耸","P波增宽","V5导联R波振幅大于等于2.5mV","aVF导联R波振幅大于等于2.0mV","RV5＋SV1≥3.5mV"],"a":1,"e":"二尖瓣狭窄使左心房压力负荷增高而肥大，心电图表现为P波增宽并呈双峰，即二尖瓣型P波；P波高尖见于右心房肥大。"},{"q":"患者，女，右上腹疼痛，向右肩放射，恶心、呕吐，伴畏寒发热1周。查体：急性病容，腹平坦，墨菲征阳性，右上腹局部肌紧张，反跳痛。该患诊断最可能为","o":["胆总管结石","化脓性胆管炎","胰头癌","胆道蛔虫","急性胆囊炎"],"a":4,"e":"右上腹痛向右肩放射伴畏寒发热，墨菲征阳性、右上腹肌紧张与反跳痛，提示炎症局限于胆囊，为急性胆囊炎；化脓性胆管炎以寒战高热、黄疸与休克为主。"},{"q":"患儿，男，2岁，出生后3个月时儿保于外院发现心脏杂音。查体：心尖冲动弥散，胸骨左缘第3/4肋间可闻及4/6级粗糙的全收缩期杂音，传导广泛，伴震颤。应诊断为","o":["主动脉瓣狭窄","二尖瓣狭窄","室间隔缺损","房间隔缺损","动脉导管未闭"],"a":2,"e":"胸骨左缘第3～4肋间响亮粗糙的全收缩期杂音伴震颤，是室间隔缺损的典型杂音；动脉导管未闭为胸骨左缘第2肋间连续性机器样杂音。"},{"q":"患者，男，78岁，高血压病史10年，间断服用降压药，未规律监测血压。3小时前晨练时突然倒地意识丧失、角膜反射减弱、瞳孔对光反射迟钝，其意识障碍程度属","o":["轻度昏迷","中度昏迷","深度昏迷","昏睡","嗜睡"],"a":1,"e":"中度昏迷者对各种刺激无反应，仅剧烈刺激出现防御反射，角膜反射减弱、瞳孔对光反射迟钝、眼球无转动；深度昏迷则各种反射均消失。"},{"q":"患者，女，35岁。鼻出血、躯干及四肢瘀点瘀斑2天。2周前有感冒病史。血常规示血小板10×109/L，单克隆抗体血小板抗原固定试验阳性，出血时间12min，束臂试验阳性，PT、APTT正常。该患者可能的诊断是","o":["血管性血友病","原发免疫性血小板减少症","血小板无力症","再生障碍性贫血","弥散性血管内凝血"],"a":1,"e":"血小板显著减少而凝血功能正常，出血时间延长、束臂试验阳性伴血小板自身抗体阳性，符合原发免疫性血小板减少症；血管性血友病以APTT延长为特点。"},{"q":"患者，女，44岁，月经量增多7个月余，发现血小板减少5个月余，查体见全身多发皮下3～5mm小红点，受压不褪色。最可能的诊断是","o":["斑疹","紫癜","荨麻疹","瘀点","血肿"],"a":1,"e":"皮下出血直径3～5mm者称紫癜，压之不褪色；直径小于2mm为瘀点，大于5mm为瘀斑，片状出血伴皮肤显著隆起为血肿。"},{"q":"患者，男，35岁，阵发性心悸3年，每次持续半小时至5小时不等，休息可终止。本次发作时心电图提示Ⅱ导联可见直立圆钝P波，心率140次/min，律齐。诊断最可能是","o":["心房扑动呈4∶1下传","心房颤动","阵发性室性心动过速","窦性心动过速","阵发性交界区心动过速"],"a":3,"e":"心动过速时各导联可见形态正常的直立窦性P波且P-QRS关系固定，为窦性心动过速；房室折返性心动过速多无可见P波或呈逆行P波。"},{"q":"患者，女，24岁，近1周出现肉眼血尿，伴尿频、腰酸，双下肢无水肿。查体：双肾区叩击痛（＋）。血常规正常，尿常规示尿蛋白（－），镜检WBC（＋＋＋），RBC（＋＋＋＋）。该患者最可能的诊断是","o":["急性肾炎","尿路结石","尿路感染","泌尿系肿瘤","功能性血尿"],"a":2,"e":"尿频、尿急伴肾区叩击痛及尿中大量白细胞而蛋白阴性，提示下尿路与肾盂感染，为尿路感染；急性肾炎以蛋白尿、血尿与水肿为主。"},{"q":"患者，女，糖尿病3年，血糖控制不佳。1天前入院明确诊断为糖尿病酮症酸中毒。该患者目前最可能出现的呼吸改变为","o":["潮式呼吸","间停呼吸","抑制性呼吸","叹气样呼吸","库斯莫尔呼吸"],"a":4,"e":"糖尿病酮症酸中毒时细胞外液碳酸氢根不足、pH降低，通过深而快的呼吸排出CO2代偿，称库斯莫尔呼吸；潮式呼吸见于中枢性呼吸抑制。"},{"q":"患者，女，42岁，突然上腹痛1天，渐重，恶心，呕吐。来诊后急查血尿淀粉酶，均明显高于正常。该患最可能的病因为","o":["胆道结石","急性胰腺炎","病毒感染","磺胺类药物","遗传或代谢障碍"],"a":1,"e":"突发上腹痛伴恶心呕吐、血尿淀粉酶明显升高，是急性胰腺炎的主要诊断依据；胆道结石多有右上腹绞痛与黄疸，淀粉酶升高不明显。"},{"q":"中年男性，突发恶心，头晕，呕新鲜血1000ml，出虚汗，无腹痛，查体：BP 10/8kPa（1kPa≈7.5mmHg），巩膜无黄染，心率120次/min，腹软，无压痛，肝脾未触及。最可能的诊断是","o":["十二指肠溃疡","食管-胃底静脉曲张破裂","胃癌","Mallory-Weiss综合征","急性胃黏膜病变"],"a":1,"e":"无痛性大量呕血伴休克、腹软无压痛，符合门静脉高压所致食管胃底静脉曲张破裂出血；溃疡出血多有节律性上腹痛史，贲门黏膜撕裂见于剧烈呕吐后。"},{"q":"患者，女，35岁。10年来经常出现发热伴四肢关节肿胀、酸痛。近2年来出现咳嗽伴夜间阵发性呼吸困难。查体：口唇及双面颊部发绀，脉搏90次/min，不齐，听诊心律不规整，第一心音强弱不等，心率130次/min，心尖部可闻及舒张期隆隆样杂音。最可能的诊断","o":["风湿性心脏病，二尖瓣狭窄","风湿性心脏病，二尖瓣关闭不全","甲状腺功能亢进症","病毒性心肌炎","风湿性心脏病，三尖瓣狭窄"],"a":0,"e":"心尖部舒张期隆隆样杂音伴第一心音强弱不等、心律不齐，是风湿性二尖瓣狭窄合并心房颤动的表现；二尖瓣关闭不全为心尖区全收缩期吹风样杂音。"},{"q":"患者，男，82岁，糖尿病合并高血压30余年，自诉1个月内突发步行时下肢酸痛乏力，稍休息后可缓解，而后仍可行走。此时患者可能存在的步态是","o":["蹒跚步态","共济失调步态","慌张步态","跨阈步态","间隙性跛行"],"a":4,"e":"步行中下肢酸痛乏力、休息后缓解、再走又发，为间歇性跛行，见于下肢动脉硬化闭塞；慌张步态见于帕金森病，跨阈步态见于腓总神经麻痹。"},{"q":"患者，男，35岁。既往胆囊结石病史。近1周右上腹痛，呈剧烈绞痛，2天前出现黄疸。查体见表情痛苦，不安，巩膜黄染。该患者最可能的诊断是","o":["急性胰腺炎","急性胆囊炎","急性心肌梗死","急性阑尾炎","急性胃炎"],"a":1,"e":"胆囊结石梗阻胆囊管后胆汁淤积、胆囊壁炎症水肿，出现右上腹绞痛、黄疸与局部压痛，符合急性胆囊炎；急性胰腺炎疼痛位于上腹中部并向腰背放射。"},{"q":"患者，男，20岁，感冒后7天出现颜面及双下肢水肿，尿少。血压150/100mmHg。尿蛋白（＋＋），潜血（＋＋），尿沉渣：红细胞104/HPF。2周后少尿，BUN 8.2mmol/L，Scr 159、3μmol/L，哪种疾病可能性大","o":["急性肾小球肾炎","急性肾盂肾炎","慢性肾炎","肾病综合征","高血压肾病"],"a":0,"e":"链球菌感染后1～2周出现血尿、蛋白尿、水肿与高血压，伴少尿及氮质血症，符合急性肾小球肾炎；肾病综合征以大量蛋白尿与低白蛋白血症为主。"},{"q":"患者，男，65岁。近2个月食欲缺乏伴上腹部无规律性疼痛，体重下降6kg。胃镜示胃小弯处有一3.4cm×2.6cm的较大溃疡，边缘不整齐伴坏死。哪组区域的浅表淋巴结肿大最有诊断意义","o":["颈前淋巴结","颈后淋巴结","锁骨上窝淋巴结","腋窝淋巴结","腹股沟淋巴结"],"a":2,"e":"胃癌经胸导管转移至左锁骨上淋巴结，形成质硬无痛的Virchow淋巴结，对胃癌诊断意义最大；颈前淋巴结多引流甲状腺与咽喉部。"},{"q":"患者，男，40岁，反复饥饿时中上腹部隐痛10年，伴反酸嗳气，在进食和服制酸剂后可缓解，今晨中上腹剧痛后腹痛持续存在。该患者可能发生的并发症是","o":["急性胰腺炎并发出血坏死","胰腺癌并发肠梗阻","胃癌并发幽门梗阻","消化性溃疡并发急性穿孔","急性胆囊炎并发胆汁性腹膜炎"],"a":3,"e":"溃疡病人疼痛节律消失、突发持续剧痛，提示溃疡穿透浆膜层发生急性穿孔；穿孔后胃肠内容物刺激腹膜引起化学性腹膜炎。"},{"q":"患者四肢麻木入院。查体发现四肢末梢存在手套、袜套样痛觉减退。考虑患者损伤位于以下哪一部位","o":["脊髓后根","脊髓后角","丘脑","四肢末梢神经","大脑皮层"],"a":3,"e":"四肢对称性手套、袜套样痛觉减退是末梢神经受损的表现，多见于多发性神经病；脊髓后角或后根损害呈节段性分布。"},{"q":"患者，女，25岁。反复发热、咳嗽、咳痰3年，间歇性痰中带血3个月。右下肺可闻及固定局限的湿啰音。最可能的诊断是","o":["胸腔积液","大叶性肺炎","肺癌","支气管扩张","慢性支气管炎"],"a":3,"e":"长期咳嗽咳痰伴间歇痰中带血、右下肺固定局限的湿啰音，是支气管扩张的典型表现；大叶性肺炎病程短，湿啰音随炎症消散而变化。"},{"q":"患者，男，46岁。满腹剧痛10小时，腹部检查发现腹式呼吸运动减弱，腹部稍隆起，触诊全腹腹肌紧张，压痛和反跳痛。该患者最可能的诊断是","o":["急性腹膜炎","急性阑尾炎","急性胰腺炎","肝硬化","结核性腹膜炎"],"a":0,"e":"全腹肌紧张、压痛与反跳痛伴腹式呼吸减弱、腹部膨隆，为腹膜炎三联征，提示急性弥漫性腹膜炎；局限性腹膜炎体征局限于病变部位。"},{"q":"患者，男，77岁。吸烟50年，常年咳嗽、咳痰，近10年出现活动性呼吸困难，进行性加重。查体：桶状胸，双肺呼吸音减弱，未闻及明显干、湿啰音。最可能的诊断为","o":["慢性支气管炎并发肺气肿","气胸","胸腔积液","大叶性肺炎","慢性支气管炎"],"a":0,"e":"长期吸烟者咳嗽咳痰多年后出现进行性活动后呼吸困难，桶状胸、双肺呼吸音减弱而无明显啰音，符合慢性支气管炎并发肺气肿。"},{"q":"患者，男，39岁，突然左腰部钻顶样疼痛，大汗淋漓。他最可能采取的体位是","o":["辗转体位","被动体位","强迫侧卧位","强迫仰卧位","强迫坐位"],"a":0,"e":"输尿管结石引起肾绞痛时疼痛剧烈难忍，病人辗转反侧、坐卧不安，取辗转体位；强迫侧卧位见于胸膜疾病，强迫坐位见于心肺功能不全。"},{"q":"患者，女，42岁，有糖尿病病史，自13岁以来就一直使用胰岛素。患者定向力差，查体：T 38.8℃，WBC 14×109/L。床旁血气分析：pH 7.23，PaCO2 25mmHg。HCO3－ 12mEq/L，PaO2 118mmHg。该患者可能发生了","o":["代谢性酸中毒部分代偿期","呼吸性碱中毒失代偿期","代谢性碱中毒部分代偿期","呼吸性酸中毒与低氧血症代偿期","抽取的是静脉血"],"a":0,"e":"pH 7.23、HCO3- 12mmol/L明显降低而PaCO2 25mmHg为代偿性过度通气，符合代谢性酸中毒部分代偿；呼吸性碱中毒时pH应升高。"},{"q":"患者，老年女性，反复双下肢水肿半年入院。既往患慢性肾小球肾炎。尿常规：蛋白＋＋＋，血Hb92g/L。肾功能：血肌酐250μmol/L，尿素氮13.4mmol/L。为明确患者肾功能不全分期，还需进一步做哪项检查","o":["尿β2-微球蛋白测定","血β2-微球蛋白测定","内生肌酐清除率测定","血尿酸测定","血清胱抑素测定"],"a":2,"e":"内生肌酐清除率能反映肾小球滤过率，是判断肾功能损害程度与分期的主要指标；血肌酐受肌肉量影响，敏感性低于肌酐清除率。"},{"q":"患者，男，37岁。腰痛伴右下肢放射性痛2个月，无发热、盗汗。查体：右侧直腿抬高实验阳性，小腿前外侧和足底感觉减退。该患者最可能的诊断是","o":["腰椎间盘突出症","腰肌劳损","腰椎肿瘤","腰椎结核","强直性脊柱炎"],"a":0,"e":"腰痛伴下肢放射性痛、直腿抬高试验阳性及相应皮节感觉减退，是腰椎间盘突出压迫神经根的表现；腰肌劳损无神经根性放射痛。"},{"q":"患者，女，68岁，诉心悸、晕厥，动态心电图结果提示：平均心室率＜40次/min，有窦性停搏，最长RR间期达2.8s。临床诊断考虑","o":["预激综合征","房室传导阻滞","窦性心动过缓","病态窦房结综合征","期前收缩"],"a":3,"e":"窦性停搏、最长RR间期2.8秒伴平均心室率低于40次/min及晕厥，是窦房结起搏与传导功能衰竭的表现，符合病态窦房结综合征。"},{"q":"患者，男，48岁，因饱餐后突发上腹部剧痛2小时急诊入院。腹部X片示膈下半月形游离气体。该患者入院时可能的体位是","o":["被动体位","辗转体位","强迫侧卧位","强迫仰卧位","强迫俯卧位"],"a":3,"e":"膈下游离气体提示胃肠道穿孔并发急性腹膜炎，腹膜受刺激后病人取仰卧、双腿蜷曲以减轻腹肌紧张，为强迫仰卧位。"},{"q":"患者，男，54岁。会阴部肿胀2个月。查体：会阴部透光试验阳性。该患者最可能的诊断是","o":["腹股沟斜疝","精索鞘膜积液","睾丸肿瘤","阴囊外伤水肿","丝虫病"],"a":1,"e":"会阴部肿大而透光试验阳性，说明肿物为液性且透光良好，符合鞘膜积液；阴囊疝与睾丸肿瘤不透光，可借此鉴别。"},{"q":"患者，男，60岁。主诉：咳嗽、咯血3个月余。既往：吸烟30年，20支/d。查体：右肺呼吸明显降低，叩诊实音。右侧锁骨上淋巴结肿大。该患者最可能的咯血出血形式是","o":["痰中带血","暗红色黏液痰","大咯血","脓血痰","粉红色泡沫痰"],"a":0,"e":"长期吸烟、咳嗽咯血伴右肺实变体征与锁骨上淋巴结肿大提示支气管肺癌，肺癌少有大咯血，多表现为痰中带血。"},{"q":"患者，女，45岁，因右侧胸痛并气促10小时来诊。肺部CT可见右下肺有楔形实变影。超声检查发现左下肢深静脉有血栓形成。近1个月有口服药物避孕史，家族中无类似患者。以下哪项描述不正确","o":["因为在血栓栓塞急性期，所以应该积极溶栓治疗","华法林可以抑制多种凝血因子活性，应该单独在溶栓后立即使用","因华法林前期有抑制蛋白C和蛋白S的作用，所有早期需要与肝素合用","在抗凝过程中维持INR在2.0～2.5","应该行狼疮抗凝物的筛查"],"a":1,"e":"华法林抑制维生素K依赖性凝血因子合成，同时降低蛋白C、蛋白S活性，起效慢且早期有促凝倾向，须与肝素重叠使用而非溶栓后单独立即使用。"},{"q":"患者，女，发现周身水肿、血脂升高2年，入院检查血清白蛋白25.8g/L，尿常规结果显示尿蛋白（＋＋＋＋），说明","o":["肾小球滤过膜改变","肾小管对蛋白回吸收障碍","功能性蛋白尿","组织性蛋白尿","偶然性蛋白尿"],"a":0,"e":"尿蛋白4＋伴低白蛋白血症与高脂血症，提示肾小球滤过膜屏障受损、大分子蛋白大量漏出，属肾小球性蛋白尿。"},{"q":"患者因“头痛1天”入院。查体：患者去枕仰卧，一侧下肢髋、膝关节屈曲直角，检查者将患者小腿抬高伸膝仅90°即感到痛。这提示患者哪项检查阳性","o":["直腿抬高实验","4字实验","Kernig征","Brudzinski征","Hoffmann征"],"a":2,"e":"屈髋屈膝成直角后伸膝受限并引起疼痛即为Kernig征阳性，提示脑膜受刺激；Brudzinski征为屈颈时双下肢屈曲。"},{"q":"患者，男，50岁，反复出现尿频、尿急2年，偶伴无痛性肉眼血尿，无水肿。查体双肾无叩击痛。尿常规示尿蛋白（－），镜检WBC 0～4个/HPF，RBC（＋＋）。该患者最可能的诊断是","o":["肾结核","膀胱炎","膀胱癌","前列腺增生症","慢性肾炎"],"a":2,"e":"尿频尿急多年后出现无痛性肉眼血尿而尿蛋白阴性，符合膀胱肿瘤表现；膀胱炎以尿痛、脓尿为主，肾结核多有结核中毒症状。"},{"q":"患者，女，20岁，皮肤瘀斑反复发作伴月经增多2年。无出血性疾病家族史。肝脾不大。血常规：血红蛋白100g/L，血小板120×109/L。出血时间正常，束臂试验阳性，PT、APTT正常，血小板黏附及聚集功能均正常。该患者可能的诊断为","o":["过敏性紫癜","原发免疫性血小板减少症","单纯性紫癜","血友病A","血管性血友病"],"a":2,"e":"女性月经期反复四肢瘀斑，血小板计数与凝血功能正常、束臂试验阳性，提示血管壁脆性增加，符合单纯性紫癜；过敏性紫癜多伴关节痛与腹痛。"},{"q":"患者，男，25岁。有左下肢深静脉血栓性静脉炎，突然左胸痛，伴有气短。查体：呼吸急促，气管居中，双肺叩之清音，呼吸音正常，左下肺湿啰音。最可能的诊断是","o":["肺栓塞","肺炎","气胸","心绞痛","急性左心衰竭"],"a":0,"e":"深静脉血栓病人突发胸痛、气短与呼吸急促，左下肺闻及湿啰音，符合血栓脱落导致的肺栓塞；气胸叩诊呈鼓音，肺炎多有发热与实变体征。"},{"q":"患者，男，45岁。突发胸骨后压榨样疼痛，最可能的原因是","o":["食管癌","自发性气胸","胸膜炎","心肌梗死","心包炎"],"a":3,"e":"突发胸骨后压榨样疼痛并有濒死感，是急性心肌梗死的典型表现；心绞痛虽亦为压榨样痛，但持续时间短，休息或含服硝酸酯类可缓解。"},{"q":"患者，女，26岁，明确诊断大动脉炎，血沉明显升高。今晨活动后出现明显胸闷伴疼痛，约1小时入院，可能的诊断是","o":["急性前壁缺血","左主干病变伴广泛心肌缺血","变异型心绞痛","急性下壁缺血","陈旧前壁心肌梗死伴室壁瘤形成"],"a":1,"e":"大动脉炎累及主动脉根部与冠状动脉开口，以左主干开口狭窄最常见，可致广泛前壁心肌缺血而出现持续胸闷胸痛。"},{"q":"患者，女，20岁，反复四肢紫癜3年，感冒时尤甚。血常规：WBC 5、0×109/L，血小板计数30×109/L，Hb 100g/L，脾无肿大，血小板自身抗体阳性。最可能的诊断是","o":["过敏性紫癜","单纯性紫癜","血友病","慢性弥散性血管内凝血","原发免疫性血小板减少症"],"a":4,"e":"反复紫癜伴血小板显著减少、脾不肿大、血小板自身抗体阳性，符合原发免疫性血小板减少症；过敏性紫癜血小板计数正常。"},{"q":"患者，女，18岁，下肢水肿、少尿15天，近2天出现发热。尿常规尿蛋白（＋＋＋），白细胞10～13个/HPF，红细胞13～15个/HPF，红细胞管型0～1个/LPF。最可能的诊断是","o":["肾病综合征合并上呼吸道感染","肾病综合征合并泌尿系统感染","感染所致尿改变","急性肾盂肾炎","急性肾炎合并泌尿系统感染"],"a":4,"e":"上呼吸道感染后出现水肿、少尿与蛋白尿、镜下血尿及红细胞管型，符合急性肾炎；病程中出现发热、尿白细胞增多提示合并泌尿系统感染。"},{"q":"患者，男，63岁。吸烟，反复咳嗽、咳白色泡沫痰20余年，气促10年。2天前因受凉后出现发热伴咳黄脓痰，气喘不能平卧。查体：双肺语颤减弱，可闻及散在干、湿啰音。该患者最可能的诊断是","o":["慢性阻塞性肺疾病","肺大疱","支气管扩张","肺结核","肺癌"],"a":0,"e":"长期吸烟者慢性咳嗽咳痰后出现气促，双肺语颤减弱、散在干湿啰音，符合慢性阻塞性肺疾病急性加重；支气管扩张多有大量脓痰与固定湿啰音。"},{"q":"患者，女，47岁。外阴瘙痒，灼痛，白带增多呈豆腐渣样。阴道分泌物清洁度分级为Ⅳ级。最可能的诊断是","o":["细菌性阴道炎","真菌性阴道炎","子宫内膜炎","老年性阴道炎","子宫颈癌"],"a":1,"e":"豆腐渣样白带伴外阴瘙痒灼痛、清洁度Ⅳ级，是念珠菌性阴道炎的表现；细菌性阴道病因厌氧菌过度繁殖而呈稀薄奶油样分泌物伴鱼腥味。"},{"q":"患者，男，19岁，上呼吸道感染后持续发热，胸部CT考虑为大叶性肺炎，并且病灶累及胸壁。患者不会出现下列哪项体征","o":["患侧呼吸音减弱","可闻及管状呼吸音","可闻及湿啰音","硬币叩击征","胸膜摩擦音"],"a":3,"e":"大叶性肺炎实变期可闻及管状呼吸音与湿啰音，累及胸膜时可闻及胸膜摩擦音，患侧呼吸音减弱；硬币叩击征见于气胸，本例不会出现。"},{"q":"患者，男，48岁，10年少量饮酒史。近1个月上腹疼痛，饥饿时加重，呈现疼痛－进食－缓解的规律。最可靠的诊断措施是","o":["超声检查","上消化道内镜","上消化道钡餐","依据临床表现","根据药物的治疗效果"],"a":1,"e":"有节律性上腹痛而疑诊消化性溃疡时，上消化道内镜可直接观察黏膜病变并取活检，是诊断最可靠的方法；钡餐与超声只能间接提示。"},{"q":"患者，男，35岁，劳力性心悸气短1年，心悸3个月。诊断风湿性心脏病、二尖瓣狭窄、快室率心房颤动，予以地高辛0.25mg、1次/d，患者用药后心电图的改变不包括","o":["T波高耸，基底部狭窄，呈帐篷型T波","ST段下垂型压低","ST-T呈“鱼钩型”","双向T波，初始部分倒置，终末部分直立","Q-T间期缩短"],"a":0,"e":"洋地黄中毒的心电图表现为ST段下垂型压低、ST-T呈鱼钩样改变、T波双向及Q-T间期缩短；帐篷型高尖T波是高血钾的特征。"},{"q":"一长期头歪的小儿患者来院检查，接诊医生发现患者颈部胸锁乳突肌萎缩，头部向右侧转无力。据此推测，患儿损伤部位为以下哪部分","o":["颈第5～6神经根","左侧副神经","右侧副神经","臂丛神经","面神经"],"a":1,"e":"左侧胸锁乳突肌萎缩、头向右转无力，提示左侧副神经受损，该神经支配胸锁乳突肌与斜方肌，受损时向对侧转头及同侧耸肩无力。"},{"q":"患者，男，41岁。阵发性心悸气短2年，M型超声心动图检查见二尖瓣前叶CD段于全收缩期呈吊床样下垂，二维超声心动图示收缩期二尖瓣前叶向左房脱出并超过瓣环连线。下列哪项体征具有诊断意义","o":["心尖区舒张中晚期隆隆样杂音伴开瓣音","心尖区收缩中期喀喇音并收缩晚期杂音","心尖区舒张晚期杂音并舒张早期奔马律","心尖区舒张中晚期杂音并肿瘤落音","心尖区全收缩期杂音并舒张时晚期奔马律"],"a":1,"e":"收缩中晚期二尖瓣叶脱入左房使腱索突然紧张，产生收缩中期喀喇音，继而瓣叶关闭不全出现收缩晚期杂音，是二尖瓣脱垂的特征。"},{"q":"患者，女，30岁，近期为乌发多次服用何首乌，近2日出现目黄、尿黄。既往无肝炎病史、无饮酒史，无家族性疾病。其黄疸最可能的原因是","o":["病毒性肝炎","脂肪肝","自身免疫性肝病","肝硬化","药物性肝病"],"a":4,"e":"服用何首乌后出现黄疸，无病毒性肝炎及饮酒史，符合药物性肝病；药物或其代谢产物可直接损伤肝细胞或引起肝内胆汁淤积。"},{"q":"患者，女，31岁，头痛、呕吐、意识不清1天入院。化验检查脑脊液中氯化物明显减少，考虑诊断为","o":["结核性脑膜炎","化脓性脑膜炎","病毒性脑膜炎","隐球菌性脑膜炎","流行性乙型脑炎"],"a":0,"e":"脑脊液氯化物明显降低以结核性脑膜炎最显著，机制为细菌分解葡萄糖产酸使脑脊液呈酸性，加之蛋白增高；化脓性脑膜炎以中性粒细胞增高为主。"},{"q":"患者，女，19岁，受凉后突然畏寒，高热，左侧胸痛伴咳嗽，咯少量铁锈色痰，胸部X片见左下肺大片淡薄阴影。其最可能的诊断是","o":["金黄色葡萄球菌肺炎","肺炎球菌性肺炎","原发性支气管癌合并阻塞性肺炎","结核性胸膜炎","急性原发性肺脓肿"],"a":1,"e":"受凉后寒战高热、胸痛、咳铁锈色痰伴肺段性大片阴影，是肺炎链球菌肺炎的典型表现；金黄色葡萄球菌肺炎多咳脓血痰、易形成肺脓肿。"},{"q":"患者，女，32岁。阵发性劳力性呼吸困难3年，咳痰带血丝1个月。M型超声心动图检查可见二尖瓣前叶呈城墙样改变，后叶同向运动。下列体征具有诊断意义的是","o":["心尖区3级收缩期杂音，向腋下传导","肺动脉瓣区第二心音亢进伴有分裂","胸骨左缘第2肋间Graham-Steell杂音","心尖区隆隆样舒张中晚期杂音","心尖区隆隆样舒张早期杂音"],"a":3,"e":"二尖瓣前叶呈城墙样改变提示二尖瓣狭窄，其最具诊断意义的体征是心尖区舒张中晚期递增型隆隆样杂音，常伴第一心音亢进与开瓣音。"},{"q":"患者，男，26岁。间歇性水肿6年，近1周水肿加重。尿蛋白（＋＋＋）。血生化：总蛋白51、2g/L，清蛋白20、5g/L。最可能的诊断是","o":["肝炎后肝硬化","原发性高血压","慢性肾盂肾炎","慢性肾小球肾炎","肾病综合征"],"a":4,"e":"大量蛋白尿伴血清白蛋白低于30g/L及明显水肿，符合肾病综合征的诊断标准；慢性肾小球肾炎多有高血压与肾功能减退，蛋白尿程度较轻。"},{"q":"患者，女，45岁。近4年来经常腰痛，劳累及气候变化时加剧。3天前搬重物后腰痛加剧，疼痛放射至左下肢。最可能的疾病是","o":["脊椎结核","类风湿关节炎","强直性脊柱炎","腰椎间盘突出症","腰肌劳损"],"a":3,"e":"搬重物后腰痛加剧并向一侧下肢放射，提示椎间盘突出压迫神经根，符合腰椎间盘突出症；腰肌劳损疼痛局限于腰部，无放射痛。"},{"q":"患者，女，42岁，因“反复活动后胸闷，气短5年”入院。查体：面颊部紫红色，口唇发绀，左侧卧位心尖区可闻及舒张中期隆隆样杂音。患者可能出现的面容为","o":["慢性病容","满月面容","肾病面容","二尖瓣面容","贫血面容"],"a":3,"e":"双颊紫红、口唇发绀伴心尖区舒张期隆隆样杂音，是二尖瓣狭窄所致的二尖瓣面容；满月面容见于库欣综合征。"},{"q":"患者，女，70岁，左侧肢体不自在抖动、僵硬5年，右侧肢体受累3个月入院。查体：面部呆板、无表情、行动迟缓、小碎步。该患者最可能的诊断是","o":["脑梗死","脑性瘫痪","小脑疾病","帕金森病","脊髓病变"],"a":3,"e":"静止性震颤、肌强直、运动迟缓伴面具脸与小碎步，是帕金森病的典型表现；小脑病变以共济失调和意向性震颤为主。"},{"q":"患者，男，66岁，咳嗽、咳痰、痰中带血3个月余。既往抽烟40余年，查体可触及颈前肿大淋巴结，质硬，无压痛，与周围组织粘连明显。该患者最可能的疾患是","o":["囊肿","非特异性淋巴结炎","囊状瘤","恶性肿瘤","血液系统疾病"],"a":3,"e":"颈部淋巴结质硬、无压痛、与周围组织粘连固定，符合恶性肿瘤淋巴结转移；非特异性淋巴结炎质地较软且有压痛。"},{"q":"患者，女，68岁，腹痛、腹胀半年余，进食后加重。今日晨起排便，粪便呈黑色、发亮，遂来就诊。考虑诊断为","o":["肛裂","胆道结石","幽门梗阻","上消化道出血","过敏性肠炎"],"a":3,"e":"黑便发亮提示血液经肠道作用形成硫化铁，出血部位在屈氏韧带以上，为上消化道出血；胆道结石与幽门梗阻不以黑便为主要表现。"},{"q":"患者，女，37岁，患风湿性心脏病20余年，心脏彩超示二尖瓣狭窄。1周前感冒后出现呼吸困难、咳嗽、水肿，查体可见颈静脉怒张。最可能出现以下哪种情况","o":["上腔静脉阻塞","下腔静脉阻塞","左心衰竭","右心衰竭","主动脉瓣关闭不全"],"a":3,"e":"二尖瓣狭窄致肺动脉高压、右心室负荷加重，失代偿时体循环淤血，出现颈静脉怒张与水肿，符合右心衰竭；左心衰竭以肺淤血和呼吸困难为主。"},{"q":"患者，女，57岁。水肿、间断血尿18年。查体：血压190/120mmHg，BUN 27mmol/L，CO2CP 12mmol/L，血清钾7.2mmol/L，血清钙1.95mmol/L，血红蛋白50g/L。则其心电图表现最可能是","o":["Q-T间期缩短，T波高耸，基底部狭窄","ST段压低，T波低平及U波增高","U波倒置","ST段水平下移","QRS波群明显增宽，Q-T间期延长"],"a":4,"e":"血清钾7.2mmol/L属严重高血钾，心电图表现为QRS波群增宽、PR及Q-T间期延长、T波高尖；U波增高见于低血钾。"},{"q":"患者，男，38岁。右手腕部外伤后出现“枪刺刀”畸形。该患者最可能的诊断是","o":["耻骨骨折","尺神经损伤","Smith骨折","Colles骨折","桡神经损伤"],"a":3,"e":"桡骨远端骨折远折端向背侧移位，侧面观呈枪刺刀样、正面观呈餐叉样畸形，为Colles骨折的典型表现；Smith骨折远折端向掌侧移位。"},{"q":"患者，男，48岁。于3年前年开始出现头昏、头重，多次在当地医院按照脑供血不足进行治疗，但症状时好时坏。4个月前头昏加重，自觉头脑不清醒，情绪低落，疲倦乏力、精力不足，兴趣减退、厌恶交际，入睡困难、注意力不集中、记忆力减退，性功能障碍。该患者最可能的诊断是","o":["焦虑症","抑郁症","人格障碍","睡眠障碍","躯体形式障碍"],"a":1,"e":"持续情绪低落、兴趣减退、精力不足伴睡眠障碍与性功能障碍，符合抑郁症的诊断；焦虑症以过分担心和自主神经症状为主。"},{"q":"患者，男，18岁。诊断1型糖尿病2年，平时每日用胰岛素32U，血糖控制正常。近1周因胰岛素用完停用。此次因“乏力3天，昏迷3小时”入院，拟诊“糖尿病酮症酸中毒”。患者呼吸为何种气味，能支持该诊断","o":["大蒜味","芳香味","氨臭味","肝臭味","烂苹果味"],"a":4,"e":"酮症酸中毒时脂肪大量分解产生酮体，丙酮经肺排出使呼吸带烂苹果味；有机磷中毒呼吸呈蒜味，肝坏死病人口腔有肝臭味。"},{"q":"患者，女，30岁，腹胀大3年。查体：腹如足月妊娠大小，无压痛，肝脾触不清，叩诊腹中部浊音，两侧鼓音，浊音不随体位改变。下列诊断可能性最大的是","o":["肝硬化腹水","巨大卵巢囊肿","结核性腹膜炎","原发性肝癌","自发性腹膜炎"],"a":1,"e":"腹中部浊音、两侧鼓音且浊音不随体位移动，是肠管被巨大囊肿挤向两侧所致，符合巨大卵巢囊肿；腹腔积液时浊音位于两侧且随体位移动。"},{"q":"患者，女，68岁。近4年来，每年冬季咳嗽、咳白色黏痰，伴气喘。近1周症状加重，无发热。此患者可能出现的异常体征","o":["支气管呼吸音","支气管肺泡呼吸音","支气管呼吸音＋湿啰音","哮鸣音","语音震颤增强"],"a":2,"e":"气道黏膜充血水肿、分泌物潴留使呼吸音传导增强，可闻及支气管呼吸音，气道内渗出物随呼吸移动产生湿啰音，为慢性支气管炎急性发作的体征。"},{"q":"患者，男，56岁。半年前开始反复出现腹胀、食欲缺乏。曾患乙型病毒性肝炎。查体手掌大小鱼际处发红，颈部可见一血管痣。患者该体征的形成原因可能是","o":["雄激素减少","醛固酮增多","抗利尿激素分泌增多","雄激素的灭活减少","雌激素增多"],"a":4,"e":"肝硬化时肝脏对雌激素灭活减弱，雌激素水平升高使手掌大、小鱼际处毛细血管扩张发红，形成肝掌，与蜘蛛痣发生机制相同。"},{"q":"患者，女，54岁，既往曾患亚急性甲状腺炎，近期肥胖，颜面明显，伴下肢黏液性水肿。该患者肥胖最可能的原因是","o":["单纯性肥胖","下丘脑性肥胖","库欣综合征","甲状腺功能减退症","多囊卵巢综合征"],"a":3,"e":"甲减时黏多糖在皮下组织沉积，形成非凹陷性黏液性水肿并致体重增加，脂肪沉积以颈部明显；库欣综合征为向心性肥胖伴满月脸。"},{"q":"患者，男，23岁，抵抗力下降、反复感染1年，结合相关检查诊断为艾滋病。该患者粪便检查可能发现","o":["钩虫","纤毛虫","鞭毛虫","隐孢子虫","阿米巴原虫"],"a":3,"e":"艾滋病病人免疫功能缺陷，易感染隐孢子虫而引起持续性腹泻，粪便呈稀水样；该原虫在免疫功能正常者多无症状。"},{"q":"患者，男，25岁。突发右侧胸痛、胸闷、呼吸困难，下列最可能出现的体征是","o":["胸壁静脉曲张","皮下气肿","右侧肋间隙变窄","胸壁压痛","胸骨叩击痛"],"a":1,"e":"自发性气胸若胸膜腔内压持续升高，气体可沿破裂口进入胸壁皮下组织形成皮下气肿，触诊有捻发感或握雪感。"},{"q":"一患者反复咳嗽、咳脓痰、咯血，每次胸片示同一部位呈卷发样阴影改变，在听诊时应出现哪种改变","o":["两肺底可闻及捻发音","支气管语音","局限性水泡音","高调干啰音","低调干啰音"],"a":2,"e":"支气管扩张时支气管壁破坏、分泌物潴留，同一部位反复感染，听诊可闻及固定局限的湿啰音，即局限性水泡音。"},{"q":"患者，男，77岁。吸烟50年，常年咳嗽、咳痰，近10年出现活动性呼吸困难、并进行性加重。明确诊断为慢性支气管炎合并肺气肿，其肺部叩诊呈","o":["清音","过清音","鼓音","浊音","实音"],"a":1,"e":"肺气肿时肺组织含气量增多、弹性回缩力下降，叩诊音调更低、时限更长、反响增强，呈过清音；鼓音见于气胸或肺大空洞。"},{"q":"患者，男，18岁。淋雨后出现咳嗽、咳痰，伴高热寒战，肺部叩诊呈浊音，气管无偏移。该患者主要考虑","o":["肺结核","支气管肺炎","大叶性肺炎","自发性气胸","肺不张"],"a":2,"e":"淋雨后寒战高热、咳嗽咳痰伴肺实变体征而气管居中，符合肺炎链球菌引起的大叶性肺炎；肺不张时气管向患侧移位。"},{"q":"患者，女，20岁，反复性尿频、尿急、偶有终末性血尿半年，首先考虑为","o":["急性肾盂肾炎","肾结核","膀胱炎","滴虫性阴道炎","急性肾小球肾炎"],"a":2,"e":"尿频、尿急伴终末血尿而全身中毒症状缺如，提示炎症局限于膀胱黏膜。膀胱刺激征存在但不剧烈、无腰痛及寒战高热是膀胱炎的特点；出现双侧腰痛伴高热则提示肾盂肾炎。"},{"q":"患者，男，20岁，高热2天，X线胸片发现右上肺大片状实变影。该患最不可能出现的是","o":["铁锈色痰","咳嗽","胸痛","呼吸急促","桶状胸"],"a":4,"e":"桶状胸是胸廓前后径增大、接近或超过左右径所致，见于慢性阻塞性肺疾病等气道疾病。大叶性肺炎实变期表现为语颤增强、叩诊浊音、管状呼吸音及铁锈色痰，不会出现桶状胸。"},{"q":"患者，男，40岁。行胃大部切除术后第4天时，出现左侧腮腺肿大；检查口腔时，在腮腺导管口处加压，有脓性分泌物。最可能的诊断是","o":["急性流行性腮腺炎","腮腺导管结石","急性化脓性腮腺炎","腮腺肿瘤","Mikulicz综合征"],"a":2,"e":"胃大部切除术后抵抗力低下，腮腺导管口加压流出脓性分泌物是急性化脓性腮腺炎的特征。流行性腮腺炎为病毒性、多为双侧且无脓性分泌物；导管结石在进食时肿痛加重。"},{"q":"患者，男，25岁。胸闷、气短12天，伴乏力、低热、盗汗，左侧腋后线第7肋间以下语颤减低，叩浊，呼吸音减低，腹部正常。拟考虑为","o":["胸膜间皮细胞瘤","系统性红斑狼疮","充血性心力衰竭","结核性胸膜炎","肝硬化"],"a":3,"e":"青壮年出现低热、盗汗，伴一侧腋后线以下语颤减弱、叩诊浊音、呼吸音减低，符合结核性渗出性胸膜炎。积液使脏层与壁层胸膜分开、肺组织受压，故语颤与呼吸音均减弱。"},{"q":"36岁患者，主诉呕血1天入院，系统回顾不应记录哪部分内容","o":["咳嗽、咳痰","胸闷、气短","头痛、头晕","腹痛、腹泻","尿频、尿急"],"a":3,"e":"系统回顾记录与现病无关的各系统症状，其功能是补充现病史的遗漏。呕血属消化系统表现，腹痛、腹泻须写入现病史，不能再作为系统回顾内容记录。"},{"q":"患者，男，60岁。左侧股骨颈骨折，卧床2个月后左下肢肿痛，逐渐加重。超声检查发现左下肢股静脉血栓形成。以下最不可能出现的检查结果是","o":["D-二聚体增高","FDP增加","APTT正常","血浆组织型纤溶酶原激活剂测定减低","血浆纤溶酶原活性减低"],"a":4,"e":"血栓形成时纤溶活性受抑，血浆纤溶酶原活性应增高而非减低。D-二聚体与FDP升高反映继发性纤溶，抗凝与纤溶平衡存在时尚可APTT正常，故纤溶酶原活性减低最不可能出现。"},{"q":"患者，男，36岁，发热、咳嗽3天，现病史还应了解的内容不包括","o":["有无药物过敏","有无咳痰","有无胸痛","有无咯血","发热的程度"],"a":0,"e":"现病史须围绕发热、咳嗽这一主诉展开，问清咳痰、胸痛、咯血及发热程度等伴随症状与演变过程。药物过敏属既往史或过敏史内容，不列入现病史。"},{"q":"患者，男，15岁。学校跑步时突然晕倒，1年前曾有类似发作。体检于心尖部可闻及舒张期杂音，超声心动图显示舒张期在二尖瓣前叶曲线下方有云雾状回声。该患者最可能的诊断是","o":["二尖瓣狭窄","二尖瓣关闭不全","左房黏液瘤","二尖瓣脱垂","主动脉瓣关闭不全"],"a":2,"e":"左房黏液瘤舒张期随血流脱入二尖瓣口，阻塞瓣口并引起脑供血骤降而晕厥，超声见二尖瓣前叶下方云雾状回声。肿瘤扑落音及杂音随体位改变是其特点。"},{"q":"患者，男，65岁。既往有慢性阻塞性肺疾病病史。3天前，受凉后出现发热伴意识模糊、定向力丧失、言语杂乱及幻听、幻视。该意识障碍属于","o":["昏睡","嗜睡","谵妄","轻度昏迷","意识模糊"],"a":2,"e":"谵妄是以兴奋性增高为主的高级神经中枢急性活动失调，表现为意识模糊、定向力丧失、幻觉与言语杂乱。急性感染的发热期出现此类精神症状即属谵妄，而非嗜睡或昏睡。"},{"q":"突发剧烈头痛患者独立行走入院，头颅CT提示蛛网膜下腔出血。查体可以发现以下哪种神经体征","o":["颈强直","Babinski征","Oppenheim征","Hoffmann征","Gordon征"],"a":0,"e":"蛛网膜下腔出血后血液刺激脑膜与脊神经根，产生脑膜刺激征，颈强直最常见。Babinski、Oppenheim、Hoffmann、Gordon征均为锥体束受损的病理反射，与脑膜受激惹无关。"},{"q":"患者，女，76岁，反复胸痛10余年，加重1个月入院。临床诊断：冠状动脉粥样硬化性心脏病，PCI术后；高血压；陈旧脑梗。入院查体：血压180/100mmHg，心率62次/min，呼吸18次/min。入院心电图检查结果如下，正确诊断为","o":["窦性心律，心电图正常","窦性心律，右束支传导阻滞","窦性心律，急性心肌梗死","窦性心律，陈旧性心肌梗死，束支阻滞","窦性心律，房室传导阻滞"],"a":3,"e":"官方题库缺失图片"},{"q":"患者，男，40岁。畏寒、发热6天，肝区疼痛1天。腹部检查：肝右肋下2cm，质软，触痛，边缘整齐，肝右侧肋间隙局限性压痛，并有叩击痛。该患者最有可能的诊断是","o":["肝癌","肝脓肿","肝炎","多囊肝","肝棘球蚴病"],"a":1,"e":"畏寒高热、肝区疼痛伴肝大触痛及右肋间隙局限性压痛与叩击痛，是肝脓肿的典型表现。肝癌质地坚硬、表面呈不规则结节状；肝炎以弥漫性轻度压痛为主。"},{"q":"患者，男，65岁，肝硬化8年。近来出现低热，右上腹疼痛，伴明显消瘦。查体：面色晦暗，颈部及前胸可见蜘蛛痣，腹膨隆，肝于右肋下3cm，触痛（＋），移动性浊音（＋）。为明确诊断，该患首选的生化检查为","o":["AFP","T/A","ALT","TIBL（胆红素测定）","血清蛋白电泳"],"a":0,"e":"肝硬化患者出现低热、右上腹痛、明显消瘦及肝大触痛，须警惕原发性肝癌，血清AFP是首选的筛查与辅助诊断标志物。AFP≥400ng/ml持续1个月高度提示肝癌。"},{"q":"患者，男，30岁，突发寒战、高热、呼吸频速，右上肺触觉语颤增强，叩诊浊音，闻及管状呼吸音。最可能的诊断是","o":["胸腔积液","气胸","肺不张","肺水肿","大叶性肺炎"],"a":4,"e":"大叶性肺炎实变期肺泡充满炎性渗出物，肺组织致密使语颤增强、叩诊浊音并闻及管状呼吸音，伴寒战高热。胸腔积液与气胸语颤减弱，肺不张多伴气管向患侧移位。"},{"q":"患者，男，16岁。3天前无明显诱因出现发热，最高体温40℃，伴剧烈头痛、呕吐。查体：颈项强直，皮肤散在少量瘀点。该患者可能的面容是","o":["急性病容","苦笑面容","面具面容","满月面容","黏液水肿面容"],"a":0,"e":"高热、头痛呕吐伴颈强直及皮肤瘀点是流行性脑脊髓膜炎的表现，属急性感染性疾病，故呈急性病容：面色潮红、兴奋不安、鼻翼扇动、表情痛苦。苦笑面容见于破伤风。"},{"q":"患者，女，50岁。肝素治疗中，实验室检查示TT延长。若想排除是不是肝素导致的TT延长，可以向标本中加入哪个物质再测定TT","o":["甲苯胺蓝","甲苯","蛋白物质","凝血酶","钙离子"],"a":0,"e":"甲苯胺蓝能中和肝素及类肝素物质，延长的TT加入后缩短5秒以上即提示延长由肝素所致。该试验为凝血酶时间纠正试验，用于鉴别肝素或类肝素物质与FDP增多。"},{"q":"患者，女，45岁，因“心累、气紧，呼吸困难3天”入院。查体：胸骨左缘第3、4肋间可闻及舒张期叹气样杂音，心尖区可闻及舒张期隆隆样杂音。心尖部可触及舒张期震颤，胸片示左房、左室增大。最可能的诊断是","o":["风湿性心脏病，二尖瓣狭窄伴关闭不全","风湿性心脏病，二尖瓣狭窄伴主动脉瓣关闭不全","风湿性心脏病，主动脉瓣狭窄伴关闭不全","高血压心脏病，心功能不全","先天性心脏病，室间隔缺损"],"a":1,"e":"胸骨左缘第3、4肋间舒张期叹气样杂音提示主动脉瓣关闭不全，心尖区舒张期隆隆样杂音伴震颤提示二尖瓣狭窄。左房与左室增大同联合瓣膜病变相符，故二者并存。"},{"q":"患者，男，28岁。自幼身体常易出现瘀斑，其姐姐也有相同的症状。完善相关检查，诊断为异常纤维蛋白原血症。下列哪项实验室检查肯定是存在的","o":["TT延长","TT缩短","APTT延长","AT延长","APTT缩短"],"a":0,"e":"异常纤维蛋白原血症时纤维蛋白原分子结构异常，凝血酶使其转变为纤维蛋白的过程受阻，凝血酶时间因而延长。TT对纤维蛋白原质与量的异常最敏感，APTT变化不恒定。"},{"q":"患者老年女性，因“牙龈出血、下肢皮肤瘀点1周”就诊。查血常规示血小板减少，凝血检查正常。请问该患者血小板计数水平最有可能是","o":["＜100×109/L","＜80×109/L","＜70×109/L","＜50×109/L","＜30×109/L"],"a":4,"e":"血小板减少伴皮肤黏膜自发性出血而凝血检查正常，说明血小板数已降至自发出血阈值以下，即低于30×10⁹/L。血小板在50×10⁹/L以上时多无明显自发出血。"},{"q":"患者，男，23岁。乏力、食欲缺乏1周，尿黄3天。查体：肝大，肋下3cm，触痛（＋），脾未扪及。TB 110μmol/L，CB 50μmol/L，抗HAV-IgM（＋）。最不可能出现异常的是","o":["尿胆原","AST","凝血酶原时间","B超肝内胆管扩张","粪胆原"],"a":3,"e":"抗HAV-IgM阳性可确诊急性甲型肝炎，肝细胞性黄疸时尿胆原、粪胆原、转氨酶及凝血酶原时间均可异常。肝内胆汁淤积不引起肝内胆管扩张，胆管扩张仅见于肝外胆道梗阻。"},{"q":"患者，男，出现右膝关节血肿。实验室检测结果：PT 14、6s，APTT 150s，FIB 2、9g/L；加正常血浆纠正后测定PT为14.0s，APTT为46、0s。FⅧ:C为110%，FⅨ:C为5%。该患者初步诊断为","o":["血友病A","血友病B","遗传性因子Ⅺ缺乏症","血管性血友病","因子Ⅷ的抑制物存在"],"a":1,"e":"FⅨ:C降至5%而FⅧ:C正常，APTT延长且能被正常血浆纠正，诊断为血友病B。血友病A为FⅧ:C减低；若体内存在凝血因子抑制物，混合血浆不能纠正延长的APTT。"},{"q":"患者，女，37岁。突发心悸10min。心电图示心率164次/min，P波与QRS波无固定关系，QRS波时限＞0.12s，可见室性融合波。最可能的诊断是","o":["心房扑动","房性心动过速","室性心动过速","交界区心动过速","窦性心动过速"],"a":2,"e":"宽QRS波心动过速伴房室分离、P波与QRS波无固定关系及室性融合波，是室性心动过速的诊断依据。房室分离与融合波反映心室异位起搏，可与室上速伴差异性传导鉴别。"},{"q":"患者，男，62岁，慢性咳嗽咳痰十余年，劳力性心悸气短1年。查体发现心界向左扩大，P2增强，可及剑突下搏动。则该患者心电图特征最可能的是","o":["Ⅱ、Ⅲ导联P波电压0、1mV","电轴左偏－30°，逆钟向转位","RaVL＋SV3＞2.8mV","V1导联呈rS型，r波电压1.0mV","aVR导联呈Rs型，RaVR电压0.5mV"],"a":4,"e":"慢性咳痰史伴P2亢进、剑突下搏动提示肺源性心脏病及右心室肥大。心电图见V1导联R/S≥1、电轴右偏≥+90°、aVR导联以R波为主呈Rs型且RaVR达0.5mV。"},{"q":"患者，男，35岁，发作性心悸5年，突发突止，发作时心电图表现如下，最可能的诊断为","o":["正常心电图","窦性心动过速","房性心动过速","室上性心动过速","室性心动过速"],"a":3,"e":"官方题库缺失图片"},{"q":"患者，男，62岁，身高170cm，体重110kg。头晕3个月。血脂检查示胆固醇5.3mmol/L，三酰甘油10.3mmol/L。要想明确头晕原因，最需要的检查是","o":["腹部B超","颅脑CT","颅脑MRA","脑电图","颈动脉彩超"],"a":4,"e":"中年肥胖、三酰甘油显著升高者出现头晕，须除外颈动脉粥样硬化性狭窄所致脑供血不足，颈动脉彩超能直观显示斑块性质与管腔狭窄程度，为首选筛查手段。"},{"q":"一大叶肺炎患者，胸痛明显。胸片示近胸膜处，均匀一致片状影，在听诊时可能出现下列体征。但应除外","o":["支气管语音","胸语音","耳语音","硬币叩击征","胸膜摩擦音"],"a":3,"e":"大叶肺炎病灶累及胸膜时可闻及胸膜摩擦音，实变区语音共振增强而出现支气管语音、胸语音及耳语音。硬币叩击征是气胸的体征，与肺实变无关。"},{"q":"患者，女，24岁。尿频、尿急、尿痛，血尿伴发热1天，无呕吐，腰痛。尿常规：蛋白（＋），白细胞满视野，红细胞30～40个/HPF。最可能的诊断是","o":["急性膀胱炎","急性肾盂肾炎","急性肾小球肾炎","膀胱结核","肾结核"],"a":0,"e":"膀胱刺激征伴肉眼血尿、尿蛋白阳性及大量白细胞，而全身症状轻微，定位在膀胱，为急性膀胱炎。肾盂肾炎多有寒战高热与肾区叩击痛，膀胱结核多为午后低热、盗汗。"},{"q":"患儿，女，5岁。呕吐3天，伴惊厥2次。2个月前确诊为肾病综合征，低盐饮食2个月，无不洁饮食史。查体：血压80/50mmHg，嗜睡，颜面部及双下肢水肿，颈软，双肺呼吸音粗，心脏无异常，腹软，肝脾未触及，病理征未引出。血清电解质：血钠130mmol/L，血钾3.5mmol/L，血氯95mmol/L，钙2、3mmol/L，HCO3- 20mmol/L。尿常规：蛋白（＋＋＋），红细胞（－）。该患儿最可能的诊断是","o":["肾病综合征伴病毒性脑炎","肾病综合征伴急性胃肠炎","肾病综合征伴低钙惊厥","肾病综合征伴低钠血症","肾病综合征伴低钾血症"],"a":3,"e":"肾病综合征长期低盐饮食并呕吐，血钠降至130mmol/L，出现嗜睡与惊厥，为低钠血症致脑细胞水肿所致。血钙2.3mmol/L在正常范围，可排除低钙惊厥。"},{"q":"一患者反复干咳，且有低热、盗汗等症状，经纤维支气管镜检查证实为支气管内膜有一占位性病变。该患在听诊时可出现的体征为","o":["两肺布满干啰音","支气管语音","耳语音","局限性干啰音","局限性湿啰音"],"a":3,"e":"支气管内膜占位使局部支气管腔狭窄，气流通过形成湍流，故闻及局限性干啰音。两肺弥漫干啰音见于支气管哮喘；湿啰音提示肺泡内渗液，与管腔狭窄不符。"},{"q":"患者，女，40岁。腹泻半年，粪便果酱色，有黏液脓血，粪便培养（－），直肠指检未扪及肿块。为明确诊断，首选的辅助检查是","o":["急诊胃镜检查","纤维结肠镜检查","X线胃肠钡餐造影","腹部超声波检查","腹部CT检查"],"a":1,"e":"果酱色黏液脓血便、便培养阴性而直肠指检未扪及肿块，病变位于结肠，须行纤维结肠镜检查并取活检。钡餐对黏膜病变敏感性低，急性期还有诱发穿孔的风险。"},{"q":"四肢肌力正常患者检查Romberg征时发现睁眼时稳，但闭眼后站立不稳，向两侧摇晃不稳。考虑存在以下哪一方面的问题","o":["深感觉障碍","小脑半球病变","小脑蚓部病变","锥体束病变","锥体外系病变"],"a":0,"e":"闭目难立征睁眼时稳、闭眼后不稳，为感觉性共济失调，提示深感觉传导受阻。深感觉由脊髓后索上传，小脑病变则睁闭眼均不稳并伴肢体共济失调。"},{"q":"患者，女，46岁。反复出现劳力性心累气促20余年，近10年加重。就医曾经诊断“风湿性心脏病、二尖瓣狭窄”。1周前出现咳嗽，咳白色稀薄痰液，不能平卧。心脏听诊心率112次/min，律齐，心尖区可闻舒张期杂音。肺部听诊可闻湿性啰音。诊断首要考虑“风湿性心脏病、二尖瓣狭窄”合并","o":["急性支气管炎","慢性支气管炎","肺结核","肺水肿","肺脓肿"],"a":3,"e":"二尖瓣狭窄基础上出现咳嗽、咳白色稀薄痰且不能平卧，双肺闻及湿啰音，提示左心衰竭致急性肺水肿。肺淤血使液体渗入肺泡，故端坐呼吸与湿啰音为其特征。"},{"q":"患者，男，52岁，食管癌术后7天。今起嘱患者正常饮食后，胸部引流袋引乳糜状液体800ml。以下能鉴别乳糜性和假性乳糜性胸腔积液的项目为","o":["细胞总数","胆固醇含量","三酰甘油含量","淀粉酶含量","白蛋白含量"],"a":2,"e":"乳糜胸因胸导管破裂、淋巴液漏入胸腔，积液中三酰甘油显著升高，是鉴别乳糜性与假性乳糜性积液的核心指标。假性乳糜积液以胆固醇增高及胆固醇结晶为主。"},{"q":"一长跑运动员，30岁。测血压为140/70mmHg，进而诊断为风湿性心脏病，主动脉瓣关闭不全。下列体征对其诊断最有意义的是","o":["双下肢结节性红斑","股动脉枪击音","Austin-Flint杂音","Graham-Steell杂音","胸骨左缘第3肋间舒张期叹气样杂音"],"a":4,"e":"主动脉瓣关闭不全的特征性体征是主动脉瓣第二听诊区即胸骨左缘第3肋间舒张早期递减型叹气样杂音，向心尖传导。枪击音与毛细血管搏动征属周围血管征，特异性较低。"},{"q":"患者，男，65岁，既往有高血压、2型糖尿病史，因胸痛4小时来诊，行心电图检查如图，请问下一步最关键检查是","o":["急诊冠脉造影","冠脉CT重建","胸部增强CT","超声心动图","平板运动试验"],"a":0,"e":"官方题库缺失图片"},{"q":"患者，男，42岁，因发绀1小时入院。查体：T 36℃，P 105次/min，R 24次/min，BP 80/50mmHg，呼吸急促，不规则，伴呕吐及阵发性四肢抽搐，无二便失禁。据家人描述其独自进食大量的过夜变质蔬菜。患者出现发绀的原因最可能为","o":["血液中硫化血红蛋白增多","血液中高铁血红蛋白增多","淤血性周围性发绀","缺血性周围性发绀","血液中血红蛋白减少"],"a":1,"e":"大量进食含亚硝酸盐的变质蔬菜，血红蛋白二价铁被氧化为三价铁，形成高铁血红蛋白而失去携氧能力，故发绀，称肠源性青紫。静脉注射亚甲蓝或大剂量维生素C可使发绀消退。"},{"q":"患者，女，26岁。半月前开始性情急躁，失眠，怕热，出汗和心慌，血清甲状腺素增高，TRAb阳性。该患者体格检查时，最典型的体征是","o":["眼球明显突出且双侧不对称","脉搏不齐","心前区可闻及Ⅲ级以上收缩期杂音","甲状腺弥漫性肿大","心脏明显扩大"],"a":3,"e":"Graves病由TRAb刺激甲状腺，滤泡上皮增生，最典型体征是甲状腺弥漫性肿大、质软并可闻及血管杂音。突眼多为双侧对称，脉搏不齐提示合并房颤而非本病必有的体征。"},{"q":"某老年男性，胸部体检示胸廓前后径明显增宽，肋间隙饱满，腹上角增大。此胸廓形态为","o":["漏斗胸","扁平胸","桶状胸","鸡胸","正常胸廓"],"a":2,"e":"胸廓前后径增宽、肋间隙饱满、腹上角增大即桶状胸，见于慢性阻塞性肺疾病及老年矮胖体型者。扁平胸前后径不足左右径一半，见于瘦长体型及肺结核等消耗性疾病。"},{"q":"患者，男，68岁。进行性呼吸困难2年，双下肺可闻及吸气末爆破音，可见杵状指。HRCT示双下肺网格改变，诊断为特发性肺纤维化。该患者出现呼吸困难的主要机制是","o":["肺泡通气不足","通气/血流比失调","肺内分流","小气道狭窄","弥散功能障碍"],"a":4,"e":"肺纤维化使肺泡-毛细血管膜增厚、弥散距离增大，弥散量下降导致低氧血症，是呼吸困难的主要机制。HRCT网格影、吸气末爆破音与杵状指均支持间质性肺病。"},{"q":"一患者，20年前患乙型肝炎，3小时前突然呕吐鲜红色血液约1000ml，心悸头晕，血压下降。查体：可见蜘蛛痣，脾大、肋下2cm。最可能的诊断是","o":["急性胃黏膜病变","胃溃疡","胆管癌","食管-胃底静脉曲张破裂","Mallory-Weiss综合征"],"a":3,"e":"乙型肝炎后肝硬化门静脉高压形成食管胃底静脉曲张，破裂时呕血量大、来势凶猛并迅速休克。蜘蛛痣与脾大提示肝硬化；消化性溃疡出血多有周期性、节律性上腹痛。"},{"q":"患者，女，51岁。近几个月来反复发生鼻出血及刷牙后牙龈出血，前往医院检查发现出血时间（BT）延长。以下均易导致BT延长，除了","o":["血小板功能正常，计数增多","血小板功能异常","某些凝血因子缺乏","血管壁缺陷","口服氯吡格雷"],"a":0,"e":"出血时间反映血管壁与血小板的一期止血功能，血小板减少、功能异常、血管壁缺陷及氯吡格雷抑制血小板聚集均使其延长。血小板计数增多而功能正常时出血时间不延长。"},{"q":"患者，女，26岁。胸部隐痛15天，伴低热，胸闷，气促。查体：颈静脉怒张，心界向两侧明显扩大，坐位时呈三角形，仰卧位心底部浊音区增宽。此患者最可能的诊断是","o":["急性心肌炎","缩窄性心包炎","扩张型心肌病","缺血性心肌病","急性心包炎伴心包积液"],"a":4,"e":"颈静脉怒张、心界向两侧扩大且坐位呈烧瓶样、卧位心底部浊音界增宽，是心包积液的典型表现。心浊音界随体位改变为积液特有，缩窄性心包炎心界多不增大。"},{"q":"患者，女，68岁。1年前于坐位早餐时无明显诱因突感心悸，随之意识丧失跌倒，数分钟后意识恢复，无大汗、肢体抽搐、口吐白沫和大小便失禁。1年来反复发作上述症状3次，发作与体位和运动无关。查体：BP 130/70mmHg，心率48次/min。心电图示二度Ⅱ型房室传导阻滞。该患者意识丧失最可能的原因是","o":["低血糖","迷走神经张力增高","癫痫发作","体位性低血压","心律失常"],"a":4,"e":"心率48次/分伴二度Ⅱ型房室传导阻滞，心室率骤降致脑供血不足而晕厥，属心律失常性晕厥。发作与体位和运动无关，无抽搐及二便失禁，不支持体位性低血压与癫痫。"},{"q":"患者，男，60岁，近半年来尿频伴进行性排尿困难，排尿费力，不伴明显尿痛。下列哪种疾病可能性较大","o":["膀胱结石","肾结石","膀胱结核","输尿管末端结石","前列腺增生症"],"a":4,"e":"老年男性尿频伴进行性排尿困难、尿线细而尿痛不明显，是前列腺增生压迫后尿道的表现。膀胱结石多有排尿突然中断；膀胱结核伴无痛性血尿与午后低热。"},{"q":"患者，女，65岁，因冠心病平素服阿司匹林，近1周来持续柏油样便，头昏、心悸。查体：巩膜无黄染，心率100次/min，律齐，双肺呼吸音清，腹软，无压痛，肝脾未触及。最可能的诊断为","o":["胃癌","消化性溃疡","急性胃黏膜病变","食管静脉曲张破裂","慢性胃炎"],"a":2,"e":"长期服用阿司匹林抑制前列腺素合成、削弱胃黏膜屏障，引起急性胃黏膜病变而致柏油样便。该患者腹软无压痛，缺乏消化性溃疡周期性上腹痛的特点。"},{"q":"患者，女，26岁。10天来全身皮肤出血点伴牙龈出血来就诊。血常规：PLT 35×109/L，临床诊断为慢性免疫性血小板减少症（ITP）。下列支持ITP诊断的实验室检查是","o":["凝血时间延长","血块收缩减低","抗核抗体阳性","骨髓巨核细胞增多，产板型增多","骨髓巨核细胞增多，原始、幼稚巨核细胞增多"],"a":1,"e":"ITP时血小板显著减少，血小板收缩蛋白不足使血块回缩不良，故血块收缩减低支持诊断。骨髓巨核细胞增多但产板型减少；抗核抗体阳性提示结缔组织病而非ITP。"},{"q":"患者，男，50岁，有乙肝病史30年，饮酒史20年。近1个月来消瘦，并出现上腹部疼痛等症状。查体：巩膜黄染，上腹部触到质硬包块，表面可触及大小不等结节，有压痛。最可能的诊断是","o":["原发性肝癌","晚期肝硬化","慢性肝炎","转移性肝癌","转移性胃癌"],"a":0,"e":"乙型肝炎加长期饮酒史，出现消瘦、上腹质硬包块且表面触及大小不等结节，是原发性肝癌的典型体征。肝硬化肝缩小、质硬而表面为细小结节；转移性肝癌多有原发灶表现。"},{"q":"患者，女，32岁，进行性膀胱刺激征，经抗生素治疗不见好转，伴右侧腰部胀痛及午后潮热。最可能的诊断是","o":["急性肾盂肾炎","急性膀胱炎","肾结核","急性肾盂肾炎并乳头坏死","急性肾盂肾炎并肾周脓肿"],"a":2,"e":"膀胱刺激征进行性加重且抗生素治疗无效，伴一侧腰部胀痛与午后潮热盗汗，是肾结核的表现。结核菌随尿下行感染膀胱，故尿路刺激症状常先于明显的肾脏症状出现。"},{"q":"患者，男，20岁。胸痛7天，伴低热、咳嗽、气促。查体：心界明显扩大，未见心尖冲动，心音遥远，颈静脉怒张。该患者最可能的诊断是","o":["肺炎伴胸腔积液","慢性缩窄性心包炎伴右室功能不全","急性心包炎伴心包积液","急性病毒性心肌炎伴右室功能不全","急性心肌梗死伴右室功能不全"],"a":2,"e":"低热、咳嗽伴心界扩大、心尖搏动不能触及、心音遥远及颈静脉怒张，是急性心包炎伴心包积液的典型表现。积液使心脏与前胸壁距离增大，故心尖搏动消失。"},{"q":"25岁男性，低热1个月，X线可见右肺尖继发性肺结核。该患右肺上界叩诊的宽度，可能为","o":["3cm","5cm","7cm","9cm","11cm"],"a":0,"e":"肺尖叩诊宽度正常为4～6cm，右肺尖结核形成纤维化使肺组织回缩，肺上界下移、宽度变窄，故仅3cm。肺尖部病灶还使局部叩诊音变浊。"},{"q":"一患者入院查体发现存在明显皮肤定位觉、两点辨别觉、实体觉障碍。考虑患者损伤","o":["神经干","脊髓后索","脊髓前角","脊髓后角","皮质"],"a":4,"e":"皮肤定位觉、两点辨别觉与实体觉属复合感觉，是大脑皮质对多种感觉信息综合分析的结果，故障碍提示皮质病变。脊髓后索损害表现为深感觉障碍而复合感觉相对保留。"},{"q":"中年男性，突发呕血约400ml。追问病史，4年来常有黑便，伴上腹隐痛，反酸。此次呕血后，腹痛有缓解。查体：急性病容，贫血貌，P 120次/min，BP 90/45mmHg，上腹压痛（＋），肠鸣音活跃。诊断首先考虑","o":["急性胃黏膜病变","肝硬化食管-胃底静脉曲张破裂出血","胃癌侵蚀血管","Dieulafoy病","消化性溃疡合并出血"],"a":4,"e":"周期性、节律性上腹痛伴反酸，出血后腹痛缓解，是消化性溃疡出血的规律。出血后局部充血减轻、血液中和胃酸，故疼痛减轻；食管胃底静脉曲张破裂多有肝病史。"},{"q":"患者，男，54岁。晕厥10min。查体：昏迷状态，双侧瞳孔散大，对光反射迟钝。该患者最可能的诊断是","o":["颠茄类中毒","吗啡类中毒","毒蕈类中毒","有机磷农药中毒","巴比妥类中毒"],"a":0,"e":"昏迷伴双侧瞳孔散大、对光反射迟钝见于颠茄类中毒。阿托品阻断M受体使瞳孔扩大、调节麻痹；吗啡、巴比妥类及有机磷中毒则表现为瞳孔缩小。"},{"q":"患者，女，36岁，有乙型病毒性肝炎病史。主诉食欲缺乏、乏力3周。血清学检查：抗-HAVIgG（＋），HBsAg（＋）和抗-HBcIgM（＋）。可诊断为","o":["急性甲型肝炎","急性乙型肝炎","乙型肝炎合并甲型肝炎","慢性乙型肝炎急性发作","急性甲型肝炎合并急性乙型肝炎"],"a":3,"e":"抗HAV-IgG阳性仅提示既往感染甲肝，不表示现症感染。HBsAg阳性伴抗-HBc IgM阳性且有乙型肝炎病史，说明慢性HBV感染处于活动期，故为慢性乙型肝炎急性发作。"},{"q":"患者，男，21岁，昨夜会餐，5小时后开始出现恶心、呕吐胃内容物，伴腹痛、腹泻。查体：体温37℃，心肺听诊正常，腹软、无压痛。最可能的诊断是","o":["Meniere病","急性胃肠炎","急性胰腺炎","幽门梗阻","肠梗阻"],"a":1,"e":"进食后数小时出现恶心呕吐伴腹痛腹泻，而腹软无压痛、体温正常，是急性胃肠炎的表现。被细菌或其毒素污染的食物刺激胃肠黏膜，故以吐泻为主而无腹膜刺激征。"},{"q":"患者，男，42岁，晕厥2次，既往体健。查体：二尖瓣区3级吹风样杂音。心电图示RV5 4.2mV，胸前导联T波深倒。该患者最可能的诊断是","o":["风湿性心脏病","肥厚型心肌病","瓣膜性心脏病","冠状动脉粥样硬化性心脏病","高血压心脏病"],"a":1,"e":"青年晕厥伴二尖瓣区收缩期杂音，心电图RV5电压达4.2mV并有胸前导联T波深倒，是肥厚型心肌病的表现。心肌肥厚使左室电压增高，心尖部肥厚者T波倒置尤深。"},{"q":"风湿性心脏病心力衰竭患者用洋地黄和利尿剂治疗，出现食欲缺乏，头痛，心电图为室性期前收缩二联律。应首先考虑","o":["洋地黄剂量不足","低钾","洋地黄中毒","风湿活动","心力衰竭加重"],"a":2,"e":"洋地黄治疗中出现食欲缺乏、头痛及室性期前收缩二联律，是洋地黄中毒的表现。中毒时心肌兴奋性增高，频发室性期前收缩最典型；利尿剂所致低钾可加重中毒。"},{"q":"患者，女，8岁。发热4天，打喷嚏、流涕、流泪、眼结膜充血、面部出米粒样丘疹1天而入院。口腔检查：扁桃体Ⅰ度肿大，口腔黏膜充血，颊黏膜处见帽针头大小白色斑点。考虑下列诊断最可能性的是","o":["风疹","鹅口疮","麻疹","药物中毒","化脓性扁桃体炎"],"a":2,"e":"发热及卡他症状、结膜充血后出疹，颊黏膜第二磨牙处见帽针头大小白色斑点即麻疹黏膜斑，为麻疹早期特征。风疹伴耳后淋巴结肿大而无黏膜斑。"},{"q":"患者，男，26岁。咳嗽、高热3天，1周前有淋浴受凉史。自述咳痰为铁锈色，可能是哪种细菌感染","o":["肺炎链球菌","乙型溶血性链球菌","肺炎克雷伯菌","铜绿假单胞菌","金黄色葡萄球菌"],"a":0,"e":"铁锈色痰是肺炎链球菌肺炎的特征，因肺泡内红细胞被破坏、血红蛋白分解为含铁血黄素所致。肺炎克雷伯菌为砖红色胶冻样痰，金黄色葡萄球菌多为脓血痰。"},{"q":"患者，男，65岁。心电图表现为：RV1＋SV5＝1、15mV，V1呈Rs型，且R/S＞1，平均电轴＋110°，应考虑为","o":["左房肥大","右房肥大","左室肥大","右室肥大","双房肥大"],"a":3,"e":"V1导联R/S>1、RV1+SV5为1.15mV、平均电轴右偏达+110°，均符合右心室肥厚的电压与电轴标准。左心室肥厚表现为RV5增高伴电轴左偏。"},{"q":"患者，女，35岁，咳嗽、咳痰、低热、盗汗1个月，查体发现大量胸腔积液，痰涂片：抗酸杆菌（＋）。符合该患者胸腔积液特点的是","o":["比重低于1、018","黏蛋白定性阳性","蛋白定量＜25g/L","细胞计数＜100×106/L","LDH＜200IU"],"a":1,"e":"结核性胸膜炎为渗出液，浆膜受炎症刺激分泌大量黏蛋白，故Rivalta试验阳性。渗出液蛋白>30g/L、比重>1.018、细胞数增多、LDH>200U/L，均与漏出液相反。"},{"q":"44岁女性，恶心、呕吐2个月就诊，个人史应记录","o":["是否已婚","是否怀孕","有无不良饮食习惯","有无消瘦","有无溃疡病史"],"a":2,"e":"个人史记录出生地、生活习惯与嗜好、职业及毒物接触、烟酒嗜好等，故有无不良饮食习惯属个人史内容。婚育情况另列，有无消瘦属现病史，溃疡病史属既往史。"},{"q":"患者，女，18岁，乏力、食欲缺乏2周。查体：巩膜轻度黄染，心肺及腹部未查及异常。为了鉴别其黄疸类型，应首选的检查项目是","o":["ALP、AST、GGT","STB、TAG","STB、结合胆红素、尿胆原、尿胆红素","ALT、TAG、血清蛋白电泳","AFP、CEA、CA199"],"a":2,"e":"黄疸鉴别依靠总胆红素、结合与非结合胆红素比值及尿胆红素、尿胆原，据此区分溶血性、肝细胞性与梗阻性黄疸。CB/STB<20%提示溶血性，>50%提示梗阻性。"},{"q":"患者，女，42岁，因系统性红斑狼疮合并肾衰竭而入院治疗，采用激素冲击疗法，连续应用糖皮质激素1周。该患者肾衰症状有所缓解，但却出现发热、咳嗽、气喘等症状，听诊肺部有啰音。患者咳痰为砖红色胶冻样，可能是哪种细菌感染","o":["肺炎链球菌","乙型溶血性链球菌","肺炎克雷伯菌","铜绿假单胞菌","金黄色葡萄球菌"],"a":2,"e":"长期大剂量糖皮质激素致免疫功能低下，出现发热咳嗽及砖红色胶冻样痰，是肺炎克雷伯菌肺炎的特征。该菌为革兰阴性杆菌，痰液黏稠呈胶冻状。"},{"q":"一年轻患者，突发胸痛呼吸困难，胸片示气管纵隔左偏，右肺野中外带内无肺纹理。在听诊时，下列对诊断有帮助的是","o":["耳语音","胸语音","羊鸣音","支气管语音","硬币叩击征"],"a":4,"e":"气胸时胸膜腔积气，语音传导减弱，硬币叩击征阳性：叩击患侧前胸硬币、听诊器置于背部可闻及金属样音响，是气胸的典型体征。耳语音与支气管语音增强见于肺实变。"},{"q":"患者进行临床神经系统检查时发现：去枕平卧，屈髋和屈膝后小腿抬高仅100°即出现伸膝受阻及疼痛。这提示该患者存在","o":["Kernig征阳性","Babinski征阳性","Brudzinski阳性","颈强直","Oppenheim征阳性"],"a":0,"e":"屈髋屈膝后伸膝受限并出现疼痛，即Kernig征阳性，为脑膜刺激征之一，见于脑膜炎与蛛网膜下腔出血。Brudzinski征为屈颈时下肢自动屈曲，Babinski征属病理反射。"},{"q":"患儿，女，7岁，突然出现高热、头痛、喷射状呕吐2天。查体示皮肤出血点，颈项强直。脑脊液检查外观浑浊，脑脊液涂片镜检革兰阴性双球菌。根据以上结果可初步诊断","o":["淋病奈瑟菌性脑膜炎","葡萄球菌性脑膜炎","肠球菌性脑膜炎","脑膜炎奈瑟菌性脑膜炎","肺炎链球菌性脑膜炎"],"a":3,"e":"脑脊液浑浊、涂片见革兰阴性双球菌，结合高热头痛、喷射性呕吐、皮肤瘀点与颈强直，诊断为脑膜炎奈瑟菌性脑膜炎。该菌为革兰阴性双球菌，经呼吸道传播。"},{"q":"患者，男，38岁，6年来反复上腹疼，夜间加重伴反酸，2周来呕吐隔日酸臭食物，腹胀加重。下列哪项体征最有诊断意义","o":["肠鸣音亢进","有反跳痛","可见胃蠕动波","Murphy氏征阳性","季肋点有压痛"],"a":2,"e":"反复上腹痛伴反酸，近期呕吐隔日酸臭食物，提示幽门梗阻。梗阻时胃蠕动增强，可见自左肋缘下向右推进的胃蠕动波，并伴胃型与振水音，为幽门梗阻的特征性体征。"},{"q":"患者，女，30岁，发热1周，左腹股沟区可扪及5cm×4cm×3cm大小肿物，有压痛，有波动感。为明确诊断应采用的检查是","o":["切开","诊断性穿刺","腹部B超","CT检查","钡剂灌肠"],"a":1,"e":"腹股沟区压痛性波动性肿物伴发热，多为脓肿，诊断性穿刺抽出脓液即可确诊并送细菌学检查。波动感提示已液化，穿刺兼具诊断与引流作用。"},{"q":"有一溃疡病史男性患者，因1小时前腹痛加重住院。查体：腹部柔韧，全腹部压痛，立位腹平片见膈下游离气体。患者最可能的诊断为","o":["消化道溃疡穿孔","消化道肿瘤","慢性胃炎","急性胃炎","急性胆囊炎"],"a":0,"e":"溃疡病史者突发全腹痛、腹肌板样强直，立位腹平片见膈下游离气体即可确诊消化道溃疡穿孔。气体逸入腹腔后积聚于膈下，是穿孔最直接的影像学证据。"},{"q":"患者，男，73岁。晨起时突发晕厥1天，意识约2～3min后恢复，伴一过性左侧上肢无力，活动不灵，发作时无抽搐及大小便失禁，发作后无后遗症状。患者有长期吸烟史，有动脉粥样硬化病史5年。查体：BP 128/75mmHg，心率58次/分，律齐；生理反射正常引出，病理反射均为阴性。该患者其最可能的病因是","o":["阿-斯综合征","短暂性脑缺血发作","急性脑梗死","体位性低血压","急性脑出血"],"a":1,"e":"老年吸烟者突发短暂意识丧失伴一过性单肢无力，数分钟完全恢复且无后遗症状，是短暂性脑缺血发作。症状于24小时内消失且影像无梗死灶，可与脑梗死相鉴别。"},{"q":"患者，男，38岁。阵发性全腹痛5天，疼痛剧烈时面色苍白、大汗淋漓，缓解时无任何不适，肌内注射阿托品不能使腹痛缓解，但静脉注射葡萄糖酸钙有明显效果。近期常用金属酒具热酒喝。外周血点彩红细胞15%，尿卟啉（±）。最可能的诊断是","o":["卟啉病","急性肠梗阻","铅中毒","神经官能症","急性胰腺炎"],"a":2,"e":"阵发性剧烈腹痛、钙剂可缓解而阿托品无效，伴点彩红细胞增多及金属酒具饮酒史，是铅中毒的表现。铅抑制血红素合成致点彩红细胞出现，驱铅治疗有效。"},{"q":"患者，女，18岁。1个月余前患者无明显诱因咽痛、发热，测得最高体温为39、8℃，伴食欲下降，未予重视；3天后出现颜面部对称性红斑，伴皮温升高，偶有瘙痒，体温正常。查体见鼻梁部皮肤出现红色斑块，病损处高起皮面并向两侧面颊部扩展。发现此鼻部体征应考虑诊断","o":["系统性红斑狼疮","二尖瓣面容","肝脏疾病","酒渣鼻","黑热病"],"a":0,"e":"鼻梁部红斑高起皮面并向两侧面颊扩展呈蝶形，是系统性红斑狼疮的特征性皮损。酒渣鼻以鼻尖、鼻翼潮红及毛细血管扩张为主，无蝶形分布。"},{"q":"患者，女，35岁。因鼻腔干燥、嗅觉减退2个月余就诊。查体：鼻黏膜萎缩，鼻甲缩小，鼻腔宽大。考虑诊断为","o":["急性鼻炎","慢性萎缩性鼻炎","化脓性鼻窦炎","过敏性鼻炎","鼻肿瘤"],"a":1,"e":"鼻黏膜萎缩、鼻甲缩小、鼻腔宽大伴嗅觉减退，是慢性萎缩性鼻炎的表现。黏膜与腺体萎缩使分泌物减少、干痂形成，鼻腔因组织缩小而显得宽大。"},{"q":"患者，女，38岁，右拇指疼痛2个月。查体：右手拇指活动时出现弹响伴疼痛，局部压痛。该患者最可能的诊断是","o":["尺神经损伤","腱鞘囊肿","桡神经损伤","狭窄性腱鞘炎","正中神经损伤"],"a":3,"e":"拇指活动时弹响伴疼痛及局部压痛，是狭窄性腱鞘炎的典型表现。屈指肌腱在增厚的腱鞘内滑动受阻，故出现弹响指；神经损伤以感觉与运动障碍为主。"},{"q":"患者，男，70岁。咳嗽、咳痰20年。查体：双肺可闻及小水泡音，肝肋下3cm，质软，无触痛。考虑肝大是由于哪种疾病所致","o":["肝淤血","肺癌","肝硬化","肝癌","肺气肿"],"a":0,"e":"慢性咳痰史提示肺源性心脏病并右心衰竭，体循环淤血使肝大而无触痛，属肝淤血。肝颈静脉回流征阳性是其特点，肝大小随淤血程度变化，与肝炎的压痛性肝大不同。"},{"q":"患者，女，35岁，尿频、尿急、尿痛伴腰痛、发热、寒战1天，右侧肾区有压痛、叩击痛。其发热原因最可能是","o":["膀胱炎","慢性肾盂肾炎","急性肾盂肾炎","急性肾小球肾炎","慢性肾小球肾炎"],"a":2,"e":"尿频尿急尿痛伴腰痛、寒战高热及肾区叩击痛，是急性肾盂肾炎的表现。细菌经尿道上行累及肾盂肾盏，引起骤升型高热与肾区叩痛；膀胱炎则无全身症状。"},{"q":"患者，男，45岁。消瘦，腹胀，尿少1个月。肝炎病史15年。查体：慢性病容，可见肝掌及前胸蜘蛛痣，腹软，肝不大，脾肋下2cm，移动性浊音阳性。实验室检查：GGT 150U/L，A/G比例倒置。肝炎标志物阳性。最可能的诊断是","o":["肝炎后肝硬化","慢性肝炎","酒精性肝硬化","急性肝炎","肝癌"],"a":0,"e":"肝炎病史多年，出现肝掌、蜘蛛痣、脾大、腹腔积液及A/G倒置，是肝炎后肝硬化的表现。门静脉高压致脾大与腹腔积液，肝功能减退使白蛋白合成减少、A/G倒置。"},{"q":"4岁女童，吃花生米时突然出现惊慌、气促，抱送急诊发现患儿吸气极度困难，出现“三凹征”。最可能诊断为","o":["气管异物","支气管哮喘发作","小儿肺炎","胸腔积液","胸膜炎"],"a":0,"e":"进食花生米时突发吸气性呼吸困难并出现三凹征，提示气管异物阻塞气道。吸气时胸腔负压增大，使胸骨上窝、锁骨上窝及肋间隙凹陷，为本病的典型体征。"},{"q":"患者，男，55岁。高血压3年，予氨氯地平＋美托洛尔＋哌唑嗪控制不佳，入院心电图如下所示，进一步诊治不合理的是","o":["联合利尿剂控制血压","筛查电解质","筛查肾上腺CT","完善卡托普利试验","筛查肾动脉超声"],"a":0,"e":"官方题库缺失图片"},{"q":"患者，男，20岁。1周前着凉后轻咳，低热、右胸刺痛，近日来活动后气短。查体：右下胸部叩诊呈浊音，浊音区上方可闻及支气管肺泡呼吸音，下方呼吸音显著减弱。最可能的诊断是","o":["气胸","肺脓肿","中等量胸腔积液","少量胸腔积液","胸膜增厚"],"a":2,"e":"右下胸叩诊浊音、呼吸音显著减弱，浊音区上方闻及支气管肺泡呼吸音，是中等量胸腔积液的典型体征。积液压迫肺组织形成压迫性肺不张，故积液上方可闻及支气管呼吸音。"},{"q":"患者，男，75岁，晕厥2次，既往有心肌梗死病史。查体：二尖瓣区3级吹风样杂音。心电图示心率130次/min，QRS波130ms。该患者最不可能的诊断是","o":["室性心动过速","心房颤动伴右束支传导阻滞","房性心动过速伴差异性传导","心房颤动伴预激综合征","房室结折返性心动过速伴预激综合征"],"a":4,"e":"该心电图QRS波宽大、心率130次/分，可见于室速、房颤伴束支阻滞或预激伴房颤。预激合并房室结折返性心动过速时QRS波一般窄，故最不可能；既往心梗史亦支持室速。"},{"q":"患者，女，30岁。妊娠3个月，面色发黄、食欲缺乏1个月。查体：轻度贫血貌，巩膜轻度黄染。心肺及肝脾无异常。实验室检查：ALT 270U/L，AST 380U/L。患者不可能出现的实验室检查结果是","o":["结合胆红素中度增高","非结合胆红素轻度增高","总胆红素明显增高","尿胆原多为中度增高","尿胆红素阳性"],"a":1,"e":"肝细胞性黄疸时摄取、结合与排泄均障碍，结合与非结合胆红素同时升高，CB/STB为20%～50%，非结合胆红素升高明显而非轻度；尿胆原中度增高、尿胆红素阳性均符合。"},{"q":"患者，女，20岁。持续头痛1个月。近来工作紧张，生活不规律，失眠，食欲良好。查体：心肺及腹部无异常，四肢神经反射正常。该患者头痛的原因最可能是","o":["病毒性脑炎","紧张性头痛","高血压","脑血管疾病","血管性头痛"],"a":1,"e":"长期紧张、失眠而查体无阳性发现，头痛呈重压感或紧箍感，是紧张性头痛。颅内器质性病变多有喷射性呕吐、视盘水肿及定位体征，本例均缺如。"},{"q":"患者，女，54岁，主诉心前区疼痛，呼吸困难2周。查体：BP 100/80mmHg，P100次/min，心音低钝、遥远。吸气时收缩压降低15mmHg。最可能的诊断","o":["急性心肌梗死","肺气肿伴右心衰竭","大量心包积液","肺栓塞","心肌炎"],"a":2,"e":"心音低钝遥远、血压偏低、心率快，吸气时收缩压下降超过10mmHg即奇脉，是大量心包积液致心脏压塞的表现。心包腔内压力增高限制心室充盈，每搏量因而下降。"},{"q":"一患者步态不稳入院。查体发现患者肌力正常，饮水无呛咳，行走时向右侧倾斜，闭目难立征：睁闭眼都向右侧倒。考虑患者损伤以下哪个部位","o":["右侧大脑皮层","右侧小脑","延髓右侧","右侧基底基底区","脑桥右侧"],"a":1,"e":"闭目难立征睁眼与闭眼均向右侧倾倒，肌力正常且饮水无呛咳，提示右侧小脑病变。小脑性共济失调与视觉无关，睁眼时仍不稳，可与深感觉障碍性共济失调鉴别。"},{"q":"患者，女，36岁。劳力性呼吸困难半个月，既往关节肿痛史。超声提示二尖瓣重度粘连，未见钙化，开放受限。查体：血压110/75mmHg，脉搏85次/min，心率145次/min，心律不齐，心音强弱不等。患者还可有其他视诊体征，如","o":["二尖瓣面容","心前区明显隆起","负性心尖冲动常见","可见胸骨右缘第2肋间异位搏动","毛细血管搏动征"],"a":0,"e":"二尖瓣狭窄使左房压升高、肺淤血，长期缺氧致面颊紫红、口唇轻度发绀，形成二尖瓣面容。心律绝对不齐、心音强弱不等提示合并心房颤动，为左房扩大的常见并发症。"},{"q":"患儿，女，13岁。3个月前其家长无意中发现颈前增粗，患儿诉无任何不适，发病以来饮食正常。既往体健，无肿瘤家族病史。查体：T36.5℃，P82次/min，R22次/min，BP 120/70mmHg，甲状腺呈对称性Ⅱ度肿大，表面光滑，质软，无压痛。该患儿最可能的诊断是","o":["甲状腺功能亢进症","单纯性甲状腺肿","甲状腺癌","慢性淋巴性甲状腺炎","亚临床甲状腺炎"],"a":1,"e":"青春期女性甲状腺对称性Ⅱ度肿大、表面光滑质软无压痛，无甲亢症状且饮食正常，为单纯性甲状腺肿。甲状腺癌质硬且不规则；慢性淋巴细胞性甲状腺炎质地较韧。"},{"q":"患儿，4岁，因肺炎就诊，体检时发现心前区隆起，听诊胸骨左缘第3～4肋间闻及响亮而粗糙的4/6级收缩期杂音伴收缩期震颤。为明确诊断，进一步检查应首选","o":["心电图","心脏正侧位片","心脏彩色多普勒","心内膜心肌活检","心脏核素扫描"],"a":2,"e":"胸骨左缘第3、4肋间响亮粗糙的收缩期杂音伴震颤，提示室间隔缺损。心脏彩色多普勒能显示缺损部位、分流方向与压差，是无创确诊的首选检查。"},{"q":"患者，男，26岁。被卡车撞倒后昏迷，外耳道溢液，起初为血色，之后为无色清水样。考虑损伤部位为","o":["外耳道损伤","中耳损伤","前庭损伤","颅内出血","颅底骨折"],"a":4,"e":"头部外伤后外耳道流出脑脊液，提示颅底骨折累及颞骨岩部并撕裂硬脑膜，脑脊液经中耳、外耳道流出。起初带血后转为无色清水样，是脑脊液漏的典型演变。"},{"q":"患者，男，53岁。腰痛、肋骨痛2个月。经影像学检查发现脊柱、骨盆等部位多发骨质疏松。该患者血清电解质水平最可能出现","o":["血钾4、0mmol/L","血钠130mmol/L","血氯115mmol/L","血钙3.17mmol/L","血磷0.9mmol/L"],"a":3,"e":"脊柱与骨盆多发骨质疏松伴骨痛，提示肿瘤骨转移或甲状旁腺功能亢进使骨吸收增强，血钙升高可达3.17mmol/L。血磷多正常或偏低，血钾血钠通常无显著改变。"},{"q":"患儿，男，7岁。学校体检发现心脏杂音1个月，无自觉症状。查体：心尖区闻及2级柔和收缩早期吹风样杂音，不传导。最可能的诊断是","o":["二尖瓣关闭不全","生理性杂音","室间隔缺损","二尖瓣狭窄","主动脉瓣关闭不全"],"a":1,"e":"儿童心尖区2级柔和吹风样收缩早期杂音、不传导、无震颤且心脏不大，符合生理性杂音的条件。二尖瓣关闭不全为全收缩期杂音并向腋下传导。"},{"q":"患者，男，36岁，因头晕胸痛半月来诊。血压160/35mmHg，胸片提示靴型心。下列体征不可能出现的是","o":["毛细血管搏动征","水冲脉","胸骨右缘2肋间的收缩期震颤","胸骨左缘3/4肋间的舒张早期递减性杂音","枪击音"],"a":2,"e":"血压160/35mmHg、胸片呈靴形心提示主动脉瓣关闭不全，舒张压骤降产生水冲脉、枪击音及毛细血管搏动征。胸骨右缘第2肋间收缩期震颤见于主动脉瓣狭窄，不会出现。"},{"q":"某患者十二指肠球部溃疡病史8年，突发剧烈上腹痛，迅速波及全腹。查体：板状腹，全腹压痛，反跳痛，肌紧张，高度怀疑十二指肠球部溃疡合并穿孔。此时最有诊断价值的检查为","o":["急性胃镜","饮水超声","X线钡餐","立位腹平片","吞线试验"],"a":3,"e":"溃疡病史者突发全腹痛、板状腹，立位腹平片见膈下游离气体即可确诊穿孔。急性期禁做胃镜与钡餐，以免加重腹腔污染；超声对游离气体不敏感。"},{"q":"患者，男，35岁。低热、乏力、盗汗，胸腔积液细胞分类计数时，淋巴细胞数达到65%。最可能的诊断是","o":["细菌性肺炎","结核病","肺梗死","气胸","创伤"],"a":1,"e":"低热、乏力、盗汗伴胸腔积液，淋巴细胞占65%以上，提示结核性胸膜炎，即结核病。结核性渗出液以淋巴细胞为主，细菌性肺炎的积液则以中性粒细胞为主。"},{"q":"患者，女，55岁。高血压20年，不规则服药。某日晨突发头痛，意识不清，30min后送到医院。查体：昏迷，血压190/120mmHg，双眼向右侧凝视，左足外旋位。该患者最可能的病变部位是","o":["右侧脑干","右侧半球表面","右侧半球深部","左侧半球表面","左侧半球深部"],"a":2,"e":"高血压患者突发昏迷，双眼向右侧凝视即凝视病灶侧，左侧肢体瘫痪、左足外旋，定位在右侧大脑半球。基底节区出血常累及内囊，故为右侧半球深部病变。"},{"q":"患者，女，20岁，因进行性心累气紧3个月来诊。查体发现BP 90/70mmHg，心界双侧扩大，随体位改变，心率120次/min，律齐，心音低弱遥远，无病理性杂音。本患者与心肌炎鉴别点主要为","o":["肝大","双侧心界扩大","心动过速，心音低弱","心界随体位改变而变化","移动性浊音"],"a":3,"e":"心界随体位改变是心包积液的独有特征，因液体流动使浊音界随体位移动。心肌炎心界扩大且固定、不随体位变化，故为二者的主要鉴别点。"},{"q":"患者，女，24岁，因脚踝受伤来到急诊，焦虑面容。床旁血气：pH 7.55，HCO3－ 23mEq/L，PaCO2 27mmHg，PaO2 105mmHg，SO2 100%。该患者可能发生了","o":["呼吸性碱中毒失代偿期","代谢性酸中毒部分代偿期","代谢性碱中毒部分代偿期","呼吸性酸中毒与低氧血症代偿期","抽取的是静脉血"],"a":0,"e":"pH 7.55、PaCO2 27mmHg、HCO3- 23mmol/L，为PaCO2原发性下降所致的失代偿性呼吸性碱中毒，焦虑与过度通气是常见诱因。HCO3-尚在正常范围，提示尚未代偿。"},{"q":"医生帮一垂体瘤患者检查视野，发现存在双眼颞侧视野缺损。推测损伤是以下哪一部位","o":["视神经","视网膜","视交叉","视束","枕叶"],"a":2,"e":"双眼颞侧偏盲是视交叉中央部受损的典型表现，因来自双眼鼻侧视网膜的交叉纤维在此受压。垂体瘤向上生长压迫视交叉，故最先出现颞侧视野缺损。"},{"q":"患者，女，25岁。近日反复出现皮肤出血点，以双下肢为著。日前曾有发热咽痛，现已痊愈。以下哪项不参与该患者止血过程","o":["血管壁","血小板","凝血因子","炎症因子","纤溶因子"],"a":3,"e":"止血由血管壁、血小板、凝血因子与纤溶系统共同完成，血管壁与血小板构成一期止血，凝血因子参与二期止血，纤溶系统维持血流通畅。炎症因子不参与止血过程。"},{"q":"患者，男，28岁，以“大量心包积液”收入院，入院后床旁心电图标准设置下波形振幅过小，无法清晰显示，按以下哪项心电图设置参数进行更改会有所帮助","o":["20mm/s、5mm/mV","25mm/s、10mm/mV","25mm/s、20mm/mV","25mm/s、5mm/mV","50mm/s、10mm/mV"],"a":2,"e":"心包积液时心脏电信号被液体衰减，体表心电图呈低电压，将定准电压由10mm/mV调至20mm/mV可使波形振幅加倍，走纸速度仍取标准25mm/s以保证时间测量准确。"},{"q":"患者，男，26岁，发热、咳嗽、咳铁锈色痰。下列确定早期肺实变较敏感的方法是","o":["叩诊","触觉语颤","耳语音","管状呼吸音","管状呼吸音伴语颤增强"],"a":2,"e":"肺实变时肺泡含气消失、组织致密，声波传导增强，耳语音在实变早期即出现音调升高、强度增大，较语颤及管状呼吸音更为敏感。"},{"q":"患者，男，64岁。因头晕黑蒙1年来诊。查体：心率42次/min，心律整齐，心音强弱不等，可及大炮音。该患者考虑","o":["二尖瓣狭窄","三度房室传导阻滞","高血压","主动脉瓣狭窄","频发室性期前收缩"],"a":1,"e":"三度房室传导阻滞时房室分离，心室由缓慢的逸搏心律控制，心率约40次/min且规则；心房与心室几乎同时收缩即产生大炮音，为该病的特征性体征。"},{"q":"患者，男，37岁。发热1周，伴乏力、腹胀、腹泻。查体示热病容，脾肋下3cm。血常规检查白细胞偏低，发病后曾服用退热药及磺胺药，但发热未退，临床怀疑为伤寒。为进一步确诊，首选应做的检查是","o":["尿培养","粪便培养","骨髓培养或血培养","抗O试验","肥达反应"],"a":2,"e":"伤寒第1周血培养阳性率最高，骨髓培养阳性率更高且受已用抗菌药物影响小，故病程早期首选血培养或骨髓培养分离病原体以确诊。"},{"q":"患者，女，38岁。咳嗽、低热3个月，咯血1天就诊。怀疑肺结核，并对其进行病原学诊断。其中痰标本涂片后应选用的方法是","o":["革兰氏染色","墨汁染色","鞭毛染色","奈瑟染色","抗酸染色"],"a":4,"e":"结核分枝杆菌细胞壁富含脂质，一般染色不易着色，痰涂片须用抗酸染色查找抗酸杆菌，是肺结核病原学诊断的常规方法。"},{"q":"患者，女，55岁。高血压20年，不规则服药。某日晨突发头痛，意识不清，30min后送到医院。查体：昏迷，血压190/120mmHg，双眼向右侧凝视，左足外旋位。该患者最可能的诊断是","o":["晕厥","脑出血","脑血栓形成","蛛网膜下脑出血","心肌梗死"],"a":1,"e":"长期高血压患者突发剧烈头痛、昏迷并双眼向病灶侧凝视，为基底节区脑出血的典型表现，血压显著升高是重要诱因。"},{"q":"患者，女，26岁。发作性咳嗽、咳痰、呼吸困难，可自行缓解。关于该患者症状发作时体征的描述正确的是","o":["呈吸气性呼吸困难","胸廓呈呼气位","两肺叩诊呈过清音","语音共振稍增强","Kronig峡消失"],"a":2,"e":"哮喘发作时气道广泛痉挛、肺过度充气，胸廓饱满呈吸气位，叩诊两肺呈过清音，语音共振减弱而非增强。"},{"q":"患者，女，28岁。恶心、尿色变黄6天，体检发现巩膜中度黄染，肝肋下2cm可及，血谷丙转氨酶840U/L，总胆红素85μmol/L。对本例明确诊断最有意义的检查为","o":["腹部超声检查","肝炎病毒标志物检查","全套肝脏生化检查","腹部增强CT检查","肥达外婓试验"],"a":1,"e":"转氨酶显著升高伴黄疸提示肝细胞损伤，明确病因需检测甲、乙、丙、戊等肝炎病毒标志物，病毒血清学是病原诊断的关键。"},{"q":"一患者术后突然出现右侧胸痛，咳嗽，咯少量血痰。胸片示右肺下野可见模糊片影。最可能出现下列哪项体征","o":["右侧出现耳语音","右侧触觉语颤增强","右侧听觉语颤增强","右肺听到湿啰音","右肺听到干啰音"],"a":3,"e":"术后卧床易发生肺栓塞并致肺梗死，梗死区肺泡充血渗出，局部可闻及湿啰音，语音震颤与耳语音一般不增强。"},{"q":"一年轻人因用力后突然感到一侧胸痛，进行性呼吸困难，伴大汗淋漓。查体：一侧胸部语音震颤减弱，呼吸音消失，气管向健侧移位。首先应想到患哪种疾病","o":["支气管哮喘","胸腔积液","大叶肺炎","气胸","肺不张"],"a":3,"e":"突发一侧胸痛伴进行性呼吸困难，病侧语颤减弱、呼吸音消失、气管移向健侧、叩诊呈鼓音，为气胸的典型体征组合。"},{"q":"一女性患者长期存在双下肢接触凉水后疼痛不适感。查体：双下肢轻微触摸后疼痛难耐。以上情况考虑为","o":["痛觉正常","痛觉过敏","痛觉消失","痛觉减退","触觉过敏"],"a":1,"e":"轻微触摸即引起难以忍受的疼痛，属痛觉反应过度，见于周围神经不完全损伤及脊髓后角、丘脑病变，称痛觉过敏。"},{"q":"患者，男，53岁。头痛3小时，呈持续性，程度剧烈。查体：T 36℃，意识模糊，烦躁，脑膜刺激征阳性。该患者最可能的诊断是","o":["蛛网膜下腔出血","脑炎","脑膜脑炎","脑肿瘤","脑梗死"],"a":0,"e":"突发剧烈头痛伴脑膜刺激征阳性及意识模糊，而缺乏局灶定位体征，最符合蛛网膜下腔出血；脑膜刺激征对其与脑膜炎均有提示意义。"},{"q":"患者，男，46岁，劳力性胸痛2个月，突感心悸、胸闷，血压为90/60mmHg，心尖S1强弱不等；心电图示心室率150次/min，P波与QRS波群无固定关系，QRS波增宽为0、14s，可见室性融合波。最可能的诊断为","o":["频发室性期前收缩","心房颤动","心房扑动","阵发性室上性心动过速","阵发性室性心动过速"],"a":4,"e":"QRS波宽大畸形且时限超过0.12秒、P波与QRS波无固定关系、可见室性融合波，心室率150次/min，为阵发性室性心动过速的诊断依据。"},{"q":"患者，女，15岁，自幼偏食不喜肉蛋。查体：浅表淋巴结不大，睑结膜苍白。心尖区2级收缩期杂音，肝脾不大。外周血RBC 4.0×1012/L，Hb 70g/L，RC 0.015，MCV 60fl，MCHC 260g/L，WBC 5.0×109/L，PLT 120×109/L，骨髓细胞外铁（－），铁粒幼细胞0、01。最可能的诊断是","o":["巨幼细胞贫血","缺铁性贫血","再生障碍性贫血","环状铁粒幼细胞贫血","遗传性球形红细胞增多症"],"a":1,"e":"小细胞低色素性贫血伴骨髓细胞外铁阴性、铁粒幼细胞显著减少，是缺铁性贫血的可靠证据，符合偏食少食肉蛋的缺铁病史。"},{"q":"一胸腔积液患者，胸部X线片显示右侧肋膈角变钝，该侧胸部的叩诊音应为","o":["清音","浊音","实音","浊鼓音","空瓮音"],"a":0,"e":"肋膈角变钝提示积液量少，尚未达到改变叩诊音的程度，故叩诊仍为清音；中等量以上积液才出现浊音乃至实音。"},{"q":"患者，男，30岁。反复心悸1个月，1周前有上呼吸道感染。查体：主动脉瓣可闻及舒张期高调递减型叹气样杂音，周围血管征阳性。目前该患者在安静状态下可能明显出现哪项体征","o":["颈动脉搏动","颈静脉搏动","颈静脉充盈","颈静脉塌陷","颈动脉杂音"],"a":0,"e":"主动脉瓣关闭不全时舒张期血液反流使收缩压升高、舒张压降低，脉压增大，出现颈动脉搏动明显、水冲脉及点头运动。"},{"q":"患者，男，55岁，乏力、消瘦、食欲减退5年加重1个月，有大量腹水，既往慢性乙型肝炎病史30余年。化验提示血清白蛋白20g/L。符合该患者腹腔积液特点的是","o":["不自凝","蛋白定量＞30g/L","细胞计数＜500×106/L","乳酸脱氢酶＞200IU","比重高于1、018"],"a":0,"e":"肝硬化门静脉高压所致腹腔积液为漏出液，蛋白含量低、细胞数少，缺乏纤维蛋白原，放置后不自凝。"},{"q":"患者，女，53岁。发作性眩晕3小时。患者于转头后突然出现眩晕，四肢无力，摔倒在地，四肢无法活动，持续约5分钟后恢复正常，无大小便失禁。发作时查体：血压145/91mmHg，神志清，四肢肌力0级，肌张力低。间歇期查体无异常，脑电图正常。该患者最可能的诊断是","o":["癫痫","短暂脑缺血发作","位置性眩晕","高血压脑病","癔症"],"a":1,"e":"发作性神经功能缺损于数分钟内完全恢复、间歇期查体及脑电图均正常，符合短暂性脑缺血发作，属脑源性眩晕的常见原因。"},{"q":"患者，女，48岁。左乳腺肿块1个月。查体：左乳腺内下方触及2cm×2cm大小包块，质硬，无触痛，表面光滑。该患者不可能出现的临床表现是","o":["皮肤橘皮样改变","乳头内陷","乳头有血性分泌物溢出","局部红肿和疼痛","腋窝淋巴结肿大和粘连"],"a":4,"e":"肿块质硬、表面光滑、无触痛，符合乳腺纤维腺瘤等良性病变，不会出现癌淋巴道转移所致腋窝淋巴结肿大并与周围组织粘连。"},{"q":"一男性患者步态不稳、脚踏棉花，医生接诊时考虑患者深感觉存在障碍，需要进行震动觉检查。以下哪个部位不适合进行震动觉检查","o":["胫骨","内、外踝","髂骨上棘","膝盖骨","肚脐周围"],"a":4,"e":"震动觉用128Hz音叉置于骨突起处检查，内踝、外踝、胫骨、膝盖及髂前上棘均可，腹部软组织不能有效传导振动。"},{"q":"患者，男，60岁。四肢关节肿痛20年，以双手小关节为重。查体见双手尺偏畸形，右肘关节屈曲畸形。最可能的疾病是","o":["类风湿关节炎","骨关节炎","软组织炎","退行性关节炎","痛风"],"a":0,"e":"双手小关节对称性肿痛伴晨僵及尺偏、屈曲畸形，是类风湿关节炎的典型表现；骨关节炎多累及远端指间关节，不出现尺偏畸形。"},{"q":"患者，女，36岁。头晕、乏力2年。平时月经过多，素食为主。查体：贫血貌。心肺无异常。实验室检查：Hb 88g/L，MCV 70fl。患者指甲最不可能出现的表现是","o":["指甲中部凹陷","指甲边缘翘起","指甲变厚","表面粗糙有条纹","出现“反甲”"],"a":2,"e":"反甲表现为指甲变薄、中央凹陷、边缘翘起、表面粗糙有条纹，缺铁性贫血不会出现指甲增厚。"},{"q":"患者，男，70岁，皮肤瘀斑2天。有心肌梗死病史，长期服用阿司匹林肠溶片。下列实验室检查不符合的是","o":["血小板P-选择素增高","血小板聚集率降低","出血时间延长","血小板黏附功能降低","APTT延长"],"a":4,"e":"阿司匹林不可逆抑制血小板环氧化酶，使血栓素A2生成减少，血小板聚集率降低、出血时间延长、P-选择素增高，而APTT反映内源凝血因子活性，不受影响。"},{"q":"患者，女，30岁，3天前脚外伤后出现发热，最可能出现","o":["左锁骨上淋巴结肿大","右锁骨上淋巴结肿大","滑车上淋巴结肿大","腋窝淋巴结肿大","腹股沟淋巴结肿大"],"a":4,"e":"足部及下肢的感染沿淋巴管回流至腹股沟淋巴结，引起该组淋巴结反应性肿大伴疼痛，故为腹股沟淋巴结肿大。"},{"q":"患者，男，60岁。近期腹痛明显，排便次数减少，偶有排便成细长条状，体重减轻明显，食欲不佳。考虑患者最可能的疾病是","o":["肠癌","肠炎","肠息肉","溃疡性结肠炎","克罗恩病"],"a":0,"e":"排便习惯改变、粪便变细伴腹痛、消瘦及食欲减退，提示结直肠肿瘤致肠腔狭窄，为肠癌的典型表现。"},{"q":"患者，男，19岁。平素劳力尚可，无明显心悸、气促。体检时发现胸骨左缘第3肋间出现叹气性递减型舒张期杂音，血压120/60mmHg。该患者可出现下列体征，但除外","o":["水冲脉","颈静脉搏动","毛细血管搏动征","枪击音","杜氏双重音"],"a":1,"e":"主动脉瓣关闭不全时脉压增大，可出现水冲脉、毛细血管搏动征、枪击音及杜氏双重音；颈静脉搏动反映右心压力升高，不见于本病。"},{"q":"患者，女，25岁。肝炎系列检查示HBsAg（－），抗-HBs（＋），抗-HBc（－），HBeAg（－），抗-Hbe（－），表明","o":["急性肝炎初期","慢性迁延性肝炎且有传染性","乙肝恢复并产生免疫力","既往乙肝病毒感染，病毒复制","慢性活动性肝炎"],"a":2,"e":"抗-HBs阳性而HBsAg、抗-HBc均阴性，提示乙肝疫苗免疫成功或既往感染已清除，机体已获得保护性免疫力。"},{"q":"患者，女，23岁。自幼身体常易出现瘀斑，1个月前剖宫产术后伤口延迟愈合，辅助检查示TT明显延长且Fg活性下降，APTT、PT正常，考虑诊断为","o":["异常纤维蛋白原血症","血友病A","血友病B","血小板无力症","血小板促凝活性增高"],"a":0,"e":"TT明显延长伴纤维蛋白原活性下降，而PT、APTT正常，提示纤维蛋白原分子结构异常致凝血酶作用障碍，为异常纤维蛋白原血症。"},{"q":"患者，男，32岁。下腹痛伴夜尿2天。查体：前列腺触诊发现前列腺弥漫性肿大，压痛明显。患者最可能的诊断是","o":["正常前列腺","急性前列腺炎","良性前列腺肥大","前列腺癌","前列腺钙化"],"a":1,"e":"前列腺弥漫性肿大伴明显压痛是急性前列腺炎的特征；良性增生表面光滑有韧感而无压痛，前列腺癌质硬、有结节且无压痛。"},{"q":"患者，男，52岁，诊为高血压20年，活动时气短1年。心电图显示如下，心电图的诊断考虑为","o":["急性心肌梗死","低血钾","一度房室传导阻滞","心房增大","左室肥大"],"a":4,"e":"官方题库缺失图片"},{"q":"患者，男，77岁。吸烟50年，常年咳嗽、咳痰，近10年出现活动性呼吸困难、并进行性加重。明确诊断为慢性支气管炎合并肺气肿，该患者胸廓改变最常见的是","o":["脊柱后凸","桶状胸","扁平胸","漏斗胸","鸡胸"],"a":1,"e":"长期慢性咳嗽、咳痰伴进行性呼吸困难，肺过度充气使胸廓前后径增大、接近左右径，形成桶状胸。"},{"q":"某患，突发呕血2000ml，为新鲜血。查体：面色晦暗，颈面部及双上肢可见散在蜘蛛痣，肝掌，腹膨隆，脾大，肋下2cm，移动性浊音阳性。该患者出血原因考虑为","o":["食管静脉曲张破裂出血","脾功能亢进","消化性溃疡","胃癌","Dieulafoy病"],"a":0,"e":"面色晦暗、蜘蛛痣、肝掌、脾大及移动性浊音阳性提示肝硬化门静脉高压，食管胃底静脉曲张破裂是此类患者大量呕血的最常见原因。"},{"q":"患者，女，25岁，既往健康。2小时前打扫室内清洁时突然出现咳嗽、胸闷、呼吸困难。查体：两肺满布干啰音。该例诊断应为","o":["慢性喘息型支气管炎","慢性阻塞性肺疾病","支气管哮喘","心源性哮喘","气胸"],"a":2,"e":"接触清洁剂后突发胸闷、呼吸困难，双肺满布干啰音，为变应原诱发的支气管哮喘急性发作；心源性哮喘多有心脏病史并闻及湿啰音。"},{"q":"患者，男，60岁。主诉：血压偏高2年，近1周头晕、胸闷、心悸。若反复多次测量血压在收缩压170～195mmHg、舒张压95～98mmHg之间波动，则其血压水平为","o":["临界高血压","1级高血压","2级高血压","3级高血压","单纯收缩期高血压"],"a":3,"e":"收缩压170～195mmHg属3级高血压，舒张压95～98mmHg属1级，两者分级不同时以较高级别为准，故为3级高血压。"},{"q":"患者，男，56岁，因血糖升高应用胰岛素治疗。近期拟检测糖化血红蛋白，该物质的测定可以反映的血糖水平是","o":["近1～2周","近3～4周","近5～6周","近6～8周","近8～12周"],"a":4,"e":"糖化血红蛋白是血红蛋白与葡萄糖非酶促结合的产物，其水平取决于红细胞生存期内的平均血糖，反映近8～12周的血糖控制情况。"},{"q":"患者，男，75岁。患高血压病史20年，夜尿增多3年，双下肢轻度水肿2个月入院。血压180/100mmHg，血红蛋白79g/L，血肌酐250μmol/L，尿蛋白＋＋。下列哪项检查有助于确定肾功能不全分期","o":["尿β2-微球蛋白测定","血β2-微球蛋白测定","24h尿蛋白定量测定","血尿酸测定","内生肌酐清除率测定"],"a":4,"e":"内生肌酐清除率由血、尿肌酐及尿量计算，能较准确反映肾小球滤过率，是判断肾功能损害程度及分期的常用指标。"},{"q":"患者，男，22岁，高热3天，突发意识不清、定向力丧失、出现幻觉、言语杂乱。此时患者的意识状态是","o":["意识模糊","昏睡","谵妄","轻度昏迷","中度昏迷"],"a":2,"e":"高热背景下出现意识模糊、定向力丧失、幻觉及言语杂乱，且以兴奋性增高为主，为急性感染发热所致谵妄。"},{"q":"患者，男，24岁。上腹痛半年，饥饿及进食后均有腹痛，伴有反酸、嗳气，并常有腹泻。既往胃镜示胃小弯、十二指肠球部及球后多发溃疡。胃液分析：基础排酸量（BAO）＞30mmol/h，最大酸排量（MAO）＞40mmol/h。最可能的诊断为","o":["多发性溃疡","复合性溃疡","复合溃疡恶变","胰岛β细胞瘤","胃泌素瘤"],"a":4,"e":"多发溃疡伴腹泻及基础排酸量、最大酸排量显著增高，提示胃泌素大量分泌刺激胃酸分泌，为胃泌素瘤即Zollinger-Ellison综合征。"},{"q":"患者，男，60岁，全身乏力、食欲缺乏3个月就诊。查体：皮肤黝黑，口腔有蓝黑色色素斑片沉着。皮肤未见静脉曲张，腹部检查无特殊。腹部B超未见异常。可能的诊断是","o":["肝硬化","肾上腺皮质功能减退","消化道肿瘤","肺结核","甲状腺功能亢进"],"a":1,"e":"皮肤及口腔黏膜蓝黑色色素沉着伴乏力、食欲缺乏，是肾上腺皮质功能减退时ACTH及促黑素分泌增多所致的特征性表现。"},{"q":"患者，女，25岁，心悸、气短10年。查体：心尖部S1亢进时，并可听到开瓣音及舒张中、晚期隆隆样杂音，P2亢进。此患者的诊断是","o":["主动脉瓣关闭不全","主动脉瓣狭窄","二尖瓣关闭不全","二尖瓣狭窄","二尖瓣相对性狭窄"],"a":3,"e":"心尖区第一心音亢进、开瓣音及舒张中晚期隆隆样杂音伴P2亢进，是风湿性二尖瓣狭窄的典型听诊组合。"},{"q":"患儿，男，11岁。出生1个月时发现心脏杂音，当时查体：于胸骨左缘2肋间及3/6级粗糙收缩期杂音，伴P2增强，S2固定分裂。现患儿渐感劳力性心累气紧，活动后出现发绀，杵状指。诊断考虑","o":["左心衰竭","右心衰竭","法洛四联症","肺静脉异位引流","艾森门格综合征"],"a":4,"e":"左向右分流使肺循环压力持续升高，最终肺动脉压超过体循环压而转为右向左分流，出现发绀与杵状指，即艾森门格综合征。"},{"q":"患者，男，37岁。于搬货后出现腰痛、左下肢疼痛，咳嗽时加重，休息后缓解，无关节肿胀。该患者最可能的诊断是","o":["腰肌纤维组织炎","腰肌劳损","腰椎间盘突出","髋关节结核","强直性脊柱炎"],"a":2,"e":"搬重物后腰痛伴左下肢放射痛、咳嗽时加重而休息缓解，提示突出髓核压迫神经根，为腰椎间盘突出症。"},{"q":"一名四肢力量正常患者入院后不能按照医生要求用左手摆出右手一样的姿势。考虑患者损伤在以下哪个部位","o":["脊髓后索","周围神经","脊髓侧索","小脑","锥体束"],"a":2,"e":"官方答案为【脊髓侧索】，但依据教材，正确答案为【脊髓后索】。位置觉由后索传导，后索病损时肌力虽正常，仍不能感知肢体所处姿势并用对侧肢体模仿。"},{"q":"患者，男性，32岁，因阵发性心动过速至门诊就诊，既往无心肌炎、高血压、糖尿病等病史，ECG如图。可能的诊断为","o":["预激综合征","完全左束支传导阻滞","不完全左束支传导阻滞","完全右束支传导阻滞","不完全右束支传导阻滞"],"a":0,"e":"官方题库缺失图片"},{"q":"患者，男，46岁。阵发性心悸、头晕5年，发作性心前区疼痛1周。胸部X线检查见心影呈靴型。下列哪项体征具有诊断意义","o":["心尖冲动向左下移位，呈抬举性","心浊音界向左下扩大，心腰凹陷","主动脉瓣区第二心音亢进","主动脉瓣第二听诊区叹气样舒张期杂音","脉压增大，伴有水冲脉"],"a":3,"e":"主动脉瓣第二听诊区舒张期叹气样杂音是主动脉瓣关闭不全的特征性体征，靴形心及脉压增大可为其佐证。"},{"q":"患者，女，38岁，主诉：酱油色尿2周。2周前曾因“感冒”服用对乙酰氨基酚类药物，期间曾发现尿色呈酱油色。查体见贫血外貌，双下肢散在出血点，巩膜轻度黄染。血常规示 Hb 85g/L，WBC 10.3×109/L，PLT 64×109/L。考虑药物性溶血性贫血，哪型超敏反应是其发病机制","o":["Ⅰ型超敏反应","Ⅱ型超敏反应","Ⅲ型超敏反应","Ⅳ型超敏反应","不是超敏反应"],"a":1,"e":"药物作为半抗原与红细胞膜结合，诱导IgG抗体形成并与红细胞结合，在补体及巨噬细胞参与下致红细胞破坏，属Ⅱ型超敏反应。"},{"q":"患者，女，52岁，有“风湿性心脏病”病史。入院后检查心电图：心室率85次/min，电轴150°，PⅠ、PⅡ、PavL切迹明显，P波时限＞0.13s，V1Ptf为0.08mm·s，V1R/S＞1，V5R/S＜1，P-R间期0.22s。应考虑为","o":["右心室肥大","左心房、右心室肥大","右心房、右心室肥大","左心房、右心室肥大伴一度房室传导阻滞","右心室肥大伴一度房室传导阻滞"],"a":3,"e":"P波增宽有切迹、V1导联Ptf负值增大提示左心房肥大，V1导联R/S＞1伴电轴右偏提示右心室肥大，PR间期0.22秒为一度房室传导阻滞。"},{"q":"患者，男，15岁。因“鼻塞、流涕1周，加重伴脓涕、头痛2天”就诊。查体：左右颧部明显按压痛，双肺呼吸音清，未闻及明显干、湿啰音。最可能的诊断是","o":["急性鼻炎","急性支气管炎","急性上颌窦炎","急性筛窦炎","急性额窦炎"],"a":2,"e":"鼻塞流涕后出现脓涕及头痛，颧部按压痛正对上颌窦前壁体表投影，提示炎症累及上颌窦。"},{"q":"患者，男，50岁，无特殊基础疾病，长期吸烟。间断胸闷8年，短暂意识丧失2次，胸闷发作时自测心率变慢，完善Holter如图所示，进一步诊治不可选","o":["地尔硫䓬药物治疗","硝酸酯类药物治疗","冠状动脉CTA评估","冠状动脉造影","永久起搏器植入"],"a":0,"e":"官方题库缺失图片"},{"q":"一患者体检发现眼球向下及向外运动受限。据此推测损伤以下哪条神经","o":["动眼神经","滑车神经","展神经","交感神经","面神经"],"a":1,"e":"滑车神经支配上斜肌，使眼球向下、向外运动，该方向运动受限提示滑车神经损害；动眼神经麻痹则眼球内、上、下运动均受限。"},{"q":"患儿，男，6个月。1个月前出现面部灰暗，哭闹及吃奶时出现青紫。查体：较瘦，口周发绀，心前区可闻及3级收缩期喷射音。X线示：右室肥大，肺动脉段凹陷，心脏呈靴形，肺野清晰。此患儿最可能的诊断是","o":["室间隔缺损","房间隔缺损","肺动脉段狭窄","动脉导管未闭","法洛四联症"],"a":4,"e":"右室肥大、肺动脉段凹陷、靴形心及肺野清晰伴发绀，符合法洛四联症的右室流出道梗阻、室间隔缺损、主动脉骑跨与右室肥厚。"},{"q":"患者乏力，黄疸，脾大，末梢血网织红细胞为10%，非结合胆红素升高，对自身免疫性溶血性贫血的诊断最重要的是","o":["HAM试验","渗透脆性试验","Coombs试验","冷溶血试验","高铁血红蛋白还原试验"],"a":2,"e":"自身免疫性溶血性贫血由红细胞表面不完全抗体介导，直接抗人球蛋白试验即Coombs试验阳性即可确诊。"},{"q":"患者，男，40岁。乏力，食欲缺乏3周。查体：巩膜黄染，心肺无异常，肝肋下1cm，轻触痛，脾不大。查HAV-Ag阳性。近1周患者黄疸逐渐加重，但ALT逐渐降低，这说明","o":["急性肝炎逐渐好转","转为慢性活动性肝炎","有较多的肝细胞坏死","症状与化验不符","无临床意义"],"a":2,"e":"黄疸加深而转氨酶下降称胆酶分离，提示大量肝细胞坏死、残存肝细胞已不能继续释放转氨酶，见于急性重型肝炎。"},{"q":"患者，女，42岁。右上腹疼痛1年，常在进食油脂重食物后发作。昨晚吃炖猪蹄后1小时出现右上腹痛，向右肩部放射，呕吐2次，腹部检查最可能发现压痛的部位是","o":["肋脊点","McBurney点","上输尿管点","季肋点","胆囊点"],"a":4,"e":"进食油腻食物后右上腹痛并向右肩放射，符合胆绞痛；胆囊点位于右锁骨中线与肋缘交界处，胆囊病变时此处压痛。"},{"q":"患者，男，32岁，主诉最近5天严重呕吐，极度疲劳。查体：眼凹，黏膜干燥，心率为110次/min，血压为90/50mmHg。站立时，血压下降，心率升高。动脉血气：pH 7、50，PaCO2 47mmHg，HCO3- 38mEq/L，PaO2 80mmHg。该患者可能发生了","o":["代谢性碱中毒部分代偿期","呼吸性碱中毒失代偿期","代谢性酸中毒部分代偿期","呼吸性酸中毒和低氧血症代偿期","抽取的是静脉血"],"a":0,"e":"严重呕吐致胃酸大量丢失，HCO3-升至38mEq/L，pH 7.50仍高于正常而PaCO2代偿性升至47mmHg，属代谢性碱中毒部分代偿期。"},{"q":"患者，女，36岁。劳力性心累气短半个月，既往关节肿痛史。超声提示二尖瓣重度粘连，未见钙化，开放受限。查体血压110/75mmHg，脉搏85次/min，心率145次/min，心律不齐，心音强弱不等。患者心律异常最可能为","o":["大炮音","频发房性期前收缩","心房颤动","阵发性室上性心动过速","频发室性期前收缩"],"a":2,"e":"心律绝对不规则、第一心音强弱不等且脉率少于心率，是二尖瓣狭窄合并心房颤动的典型听诊特点，脉搏短绌由此产生。"},{"q":"患者，女，25岁，运动后心悸气短3年。查体：心脏左下可闻及浊音，心腰狭窄，靴型心。主要诊断是","o":["主动脉瓣关闭不全","肺心病","扩张型心肌病","单纯二尖瓣狭窄","高血压心脏病"],"a":0,"e":"靴形心由左心室增大、心腰凹陷形成，主动脉瓣关闭不全时舒张期反流使左室容量负荷加重，可致左室扩大及心尖向左下移位。"},{"q":"患者，女，23岁。发热4天，叩诊右肺呈实音，不可能存在的疾病是","o":["大叶性肺炎","肺不张","肺结核","肺脓肿","气胸"],"a":4,"e":"气胸时胸腔内积气，叩诊呈鼓音；大叶性肺炎实变、肺不张、肺结核及肺脓肿均可出现浊音或实音。"},{"q":"患者，男，18岁，剧烈头痛、呕吐、意识不清2小时，入院诊断为化脓性脑膜炎。其脑脊液的特点是","o":["外观微混","蛋白质（＋）","氯化物增高","葡萄糖明显减低","中性粒细胞轻度增加"],"a":3,"e":"化脓性脑膜炎时细菌分解葡萄糖，脑脊液葡萄糖明显减低，同时蛋白升高、氯化物降低、中性粒细胞显著增多。"},{"q":"患者，男，56岁。胸骨后压榨性疼痛半天口含硝酸甘油不缓解而就诊，心电图显示Ⅱ、Ⅲ、aVF导联出现异常Q波，ST段弓背抬高，查体：BP 150/90mmHg，心率92次/min。最可能的诊断是","o":["高血压","心包积液","急性心肌梗死","心律失常","肺心病"],"a":2,"e":"持续胸骨后压榨痛且含服硝酸甘油不缓解，Ⅱ、Ⅲ、aVF导联出现异常Q波及ST段弓背向上抬高，提示下壁急性心肌梗死。"},{"q":"患者，女，28岁。受凉后寒战，咳嗽、咳痰、胸痛。查体：体温38.5℃，右下肺语颤增强，可闻湿性啰音。白细胞总数17×109/L，中性粒细胞90%。最可能的诊断为","o":["上呼吸道感染","急性支气管炎","急性肺脓肿","肺炎球菌肺炎","肺结核"],"a":3,"e":"寒战高热、胸痛、右下肺语颤增强伴湿啰音，白细胞及中性粒细胞明显升高，为大叶性肺炎即肺炎球菌肺炎的典型表现。"},{"q":"中年女性，喜生食蔬菜，2个月来时常发作右上腹钻顶样疼痛难以忍受，但可自然缓解。1小时前再次发作，下列最有助于诊断的是","o":["尿淀粉酶","急诊超声","粪便查虫卵","纤维内镜","立位腹平片"],"a":1,"e":"钻顶样右上腹剧痛、发作性而缓解期如常，为胆道蛔虫症；急诊超声可显示胆管内虫体，是最有助于诊断的检查。"},{"q":"患者，男，55岁。间断性心前区疼痛2个月，与劳累有关，静息心电图未见异常，运动实验提示有ST段下移0.15mV。首先考虑","o":["急性心肌梗死","心肌病","高血压冠心病","肺气肿","冠状动脉粥样硬化性心脏病"],"a":4,"e":"劳力性心绞痛伴运动试验ST段下移0.15mV，提示存在心肌缺血，诊断为冠状动脉粥样硬化性心脏病。"},{"q":"患者，女，30岁，月经减少1年就诊，伴怕冷、乏力、便秘。查体：反应迟钝，颜面水肿，眉毛稀疏，舌体大，HR 50次/min。需要完善下列哪项检查确诊","o":["性激素水平","肾功能","甲状腺功能","妇科B超","血常规"],"a":2,"e":"怕冷、乏力、便秘、反应迟钝，查体见面色苍黄、颜面水肿、眉毛稀疏、舌体肥大伴心动过缓，为甲状腺功能减退表现，确诊需检测甲状腺功能。"},{"q":"患者，女，26岁。双臂皮肤出现皮疹，呈对称性，双面颊和鼻梁部位呈蝶形红斑，同时伴有膝、踝关节痛。若怀疑为系统性红斑狼疮，需做哪项过筛试验","o":["E花环试验","抗核抗体检查","淋巴细胞转化试验","CIC检测","补体水平检测"],"a":1,"e":"双面颊及鼻梁蝶形红斑伴多关节痛高度提示系统性红斑狼疮，抗核抗体敏感性高，是本病首选的过筛试验。"},{"q":"一患者发热、咳嗽、胸痛、咳铁锈色痰，胸片示肺炎吸收消散期。此时患者患侧胸部叩诊音应为","o":["清音","实音","鼓音","浊音","空瓮音"],"a":3,"e":"消散期肺泡内渗出物尚未完全吸收、局部含气量减少，叩诊呈浊音，随渗出物清除逐渐恢复清音。"},{"q":"患者，女，38岁。自述头迷，头晕，左上肢血压13.3/10.7kPa（1kPa≈7.5mmHg）。右上肢血压21.3/12.0kPa，左侧桡动脉搏动较右侧弱。首选考虑是下列何种疾病所致","o":["主动脉缩窄","多发大动脉炎","严重贫血","动静脉瘘","甲状腺功能减退症"],"a":1,"e":"双上肢收缩压相差超过10mmHg且左侧桡动脉搏动减弱，提示主动脉弓及其分支狭窄，为多发性大动脉炎所致。"},{"q":"患者，男，70岁，有长期吸烟史。右胸部疼痛3个月，伴咳痰、痰中带血。查体：气管右偏，右上肺叩浊，呼吸音明显减弱。诊断上首先应考虑","o":["右上肺炎","右上肺癌","右上浸润性肺结核","右上包裹性积液","右上纵隔肿瘤"],"a":1,"e":"长期吸烟的老年男性出现痰中带血、气管向患侧移位及局部呼吸音减弱，提示中心型支气管肺癌阻塞支气管致肺不张。"},{"q":"患者，女，24岁，着凉后出现高热、咳嗽、咳痰3天，伴右侧胸痛，咳嗽或深吸气时加重。该患最不可能出现的体征是","o":["右侧胸廓饱满","右侧语音震颤增强","叩诊病变部位呈浊音","听诊病变部位可闻及湿啰音","气管位置居中"],"a":0,"e":"胸廓饱满见于气胸或大量胸腔积液；肺炎实变时胸廓对称，语颤增强、叩诊浊音、可闻湿啰音，气管居中。"},{"q":"患者，女，34岁。腹泻便秘交替3个月，伴发热，体温午后升高，夜间盗汗。1年前曾患肺结核。查体：轻度贫血，心肺听诊无异常，腹平软，右下腹轻度压痛，粪便常规检查（－）。最可能的诊断是","o":["肠结核","结肠易激综合征","慢性阑尾炎","结核性腹膜炎","慢性结肠炎"],"a":0,"e":"青壮年腹泻与便秘交替、午后低热、夜间盗汗，右下腹轻压痛，且有肺结核史，最符合肠结核。"},{"q":"患者，女，35岁。体检时发现甲状腺弥漫性肿大，未闻及血管杂音，血压150/50mmHg，胸骨左缘第3、4肋间可闻及舒张期叹气样杂音。最可能的诊断是","o":["甲亢性心脏病","室间隔缺损","主动脉瓣狭窄","主动脉瓣关闭不全","动静脉瘘"],"a":3,"e":"胸骨左缘第3、4肋间舒张期叹气样杂音伴舒张压降低、脉压增大，是主动脉瓣关闭不全的典型表现。"},{"q":"高血压老年患者突发左侧肢体无力。神经系统查体发现左侧肢体肌力0级，右侧周围性面瘫。考虑损伤位于","o":["右侧大脑皮层","右侧基底节区","左侧基底节区","脑干右侧","颈段脊髓"],"a":3,"e":"左侧肢体瘫痪伴右侧周围性面瘫，属交叉性瘫痪，提示脑干右侧病变同时累及锥体束与面神经核。"},{"q":"患者来院检查，接诊医生神经系统查体发现患者伸舌偏左。以此推测患者损伤以下哪一部分","o":["左副神经","右副神经","左舌下神经","右舌下神经","左舌咽神经"],"a":2,"e":"舌下神经支配同侧舌肌，单侧麻痹时舌尖偏向病灶侧，故伸舌偏左提示左侧舌下神经损伤。"},{"q":"患者，女，32岁，进行性膀胱刺激征，经抗生素治疗不见好转，伴右侧腰部胀痛及午后潮热。最合理的治疗措施是","o":["积极对症治疗","服碱性药，减轻尿路刺激症状","用抗真菌药","联合应用抗生素，作局部处理","抗结核治疗"],"a":4,"e":"进行性膀胱刺激征、抗生素治疗无效，伴腰部胀痛及午后潮热，提示肾结核，应在明确后行抗结核治疗。"},{"q":"患者，女，40岁，胃溃疡10年，突然大出血2小时，血压75/45mmHg；经输血后血压升至120/75mmHg，恢复正常，出血停止，但出现少尿，200ml/24h，考虑急性肾衰竭。下列检查对确诊最有帮助的是","o":["尿渗透压","血常规","尿常规","血肌酐","尿比重"],"a":3,"e":"急性肾衰竭时血肌酐升高且其动态变化反映肾小球滤过功能，是确诊并判断肾功能损害程度最实用的指标。"},{"q":"患者，男，37岁。近1个月来经常排鲜血便，血量少、不与粪便混合，伴里急后重，不发烧，无腹痛。最可能的诊断是","o":["直肠癌","急性坏死性肠炎","胃癌","肠结核","Crohn病"],"a":0,"e":"少量鲜血不与粪便混合、伴里急后重而无腹痛发热，提示病变位于直肠，直肠癌为最可能的诊断。"},{"q":"中年女性，反复排黏液血便2年，复发5天，伴低热左下腹疼痛。查体：贫血貌，左下腹压痛（＋）。首选的诊断方法为","o":["粪潜血检查","纤维结肠镜","X线钡剂灌肠","OT试验","骨髓穿刺术"],"a":1,"e":"反复黏液血便伴左下腹痛及贫血，需明确结肠病变性质，纤维结肠镜可直视黏膜并取活检，为首选诊断方法。"},{"q":"患者，男，38岁，发作性心悸伴气短3小时，急检心电图各导联均未见正常P波，而V1导联有明显的f波，频率为460次/min，心室率绝对不规则。下列体征具有诊断意义的是","o":["S1、S2同时减弱伴奇脉","A2减弱伴水冲脉","S1强弱不等伴短绌脉","S1减弱伴重搏脉","P2增强伴交替脉"],"a":2,"e":"P波消失代之以f波、心室率绝对不规则，为心房颤动，听诊第一心音强弱不等伴脉搏短绌具有诊断意义。"},{"q":"患者，男，46岁，因“尿频、尿急、尿痛1周，尿道口脓性分泌物”就诊。分泌物涂片革兰染色镜检示大量白细胞，在白细胞内发现革兰阴性双球菌。最可能感染的病原菌是","o":["金黄色葡萄球菌","梅毒螺旋体","淋病奈瑟菌","溶血链球菌","表皮葡萄球菌"],"a":2,"e":"尿道口脓性分泌物涂片示大量白细胞，其内见革兰阴性双球菌，为淋病奈瑟菌感染的特征性表现，可据此作出病原学诊断。"},{"q":"患者，女，36岁。劳力性心累气短半月，既往关节肿痛史。超声提示二尖瓣重度粘连，未见钙化，开放受限。查体：血压110/75mmHg，脉搏85次/min，心率145次/min，心律不齐，心音强弱不等。如触及震颤，则应为","o":["胸骨左缘第2肋间收缩期震颤","胸骨右缘第2肋间收缩期震颤","胸骨左缘第3、4肋间收缩期震颤","心尖收缩期震颤","心尖舒张期震颤"],"a":4,"e":"二尖瓣狭窄时舒张期血流经狭窄瓣口形成隆隆样杂音，常伴心尖区舒张期震颤，左侧卧位时更易触及。"},{"q":"一糖尿病患者因右侧肢体无力入院。入院查体发现巴宾斯基征阳性，损伤部位不可能是","o":["左侧基底节区","左侧大脑皮层","脑干左侧","右侧脊髓侧索","左侧脊髓侧索"],"a":4,"e":"皮质脊髓侧束支配同侧肢体，左侧侧索病变只引起左侧上运动神经元性瘫痪，不会导致右侧肢体无力及巴宾斯基征阳性。"},{"q":"患者神经系统查体，发现双下肢震动觉减退，但未见明显感觉障碍平面。考虑该患者病变累及以下哪个部位","o":["脊髓侧索","脊髓丘脑前束","神经根","脊髓前角","脊髓后索"],"a":4,"e":"震动觉由脊髓后索传导，音叉振动觉减退见于后索病损；后索病变不累及痛温觉，故临床不出现感觉障碍平面。"},{"q":"患者，女，28岁。近3个月出现体重下降5kg，伴腹泻、心悸、手抖，遂至门诊就诊。关于该患者查体时的甲状腺检查，说法不正确的是","o":["甲状腺外观可不突出","甲状腺质地中等","触诊比视诊更能明确病变性质","可能触及甲状腺震颤","甲状腺可触及疼痛"],"a":4,"e":"甲亢时甲状腺多弥漫性肿大、质地柔软，可触及震颤并闻及血管杂音，但无压痛；压痛见于亚急性甲状腺炎。"},{"q":"患者，男，63岁，面色苍白半年。查体：贫血貌，腹部无异常。大便隐血阳性。血常规：Hb 70g/L，MCV 72fl。临床给予口服硫酸亚铁治疗，该药物在消化道的主要吸收部位是","o":["胃","肝","回肠","直肠","十二指肠和空肠上段肠黏膜"],"a":4,"e":"铁的吸收部位在十二指肠和空肠上段黏膜，口服硫酸亚铁主要在此处吸收，胃酸有助于铁的游离与还原。"},{"q":"患者，女，28岁，因肥胖1年而就诊。查体：面呈满月，皮肤痤疮增多，口唇有小须，背部毳毛多见，项部脂肪垫肥厚，血压20/13、3kPa（1kPa≈7、5mmHg）。疑为库欣综合征，为了进一步明确诊断，应做的检查是","o":["血浆皮质醇测定","24h尿钾测定","24h尿蛋白测定","24h尿乳酸测定","血清醛固酮测定"],"a":0,"e":"库欣综合征因皮质醇分泌过多致病，测定血浆皮质醇昼夜节律及24小时尿游离皮质醇是明确诊断的首选检查。"},{"q":"患者，男，68岁，既往多年吸烟史。咳嗽咳痰3个月，胸片及胸部CT未见异常，痰涂片发现瘤细胞，下一步最佳检查应选","o":["胸部薄层CT","胸部增强CT","胸部磁共振","纤维支气管镜检查及活检","同位素骨扫描"],"a":3,"e":"痰中已查见瘤细胞而影像未见明确病灶，需经纤维支气管镜直视观察并活检，以确定病变部位及病理类型。"},{"q":"患者，女，34岁，3年前开始出现面部水肿，晨起明显，伴双下肢轻度水肿。1周前着凉后水肿加重，尿少、乏力、食欲缺乏来诊。患者可能的面容是","o":["急性病容","贫血面容","肾病面容","肝病面容","伤寒面容"],"a":2,"e":"长期晨起眼睑及颜面水肿伴尿少，属肾脏疾病表现；面色苍白、眼睑颜面水肿、舌淡有齿痕即肾病面容。"},{"q":"患儿，男，8个月。呕吐2天，发热伴水样便1天。查体：T 37.8℃，R 26次/min，P 110次/min，BP 80/60mmHg，神志清，精神倦，唇干，皮肤干燥，前囟凹陷，心肺无异常，腹软，肝肋下1cm，质软，脾未触及，四肢暖。根据患儿目前病情，应首先进行的检查是","o":["血培养","大便培养","血电解质分析","肝肾功能检查","脑脊液检查"],"a":2,"e":"婴儿腹泻伴前囟凹陷、唇干、皮肤干燥及尿少，提示脱水，需先查血电解质判断脱水性质与程度以指导补液。"},{"q":"患者，女，29岁。清理房间后出现鼻痒、喷嚏，继而出现胸闷、呼吸困难、端坐位，两肺布满哮鸣音。最可能的诊断是","o":["急性支气管炎","支气管哮喘","急性左心衰竭","肺炎","气胸"],"a":1,"e":"接触过敏原后鼻痒喷嚏，继而胸闷、呼吸困难、端坐位，双肺满布哮鸣音，为支气管哮喘急性发作。"},{"q":"患儿，男，1岁。间歇性抽搐3小时。查体：双侧上肢肌肉强直性肌痉挛，呈“助产手”，该患者的诊断最可能是","o":["小儿癫痫","婴儿痉挛","低钙血症","高热惊厥","重症感染"],"a":2,"e":"间歇性双侧上肢强直性肌痉挛呈助产士手，为低钙血症致神经肌肉兴奋性增高所引起的手足搐搦。"},{"q":"患者，女，23岁。头痛伴剧烈呕吐2天。1个月前诊断为急性淋巴细胞白血病，行化疗后骨髓恢复正常。查体：浅表淋巴结不大，心肺无异常。颈项强直，双侧Babinski征阳性。患者最可能的病因是","o":["病毒性脑炎","血管性头痛","颅内白血病浸润","蛛网膜下腔出血","癫痫病发作"],"a":2,"e":"急性淋巴细胞白血病化疗缓解后出现颅内压增高及脑膜刺激征，提示白血病细胞中枢神经系统浸润。"},{"q":"患者，男，52岁，诉心悸头晕1个月。心电图示：QRS波群宽大，时限0.13s，P波与QRS波无关，P波多于QRS波群，心室率40次/min，律规整。可诊断为","o":["交界区逸搏心律","窦性心动过缓","二度房室传导阻滞","未下传的房性期前收缩呈二联律","三度房室传导阻滞，室性逸搏心律"],"a":4,"e":"P波与QRS波无关且P波多于QRS波，心室率40次/min、QRS宽大畸形而律规整，为三度房室传导阻滞伴室性逸搏心律。"},{"q":"患者，女，45岁。运动中感觉眩晕、恶心、乏力，随即意识丧失，摔倒在地，3min后自行恢复正常。无大小便失禁，缓解后无意识及肢体功能障碍，其最可能的病因是","o":["短暂脑缺血发作","低血糖症","心率失常","迷走神经张力异常增高","分离（转换）性障碍"],"a":0,"e":"运动中突发眩晕后意识丧失，数分钟内完全恢复且无残留神经功能缺损，符合椎基底动脉系统短暂性脑缺血发作。"},{"q":"患者，女，50岁，发现血脂升高、蛋白尿、周身水肿10余年。查体发现少量胸腔积液。实验室检查：清蛋白20g/L，三酰甘油7.22mmol/L，总胆固醇8.34mmol/L，尿蛋白（＋＋＋）。符合该患者胸腔积液特点的是","o":["浑浊","葡萄糖低于血糖水平","LDH＞200U/L","能自凝","积液蛋白/血清总蛋白＜0.5"],"a":4,"e":"大量蛋白尿、低清蛋白血症所致胸腔积液为漏出液，积液蛋白与血清总蛋白比值小于0.5，LDH亦低于200U/L。"},{"q":"患者，女，28岁。恶心、尿色变黄6天，体检发现巩膜中度黄染，肝肋下2cm可及，血谷丙转氨酶840U/L，总胆红素85μmol/L。本例抗HAV-IgM阳性，抗HBs阳性，抗HBc阳性，最可能的病原学诊断是","o":["甲型病毒性肝炎","乙型病毒性肝炎","甲型病毒性肝炎和乙型病毒性肝炎重叠感染","戊型病毒性肝炎","丙型病毒性肝炎"],"a":0,"e":"抗HAV-IgM阳性是甲型肝炎近期感染的特异性指标；抗HBs与抗HBc阳性仅提示既往乙肝感染已恢复并具免疫力。"},{"q":"某2岁患儿，前额突出，头顶平坦呈方形，出汗多。该患儿可能性最大的疾患是","o":["脑积水","佝偻病","甲状腺功能减退症","肢端肥大症","库欣病"],"a":1,"e":"方颅即前额左右突出、头顶平坦呈方形，系佝偻病骨样组织堆积所致，常伴多汗、易惊等表现。"},{"q":"患者，男，45岁。半天前跑步后出现右下腹疼痛伴发热、畏寒，6小时前转至脐周疼痛。此时最应注意的腹部体征是","o":["脐周有无压痛","McBurney点是否压痛","墨菲征是否阳性","季肋点有无压痛","肠鸣音是否改变"],"a":1,"e":"转移性右下腹痛是急性阑尾炎的典型病史，发病数小时后右下腹McBurney点出现固定压痛及反跳痛。"},{"q":"患者，女，36岁。半年前开始发现面色逐渐变白，甲床颜色亦变浅。1周前开始出现活动后易疲乏来医院就诊。既往体检曾发现子宫肌瘤，未处理。该患者就诊时的面容可能是","o":["急性病容","慢性病容","黏液水肿面容","贫血面容","苦笑面容"],"a":3,"e":"面色与甲床逐渐苍白、活动后易疲乏，结合子宫肌瘤所致长期慢性失血，符合面色苍白、唇舌色淡、表情疲惫的贫血面容。"},{"q":"患者，男，63岁。慢性咳嗽、咳痰伴呼吸困难20年，今晨用力咳嗽后突然出现呼吸困难加重，发绀，不能平卧。查体右侧呼吸动度减弱伴叩诊为鼓音、呼吸音消失。该患最有可能的诊断是","o":["左侧肺不张","右侧胸腔积液","右下大叶性肺炎","右侧气胸","右侧肺不张"],"a":3,"e":"慢性肺病患者用力咳嗽后突发呼吸困难加重，患侧呼吸动度减弱、叩诊鼓音、呼吸音消失，为右侧气胸。"},{"q":"患者，女，33岁。因面部红斑1年入院，考虑诊断为系统性红斑狼疮。患者既往有多次流产病史，实验室检查示ACA＋，APTT延长。目前考虑诊断为","o":["系统性红斑狼疮合并抗心磷脂抗体综合征","Evans综合征","血管栓塞","TTP","HUS"],"a":0,"e":"系统性红斑狼疮患者抗心磷脂抗体阳性、APTT延长并有多次流产史，符合抗磷脂抗体综合征，属继发性抗磷脂综合征。"},{"q":"患者，男，20岁。多次于郊外春游时出现胸闷、窒息感，呼气性呼吸困难，回家休息后好转。该患发作时最不可能出现的体征是","o":["呼吸运动度变小","语音共振减弱","叩诊呈过清音","双肺满布干啰音","呼吸音增强"],"a":4,"e":"支气管哮喘发作时气道痉挛、通气减少，肺泡呼吸音减弱而非增强。典型体征为呼吸动度变小、语音共振减弱、叩诊过清音及双肺满布干啰音，故呼吸音增强最不可能出现。"},{"q":"患者，女，50岁，3次分娩史。半年来，咳嗽、下楼梯时出现尿失禁症状。该患者尿失禁为","o":["真性尿失禁","压力性尿失禁","持续性尿失禁","间歇性尿失禁","急迫性尿失禁"],"a":1,"e":"腹压骤增时尿液不自主溢出而逼尿肌无收缩，属压力性尿失禁。其机制为膀胱颈部及尿道括约肌支持结构松弛、闭合压下降，多次分娩是常见诱因。"},{"q":"一男性患者，30岁。淋雨后出现咳嗽，咯铁锈色痰，发热，右侧胸痛。查体：BP 130/80mmHg，右肺中上野叩诊实音。该患者最不可能出现下列哪种体征","o":["右肺可闻及胸膜摩擦音","右肺触觉语颤增强","右肺可闻及管状呼吸音","肺泡呼吸音增强","呼吸浅快"],"a":3,"e":"右肺实变时肺泡被炎性渗出物充填，肺泡呼吸音减弱并代之以管状呼吸音，语颤增强。发热与胸痛使呼吸浅快，炎症波及胸膜时还可闻及胸膜摩擦音。"},{"q":"患者，男，20岁。右侧呼吸运动减弱，语颤消失，右下叩诊实音，实音区上方闻及支气管呼吸音。首先应考虑为","o":["支气管哮喘","大叶性肺炎","支气管扩张","胸腔积液","支气管肺癌"],"a":3,"e":"患侧呼吸运动减弱、语颤消失、叩诊实音而积液区上方闻及支气管呼吸音，为胸腔积液的典型表现。积液压迫肺组织形成压迫性肺不张，局部致密有利于支气管音传导。"},{"q":"患者，男，22岁，打篮球时突然呼吸困难，明确诊断为右侧大量气胸。关于该患者的体格检查，描述错误的是","o":["右侧胸廓膨满","气管移向左侧","右侧叩诊为鼓音","右侧呼吸音弱","右侧可闻及支气管呼吸音"],"a":4,"e":"气胸时胸膜腔积气使传音不良，患侧呼吸音与语音共振减弱或消失，不出现支气管呼吸音。支气管呼吸音见于肺实变及压迫性肺不张。"},{"q":"患者，女，46岁，2型糖尿病病史10年，1天前明确诊断为糖尿病酮症酸中毒，该患者最可能出现的呼吸改变是","o":["规则呼吸后出现长周期呼吸停止又开始呼吸","呼吸深快","正常的呼吸节律中插入1次深大呼吸","吸气相突然中止，呼吸运动短暂的突然受到抑制","一种由浅慢逐渐变为深快，然后再由深快转为浅慢，随之出现一段呼吸暂停后，又开始上述变化的周期性呼吸"],"a":1,"e":"严重代谢性酸中毒时细胞外液碳酸氢根不足、pH降低，机体通过深快呼吸排出二氧化碳进行代偿，称库斯莫尔呼吸。糖尿病酮症酸中毒是典型病因。"},{"q":"患者突然高热，右侧胸痛，下列哪项有助于单纯少量胸腔积液与单纯肺炎实变的鉴别","o":["呼吸运动","气管位置","叩诊音","胸膜摩擦音","肺泡呼吸音"],"a":3,"e":"少量积液与肺炎实变在呼吸运动、叩诊音及语颤上均可相似，难以区分。胸膜摩擦音见于纤维蛋白性胸膜炎，积液增多使两层胸膜分开后即消失，可借以鉴别。"},{"q":"一位发热患者，体温在39℃以上，未用任何退热降温措施，24小时内体温波动达2℃以上，最低时体温仍高于正常。这种热型是","o":["稽留热","弛张热","间歇热","波浪热","回归热"],"a":1,"e":"弛张热指体温持续39℃以上，24小时内波动超过2℃而最低体温仍高于正常，又称败血症热型。稽留热波动不超过1℃，间歇热则为高热与正常体温交替。"},{"q":"患者，女，45岁，外阴瘙痒伴泡沫样分泌物，白带增多变黄绿色。镜检分泌物，考虑为寄生虫感染，下列哪种为妇科常见","o":["丝虫","阴道滴虫","溶组织变形虫","阿米巴原虫","弓形虫"],"a":1,"e":"泡沫样黄绿色分泌物伴外阴瘙痒是滴虫性阴道炎的典型表现，病原体为阴道毛滴虫。镜检可见活动的毛滴虫，为妇科最常见的寄生虫性阴道炎。"},{"q":"患者，男，78岁，头痛伴意识障碍4小时，头颅CT提示蛛网膜下腔出血，以下心电图表现和脑出血相关的是","o":["T波高耸","宽而深的倒置T波，往往伴QT延长","窄而深的倒置T波，往往伴QT缩短","T波表现为类似冠状动脉粥样硬化性心脏病的“冠状T”","T波平坦"],"a":1,"e":"脑血管意外可引起宽而深的倒置T波，常伴显著QT间期延长，称脑性T波。其形态与演变规律不同于冠心病冠状T波，结合神经系统表现可鉴别。"},{"q":"患儿，男，8岁。受凉后突发左侧脸肿胀，张口受限。查体：左侧以耳垂为中心颜面肿胀，有压痛，导管处加压未见脓性分泌物。血常规正常。可能的诊断是","o":["急性流行性腮腺炎","急性化脓性腮腺炎","腮腺肿瘤","蚊虫叮咬","外伤"],"a":0,"e":"学龄儿童受凉后以耳垂为中心腮腺肿痛、张口受限，导管口无脓性分泌物且血象正常，符合急性流行性腮腺炎。急性化脓性腮腺炎多有高热及导管口溢脓。"},{"q":"患者，男，45岁。低热、乏力、食欲缺乏1周。查体：皮肤黏膜黄染，肝肋下2cm，脾肋下1cm。实验室检查：总胆红素50μmol/L，结合胆红素20μmol/L，非结合胆红素30μmol/L，尿胆原（＋＋），尿胆红素（－）。该患者黄疸最可能的原因是","o":["溶血性黄疸","肝细胞性黄疸","梗阻性黄疸","黄疸性质不明","药物性黄疸"],"a":1,"e":"总胆红素、结合与非结合胆红素均升高，结合胆红素比值约40%处于20%～50%区间，符合肝细胞性黄疸。溶血性黄疸以非结合胆红素升高为主，结合胆红素比值低于20%。"},{"q":"患者，男，30岁，因四肢瘀斑、牙龈出血1周入院。查体：贫血貌，皮肤黏膜多发出血，胸骨下端轻度压痛。实验室检查：白细胞增高，分类见幼稚细胞，血红蛋白90g/L，血小板12×109/L，ATPP 40s（对照 45s），PT 13s（对照 11s），TT 24s（对照 13s），D-二聚体 5.3mg/L（参考范围0～0.25mg/L）。以下判断正确的是","o":["ATPP和PT正常，D-二聚体增高，考虑出血导致继发改变，可不需要处理","患者D-二聚体增高，说明高凝状态，可考虑使用华法林抗凝治疗","TT延长，有出血风险，应该加用凝血酶","尽快输注血小板和纤维蛋白原输注","尽快输注血小板，为避免高凝状态，不应该输注纤维蛋白原"],"a":3,"e":"血小板极低、TT延长而D-二聚体显著增高，提示凝血因子与纤维蛋白原大量消耗并继发纤溶亢进。应及时补充血小板及纤维蛋白原，而非抗凝或单纯观察。"},{"q":"患者，男，55岁，肥胖体型，反复多关节肿痛20年，平时未重视。1周前再次于大量饮酒后复发，尤以右侧第一跖趾关节疼痛明显。查体可见右侧跖趾关节周围大小不一的灰白色结节，应诊断为","o":["风湿结节","痛风结节","结节性红斑","动脉炎结节","Osler结节"],"a":1,"e":"第一跖趾关节反复红肿疼痛、饮酒后发作，关节周围出现灰白色结节，为尿酸盐结晶沉积形成的痛风石。其为痛风特征性病变，多见于耳郭及跖趾关节。"},{"q":"患者，男，78岁，高血压病史30余年，因“反复发作胸闷、气紧4年余，加重伴双下肢水肿3天”入院。查体：呼吸急促，大汗淋漓，面色苍白。该患者的体位可能是","o":["被动体位","强迫坐位","强迫侧卧位","强迫仰卧位","辗转体位"],"a":1,"e":"急性左心衰竭肺淤血时，坐位可减少回心血量、降低膈肌阻力并便于辅助呼吸肌参与，故取强迫坐位，又称端坐呼吸。该体位能增加肺通气量并减轻心脏负担。"},{"q":"年轻男性，发热5天，每天体温维持在39℃～41℃，24小时内体温波动相差不超过1℃。体检发现腹部玫瑰疹，肝脾大。最可能的诊断为","o":["大叶肺炎","流行性出血热","风湿热","疟疾","伤寒"],"a":4,"e":"稽留高热、腹部玫瑰疹及肝脾肿大是伤寒的典型表现。伤寒高热期体温恒定于39～40℃，24小时波动不超过1℃，血或骨髓培养可确诊。"},{"q":"患者，女，40岁。咳嗽、气短1个月，伴午后发热、盗汗，右侧胸痛。查体：气管左移，右侧胸廓饱满，叩诊实音。最不可能出现的体征是","o":["右侧呼吸音减弱","右侧触觉语颤减弱","可听到支气管呼吸音","可听到胸膜摩擦音","右侧可听到支气管肺泡呼吸音"],"a":3,"e":"大量积液使脏、壁胸膜分开，胸膜摩擦音消失；气管移向健侧、患侧饱满、叩诊实音、呼吸音及语颤减弱均符合。积液上方有时可闻及支气管呼吸音。"},{"q":"患儿，女，8岁。发热，鼻出血，四肢大量瘀点瘀斑2天，发病前1周有感冒史，血小板15×109/L，骨髓增生活跃，巨核细胞增多，成熟受阻。最可能的诊断为","o":["急性原发免疫性血小板减少症","再生障碍性贫血","慢性原发免疫性血小板减少症","过敏性紫癜","弥散性血管内凝血"],"a":0,"e":"儿童感染后突发皮肤黏膜出血、血小板显著减少，而骨髓巨核细胞增多伴成熟受阻，为原发免疫性血小板减少症的典型骨髓象。病程短于6个月者属急性型。"},{"q":"患者，女，27岁。3天前淋雨后寒战、高热，胸痛，咳嗽，咳铁锈色痰。考虑诊断为","o":["干酪性肺炎","阻塞性肺炎","肺脓肿","大叶性肺炎","病毒性肺炎"],"a":3,"e":"淋雨后寒战高热、胸痛、咳铁锈色痰是大叶性肺炎的典型表现，多由肺炎链球菌引起。病变累及整个肺段，X线可见大片均匀实变影。"},{"q":"患者，女，30岁，因怕热、多汗、心悸、多食、消瘦4个月就诊。关于甲状腺检查，错误的是","o":["注意观察甲状腺的大小和对称性","要先视诊后再进行触诊","检查时嘱被检查者做呼吸动作，可见甲状腺随呼吸动作而向上移动","检查时嘱被检查者做吞咽动作，可见甲状腺随吞咽动作而向上移动","如不易辨认，嘱被检查者两手放于枕后，头向后仰，再进行观察即较明显"],"a":2,"e":"甲状腺借结缔组织连于环状软骨与气管，随吞咽动作上下移动而非随呼吸移动，观察时应嘱病人吞咽。触诊较视诊更能明确其轮廓及病变性质。"},{"q":"患者，男，70岁，前列腺癌病史2年。为评估血栓前状态，下列可用来评估纤溶活性的检查中，有利于区分原发纤溶和继发纤溶的是","o":["D-二聚体","FDPs","血浆组织型纤溶酶原激活剂","血浆纤溶酶原激活抑制剂-1活动测定","优球蛋白溶解时间"],"a":0,"e":"原发性纤溶时纤维蛋白原被降解而交联纤维蛋白未形成，D-二聚体不增高；继发性纤溶有交联纤维蛋白形成，D-二聚体升高，故可鉴别二者。"},{"q":"患者，男，66岁。因胸闷2小时入院，完善冠脉造影，考虑诊断为急性心肌梗死。除常见的肌酶增高外，可以增高的指标还有","o":["TAT","AT","PT","APTT","TT"],"a":0,"e":"急性心肌梗死时凝血系统激活、凝血酶生成增多，凝血酶-抗凝血酶复合物TAT随之升高，反映凝血酶活性增强。抗凝血酶AT则因消耗而降低，方向相反。"},{"q":"患者，女，34岁，近1年来反复上腹痛，进食半小时后腹痛明显，伴反酸、胃灼热，1小时前突发上腹部剧烈疼痛，伴恶心、呕吐。该患者查体所见除外下列哪项","o":["肠鸣音消失","肠型","腹式呼吸减弱","板状腹","压痛、反跳痛"],"a":1,"e":"溃疡穿孔致弥漫性腹膜炎，表现为板状腹、压痛反跳痛、腹式呼吸减弱及肠鸣音消失。肠型是肠管扩张、肠梗阻的表现，穿孔时反而不出现。"},{"q":"一剧烈头痛患者入院。接诊医生查体发现患者右侧瞳孔散大，右侧眼睑下垂，直接对光反射消失。考虑患者损伤的神经是","o":["滑车神经","动眼神经","展神经","交感神经","面神经"],"a":1,"e":"右侧瞳孔散大、上睑下垂、直接对光反射消失，为动眼神经麻痹的表现。动眼神经支配提上睑肌与瞳孔括约肌，受损后眼睑下垂、瞳孔散大且对光反射消失。"},{"q":"患者，男，66岁，胸闷、气短10年，加重伴呼吸困难2天入院。既往冠心病史多年。查体发现少量胸腔积液。那么该患者的胸腔积液LDH可能为","o":["＜100IU","＜150IU","＜200IU","＞200IU","＞300IU"],"a":2,"e":"冠心病心衰所致的胸腔积液属漏出液，其LDH＜200U/L，积液与血清LDH比值＜0.6，蛋白含量亦低。渗出液则LDH＞200U/L，常见于炎症与肿瘤。"},{"q":"患者，女，35岁。1个小时前因与家人不和，自服药水1小瓶，把药瓶打碎扔掉。家人发现后5分钟患者腹痛、恶心，并呕吐1次，吐出物有大蒜味，逐渐神志不清，急送医院就诊，病后大小便失禁，出汗多。检查该患者瞳孔，可能发现何种体征","o":["双侧瞳孔放大","双侧瞳孔缩小","双侧瞳孔大小不等","瞳孔对方反射消失","集合反射消失"],"a":1,"e":"有机磷农药抑制胆碱酯酶，乙酰胆碱蓄积使瞳孔括约肌收缩，出现双侧瞳孔缩小，并伴大蒜味、多汗及分泌物增多。阿托品中毒则表现为瞳孔散大。"},{"q":"一名17岁的糖尿病患者来到急诊，为Kussmaul呼吸，床旁血气：pH 7.05，HCO3- 5mEq/L，PaCO2 12mmHg，PaO2 108mmHg。该患者可能发生了","o":["严重的代谢性酸中毒部分代偿期","呼吸性碱中毒失代偿期","代谢性碱中毒失代偿期","呼吸性酸中毒与低氧血症代偿期","抽取的是静脉血"],"a":0,"e":"pH 7.05、碳酸氢根显著降低，而二氧化碳分压降至12mmHg系过度通气代偿，符合严重代谢性酸中毒部分代偿期。库斯莫尔呼吸即为其代偿表现。"},{"q":"患者，男，40岁。上腹痛1天，腹部检查右下腹McBurney点有固定压痛和反跳痛，应首先考虑的疾病是","o":["盲肠肿瘤","输尿管结石","急性阑尾炎","肠系膜淋巴结炎","前列腺癌伴腹腔转移"],"a":2,"e":"McBurney点固定压痛与反跳痛是急性阑尾炎最重要的体征。炎症波及壁腹膜后出现定位明确的右下腹痛，多伴转移性右下腹痛病史。"},{"q":"患者，男，18岁。右膝关节肿胀疼痛，伴潮热盗汗3个月。最可能的疾病是","o":["类风湿关节炎","创伤性关节炎","骨肿瘤","关节结核","化脓性关节炎"],"a":3,"e":"青壮年单关节肿胀疼痛伴潮热、盗汗等结核中毒症状，符合结核性关节炎。膝关节结核常呈梭形膨大，浮髌试验阳性，X线可见骨质破坏。"},{"q":"患者，男，35岁，阵发性心悸3年，发作时持续半小时至5小时不等，休息可终止。本次发作时心律齐，180次/min。下列哪项有助于室上性心动过速的诊断","o":["心电图示宽大畸形QRS波","按压颈动脉窦能终止发作","既往冠状动脉粥样硬化性心脏病、心绞痛病史","心电图上发现室性融合波","可见房室分离"],"a":1,"e":"阵发性室上速多由房室结折返引起，刺激迷走神经如按压颈动脉窦可终止发作。宽大畸形QRS波、室性融合波及房室分离均支持室性心动过速。"},{"q":"患者，男，60岁。突发右侧胸痛、呼吸困难3小时。右侧股骨头坏死2个月，未行手术治疗。查体：巩膜黄染，右肺呼吸音低，心脏无异常，双下肢轻度凹陷性水肿。患者最可能出现的并发症是","o":["自发性气胸","肺梗死","脑梗死","感染性心内膜炎","急性心肌梗死"],"a":1,"e":"股骨头坏死卧床致血流淤滞，突发胸痛、呼吸困难伴发绀，应警惕肺血栓栓塞及肺梗死。可伴胸膜摩擦音、乳酸脱氢酶升高及D-二聚体阳性。"},{"q":"患者，男，57岁，头痛剧烈，喷射性呕吐，体检示皮肤出血性瘀斑，脑膜刺激征（＋）。培养此病原菌应选用","o":["巧克力色血琼脂培养基","鲍-金培养基","罗氏培养基","吕氏培养基","远藤培养基"],"a":0,"e":"剧烈头痛、喷射性呕吐、皮肤瘀斑及脑膜刺激征提示流行性脑脊髓膜炎，病原为脑膜炎奈瑟菌。该菌营养要求高，须用巧克力色血琼脂培养基分离培养。"},{"q":"患者查体时发现肢体僵硬，肌肉坚实，上肢伸直时存在明显阻力增加。考虑患者存在以下哪个体征","o":["肌力增加","肌张力增加","震颤","病理征阳性","脑膜刺激征阳性"],"a":1,"e":"肌肉触之坚实、被动伸屈时阻力增加，属肌张力增高，由锥体束或锥体外系损害所致。肌力指主动运动时肌肉收缩的力量，与肌张力概念不同。"},{"q":"患者，男，50岁，田间劳动后突然跌倒，随即昏迷，1天后出现发热。查体：T 37.9℃，BP 160/95mmHg。该患者最可能的诊断是","o":["巴比妥类中毒","中暑","流行性脑脊髓膜炎","脑出血","流行性乙型脑炎"],"a":3,"e":"活动中突然跌倒昏迷、血压显著升高，一天后出现发热，符合先昏迷后发热的脑出血。先发热后昏迷多见于流行性乙型脑炎、流行性脑脊髓膜炎及中暑。"},{"q":"患者，男，55岁，心电图检查显示胸导联T波直立，u波倒置，下列说法正确的是","o":["多提示心肌病","多提示冠状动脉粥样硬化性心脏病","多提示肺源性心脏病","多提示心包积液","多提示低钾血症"],"a":1,"e":"胸导联T波直立而U波倒置，多见于冠状动脉粥样硬化性心脏病心肌缺血。低钾血症表现为U波增高、T波低平或倒置，方向与之相反。"},{"q":"一高楼跌落患者送入医院，医师接诊后查体发现患者双下肢完全不能移动，双上肢活动正常，小便潴留，双侧巴宾斯基征阳性。考虑患者损伤","o":["大脑皮层","颈段脊髓","胸段脊髓","脊髓圆锥","马尾神经"],"a":2,"e":"双下肢瘫而上肢正常，提示病变位于胸段脊髓；尿潴留与巴宾斯基征阳性说明锥体束受累。颈段病变引起四肢瘫，腰骶段病变多呈弛缓性瘫。"},{"q":"某幼儿在玩耍时，突然出现烦躁不安、唇发绀、呼吸困难，查体呈三凹征，考虑可能的原因是","o":["气管异物","呼吸衰竭","大量胸腔积液","自发性气胸","急性支气管炎"],"a":0,"e":"幼儿玩耍时突发烦躁、发绀、呼吸困难并呈三凹征，提示气道异物梗阻。三凹征指吸气时胸骨上窝、锁骨上窝及肋间隙凹陷，见于上呼吸道梗阻。"},{"q":"患者，男，32岁，因腹痛、腹胀入院。经行肠系膜动脉造影等检查确诊为小肠动脉血栓栓塞，经溶栓治疗治愈。1个月后患者出现左下肢肿胀、疼痛，彩色多普勒示左髂内静脉血栓，辅助检查示AT降低，APTT、PT正常，考虑诊断为","o":["再生障碍性贫血","先天性AT缺陷症","血友病","肝脏疾病","白血病"],"a":1,"e":"反复静脉血栓形成、抗凝血酶活性降低而PT与APTT正常，符合先天性抗凝血酶缺陷症。抗凝血酶是生理性抗凝物质，缺乏时凝血酶灭活减少而易致血栓。"},{"q":"患者查体发现伸肌和屈肌肌张力均增高，做被动运动时各个方面肌力增加是均匀一致。考虑损伤以下哪个部位","o":["锥体外系","周围神经","四肢肌肉","神经根","锥体系"],"a":0,"e":"伸肌与屈肌张力均增高、各方向阻力均匀一致，为铅管样强直，是锥体外系损害的表现，伴震颤时呈齿轮样。锥体束损害则表现为折刀样痉挛。"},{"q":"患者，男，56岁。胸骨后压榨性疼痛半天口含硝酸甘油不缓解而就诊，心电图显示Ⅱ、Ⅲ、aVF导联出现异常Q波，ST段弓背抬高，查体：BP 150/90mmHg，心率92次/分。病变部位是","o":["下壁","前壁","后壁","前侧壁","广泛前壁"],"a":0,"e":"Ⅱ、Ⅲ、aVF导联出现异常Q波伴ST段弓背向上抬高，为急性下壁心肌梗死。多由右冠状动脉闭塞所致，易合并房室传导阻滞及右心室梗死。"},{"q":"患者，男，19岁。体检发现：气管居中，两侧胸廓饱满，呼吸运动减弱，两肺叩诊呈过清音，呼气时间延长，可闻及哮鸣音。考虑诊断为","o":["哮喘","胸腔积液","大叶性肺炎","气胸","肺不张"],"a":0,"e":"双肺过清音、呼气相延长伴哮鸣音，且气管居中、两侧对称，符合支气管哮喘发作。气胸多为单侧鼓音伴气管移位，与双肺对称的体征不符。"},{"q":"患者突发心悸，心电图示心率160次/min，QRS波时间0.10s，未见P波，R-R绝对不齐。最可能为","o":["房室交界性逸搏心率","阵发性室上性心动过速","阵发性室性心动过速","窦性心动过速","心房颤动"],"a":4,"e":"P波消失、R-R间期绝对不齐而QRS波形态正常，为心房颤动的典型心电图。房颤时心房频率350～600次/分，心室率快而不规则。"},{"q":"患者，男，52岁。因“呼吸困难伴双下肢水肿进行性加重3周”就诊。查体：BP 90/80mmHg，P 100次/min，奇脉，颈静脉怒张，心音低钝，X线见心脏向双侧扩大，双肺野清晰，最可能的诊断是","o":["扩张型心肌病","病毒性心肌炎","肥厚性心脏病","高血压心脏病","心包积液"],"a":4,"e":"奇脉、颈静脉怒张、心音低钝、心界向两侧扩大而肺野清晰，为大量心包积液致心脏压塞。心浊音界随体位改变、卧位心底部增宽是其特点。"},{"q":"患者，男，45岁，主诉头痛1个月。查体：BP 170/90mmhg，心界不大，心率75次/min，律齐有力，未及明确杂音，未发现神经系统异常。哪项诊断可能性最低","o":["尿毒症","肾动脉狭窄","甲状腺功能亢进","原发性醛固酮增多症","脑部肿瘤"],"a":4,"e":"血压明显升高而心界不大、无神经系统异常，头痛由高血压所致，缺乏颅内占位的定位体征。脑部肿瘤的头痛多伴喷射性呕吐、视盘水肿及局灶损害。"},{"q":"患者，女，19岁。受凉后出现咽痛、高热，右肩、右膝、左踝关节疼痛，伴活动后心悸、气促。最可能的疾病是","o":["结核性关节炎","风湿热","痛风关节炎","变异型骨关节炎","类风湿关节炎"],"a":1,"e":"青年女性上呼吸道感染后出现游走性多关节炎，伴心悸、气促，符合风湿热。其关节痛呈多发性、对称性、游走性，愈后不留畸形，心脏受累最常见。"},{"q":"患者，男，28岁，因四肢无力1个月入院。查：尿pH 7.0，血钾2.3mmol/L，血钙1、95mmoL/L，血氯114mmol/L，血pH 7.2，血肌酐80μmol/L。患者最可能诊断是","o":["Ⅰ型肾小管性酸中毒","Ⅱ型肾小管酸中毒","Ⅲ型肾小管性酸中毒","Ⅳ型肾小管性酸中毒","Fanconi综合征"],"a":0,"e":"高氯性代谢性酸中毒伴低血钾而尿pH＞6.0，为Ⅰ型即远端肾小管性酸中毒。远端小管泌氢障碍使尿液不能酸化，故尿pH持续偏高。"},{"q":"患者，男，66岁，因“反复咳嗽、咳痰20年，活动后气促5年，加重伴双下肢水肿1天”收入院。1天前，上呼吸道感染后症状加重，伴夜间阵发性呼吸困难。查体：半卧位，口唇及四肢发绀，颈静脉怒张，肝颈静脉反流征阳性，双肺可闻及细湿啰音，双下肢凹陷性水肿。目前该患者的发绀类型是","o":["肺性发绀","心性混合性发绀","淤血性周围性发绀","缺血性周围性发绀","混合性发绀"],"a":4,"e":"慢性肺心病急性加重时，既有肺换气障碍所致中心性发绀，又有右心衰末梢淤滞所致周围性发绀，二者并存称混合性发绀。口唇与四肢同时发绀为其特点。"},{"q":"患者，女，55岁。高血压20年，不规则服药。某日晨突发头痛，意识不清，30min后送到医院。查体：昏迷，血压190/120mmHg，双眼向右侧凝视，左足外旋位。为明确诊断，最有价值的辅助检查是","o":["腰穿检查","脑电图检查","脑超声检查","头颅CT检查","开颅探查"],"a":3,"e":"高血压病人活动中突发头痛、昏迷，双眼向病灶侧凝视并伴对侧偏瘫，提示脑出血。头颅CT可迅速显示高密度出血灶，为首选检查。"},{"q":"一高血压患者，突发呼吸困难，咳嗽，咳粉红色泡沫状痰，听诊时双肺底布满水泡音，此时该患者的肺部叩诊音应为","o":["浊音","实音","鼓音","浊鼓音","过清音"],"a":3,"e":"急性左心衰竭肺水肿时肺泡含气量减少而间质含水增多，叩诊呈兼有浊音与鼓音特点的浊鼓音。该音亦见于肺不张及肺炎充血期。"},{"q":"34岁女性，腹痛3小时入院。婚姻史应记录的内容不包括","o":["性生活情况","夫妻关系","结婚年龄","丈夫健康状况","生育次数"],"a":4,"e":"婚姻史包括婚姻状况、结婚年龄、配偶健康状况、性生活情况及夫妻关系。生育次数属生育史内容，与月经史同列，不记入婚姻史。"},{"q":"患者，男，42岁，近2年来经常出现头昏、无力，伴心前区疼痛。查体：BP 150/60mmHg，P 90次/min，心尖部向左下移位，听诊胸骨左缘3肋间可闻及舒张期叹气样杂音。X线见左室增大。其病变可能为","o":["二尖瓣狭窄","二尖瓣狭窄合并肺动脉高压","主动脉瓣狭窄","主动脉瓣关闭不全","冠心病、心绞痛"],"a":3,"e":"胸骨左缘第3肋间舒张期叹气样杂音、脉压增宽及左心室增大，为主动脉瓣关闭不全的典型表现。舒张期反流使舒张压下降，故脉压增大并出现水冲脉。"},{"q":"患者，女，56岁。会阴部渗液1个月。查体：小阴唇结节、溃烂。患者最可能的诊断是","o":["外阴溃疡","外阴白斑","外阴皮肤癌变","阴部感染","尖锐湿疣"],"a":2,"e":"小阴唇结节伴溃烂、渗液应考虑癌变可能，须活检确诊。外阴白斑为色素脱失斑片，尖锐湿疣呈乳头状或蕈样突起，均与结节溃烂不同。"},{"q":"老年男性，慢性咳嗽、活动后呼吸困难40年，明确诊断为慢性阻塞性肺疾病。该患者的听诊特点是","o":["肺泡呼吸音减弱，伴呼气延长","吸气相延长","大水泡音","鼾音","痰鸣音"],"a":0,"e":"慢性阻塞性肺疾病因气道阻塞及肺弹性回缩力下降，肺泡呼吸音普遍减弱、呼气相延长，双肺底可闻湿啰音。桶状胸、过清音及肺下界下移亦为其体征。"},{"q":"一患者四肢肌力正常，大便控制不佳，入院查体发现肛周反射消失。患者损伤可能是以下哪个部位","o":["颈髓第1～2节段","胸髓第11～12节段","腰髓第2～4节段","骶髓第4～5节段","大脑皮层"],"a":3,"e":"肛门反射由骶髓4～5节段支配，其消失提示该节段或锥体束受损。患者四肢肌力正常而大便失禁，病变定位于骶髓而非颈、胸、腰段。"},{"q":"某患者车祸后出现昏迷，头部CT提示蛛网膜下腔出血，该患者有可能出现","o":["颈强直","斜颈","头部活动自如","落日现象","扑翼样震颤"],"a":0,"e":"蛛网膜下腔出血使脑膜受激惹，出现颈强直、Kernig征及Brudzinski征等脑膜刺激征。颈强直为屈颈时阻力增高，是最常见的脑膜刺激征。"},{"q":"患者，女，59岁，因“间断关节痛4个月”就诊，查类风湿因子阳性。有关类风湿因子的描述正确的是","o":["以变性IgG刺激机体产生IgG型为主的抗体","能与变性IgG发生特异性结合反应","以IgG型类风湿因子为主，但也有IgM类、IgA类、IgD类和IgE类","特异性高，阳性仅见于类风湿性关节炎患者","参与Ⅰ型超敏反应"],"a":1,"e":"类风湿因子是针对变性IgG Fc段的自身抗体，能与变性IgG特异性结合，以IgM型为主。其特异性不高，亦可见于干燥综合征、慢性肝病及健康老年人。"},{"q":"患者，女，33岁。多尿、乏力、腰痛1年，有重金属接触史。尿常规：尿蛋白（＋＋＋）。诊断为肾小管性蛋白尿，其特点为","o":["尿蛋白常以白蛋白增多为主","尿蛋白以小分子量蛋白如β2-微球蛋白为主","尿中常出现大分子蛋白如IgG","尿蛋白常＞2g/24h","尿中免疫球蛋白的轻链显著增高"],"a":1,"e":"肾小管重吸收功能受损时，β2-微球蛋白等小分子蛋白从尿中排出增多，尿蛋白定量常＜2g/24h。肾小球性蛋白尿则以白蛋白等中高分子蛋白为主。"},{"q":"患者，男，72岁，处于慢性阻塞性肺疾病急性加重期。患者通过面罩吸氧，2L/min，动脉血气测量为pH 7、44，PaCO2 54mmHg，HCO3－ 36mEq/L，PaO2 60mmHg。此时患者处于","o":["呼吸性酸中毒和低氧血症代偿期","呼吸性碱中毒失代偿期","代谢性酸中毒部分代偿期","代谢性碱中毒部分代偿期","抽取的是静脉血"],"a":0,"e":"二氧化碳分压升高、碳酸氢根代偿性增高而pH处于正常高限，氧分压60mmHg，符合呼吸性酸中毒代偿期伴低氧血症。常见于慢阻肺急性加重。"},{"q":"患者，女，42岁，进食后突发右上腹痛、恶心呕吐，伴寒战、发热。查体：巩膜黄染，心肺听诊正常，腹软，右上腹压痛，无反跳痛，肝脾未触及。最可能的诊断是","o":["急性胃肠炎","肝脓肿","胆总管结石","幽门梗阻","急性出血坏死性肠炎"],"a":2,"e":"进食后右上腹绞痛、寒战高热伴黄疸，构成夏科三联征，提示胆总管结石合并胆道感染。腹软且无反跳痛，说明尚未形成弥漫性腹膜炎。"},{"q":"患者，男，65岁。入院后查胸部X线示右侧中等量的胸腔积液，此时查体可发现以下体征，除了","o":["右侧呼吸运动减弱，心尖冲动左移","右侧肋间隙饱满","气管右移","右侧触觉语颤减弱","右侧可闻及支气管呼吸音"],"a":2,"e":"中等量胸腔积液时气管移向健侧即左侧，故气管右移不符合。患侧胸廓饱满、呼吸运动与语颤减弱、叩诊浊音及积液上方支气管呼吸音均可出现。"},{"q":"患者，男，50岁。呼吸困难，颈静脉怒张，心界明显向两侧扩大，平卧位时第2、3肋间心界增宽，心尖冲动减弱，心音低钝，胸骨左缘3、4肋间有舒张早期额外心音，肝大，腹水征（＋）。最可能的诊断是","o":["肝硬化","心肌病","冠心病","心包积液","缩窄性心包炎"],"a":3,"e":"心界向两侧扩大且随体位改变、心音低钝、颈静脉怒张及肝大腹水，为大量心包积液。卧位时心底部浊音界增宽是其特征，缩窄性心包炎则无此改变。"},{"q":"患者，男，60岁。皮肤巩膜黄染，肝功能检查提示胆汁淤积性黄疸。B超：胆囊肿大，胆总管及肝内胆管扩张，但未见结石。查粪便隐血试验反复阳性。为明确诊断，首选的辅助检查是","o":["X线胃肠钡餐造影","纤维结肠镜检查","急诊胃镜检查","逆行胰胆管造影","磁共振腹部检查"],"a":3,"e":"胆囊肿大、胆管扩张而无结石，粪便隐血反复阳性，提示壶腹周围肿瘤所致梗阻。逆行胰胆管造影可直接观察壶腹部并显示梗阻部位，兼具诊断与治疗作用。"},{"q":"患者，男，23岁。排尿不适、尿道口流脓3天就诊，有不洁性史，临床怀疑淋病。关于淋病的病原体实验室检查错误的是","o":["分离培养具有很高的特异性，是诊断的“金标准”","直接镜检发现革兰阴性双球菌可确诊","PCR检查敏感性高，有利于早期快速确诊，但易出现假阳性","血清学试验结果需结合其他方法加以证实","培养阴性不能排除淋病"],"a":1,"e":"尿道分泌物涂片见革兰阴性双球菌仅为初步诊断依据，确诊须靠分离培养或核酸检测。女性宫颈标本杂菌多，直接镜检的可靠性更低。"},{"q":"患者，女，45岁。近日反复发生鼻出血，出血量不大，查体可见皮肤紫癜，以双下肢为著。以下哪项检查结果不可能出现","o":["BT延长","束臂试验阳性","vWD:Ag增高","血小板计数正常","PT、APTT正常"],"a":2,"e":"反复鼻出血、皮肤紫癜而血小板计数及PT、APTT正常，提示血管性血友病，其血管性血友病因子抗原应减低而非增高。BT延长与束臂试验阳性符合血管及血小板功能异常。"},{"q":"患者，女，23岁，淋雨后出现高热、寒战、咳嗽、咳痰及右侧下胸痛。查体最可能出现的体征是","o":["语音共振减弱","语音震颤减弱","叩诊呈过清音","右下肺可闻及支气管呼吸音","可闻及干啰音"],"a":3,"e":"淋雨后高热寒战、咳嗽咳痰伴下胸痛，为大叶性肺炎实变期，实变肺组织传音良好，可闻及支气管呼吸音，同时语颤增强、叩诊呈浊音。"},{"q":"患者，男，30岁。发热2天，上厕所时昏倒在地，急测血压37/0mmHg，面色苍白，脉搏细速，医院诊断为流行性出血热休克期。患者产生休克最主要的原因是","o":["小血管通透性增加，血浆外渗，血容量减少","水电解质平衡失调","内脏大出血","继发细菌感染","小动脉痉挛"],"a":0,"e":"流行性出血热早期休克以血管壁损伤、通透性增高致血浆大量外渗、血容量骤减为主，属分布性休克。其与失血性休克的发生机制不同。"},{"q":"患者，男，60岁，右上腹疼痛伴黄疸3个月余。超声检查肝脏多发性散在性光团，AFP（－）。诊断继发性肝癌，其诊断的关键是","o":["肝穿刺","找出原发病灶","CT检查","MRI检查","肝血管造影"],"a":1,"e":"继发性肝癌为转移性肿瘤，肝内多发散在光团而甲胎蛋白阴性，确诊关键在于寻获肝外原发灶。肝穿刺、CT及血管造影只能协助定位，不能确定肿瘤来源。"},{"q":"某男性患者，规律性上腹痛20年，曾做胃镜诊断为十二指肠球部溃疡。最近1周来规律性上腹痛，排黑便。对于该患者，“规律性上腹痛20年”应为","o":["既往史","现病史","系统回顾","个人史","家族史"],"a":1,"e":"现病史须记录主要症状的发生、发展及演变全过程，既往20年的规律性上腹痛与本次黑便同属一个疾病过程，故应归入现病史而非既往史。"},{"q":"患者近3日出现腹痛、便秘，无排气，伴有恶心、呕吐，行立位腹平片可见液气平面，该患者最可能罹患的疾病是","o":["肠梗阻","慢性肠炎","急性肠炎","急性胃炎","慢性胃炎"],"a":0,"e":"腹痛、呕吐、停止排气排便，立位腹平片见液气平面，为肠梗阻的典型表现。液气平面由肠腔内气体与液体分层形成，是机械性梗阻的重要征象。"},{"q":"患者，男，75岁。咳嗽、咳痰、喘息30余年，5年来间断加重，伴有双下肢水肿。1周来咳喘并下肢水肿加重伴有嗜睡入院。以下检查对诊断具有重要意义的是","o":["MRI检查","心电图","脑电图","血气分析","痰培养"],"a":3,"e":"慢阻肺病人咳喘加重伴嗜睡，提示二氧化碳潴留及肺性脑病。动脉血气可直接测定氧分压、二氧化碳分压及pH，判断呼吸衰竭类型与酸碱失衡，对诊断意义最大。"},{"q":"患者，男，59岁，反复反酸、上腹痛10余年，每次持续1个月左右，未系统治疗。近半年，持续腹痛不缓解，无反酸，伴头晕、乏力，消瘦，低热。查体：贫血貌，剑下压痛（＋），未触及异常包块，肠鸣音正常。该患者最可能的诊断是","o":["胆汁反流性胃炎","萎缩性胃炎","胃溃疡","胃癌","十二指肠溃疡"],"a":3,"e":"中老年长期规律性上腹痛近期转为持续不缓解，伴消瘦、贫血及低热，应高度警惕胃癌。疼痛节律消失与全身消耗是溃疡恶变的重要提示。"},{"q":"患者，女，28岁，于心尖部听到舒张中、晚期低调的隆隆样杂音，较局限，并有S1亢进，于S2稍后可听到一短促、高调清脆的拍击样声音，此音为","o":["病理性S3","病理性S4","开瓣音","心包叩击音","重叠奔马律"],"a":2,"e":"心尖区舒张中晚期隆隆样杂音伴第一心音亢进，第二心音后出现短促清脆的拍击样音，为二尖瓣狭窄的开瓣音。其产生于舒张早期二尖瓣开放突然受阻，提示瓣膜弹性尚好。"},{"q":"患者，男，82岁，喘憋1周，加重1天。查体：心率56次/min，呼吸20次/min，血压137/64mmHg。既往有冠状动脉粥样硬化性心脏病，高血压。心电图诊断正确的是","o":["窦性心动过缓，U波明显","心房颤动，交界区逸搏","心房扑动，U波明显","心房颤动，U波明显","心房颤动，3度房室传导阻滞，交界区逸搏"],"a":4,"e":"心房颤动时R-R间期绝对不齐，一旦心室律转为缓慢而规则，提示三度房室传导阻滞伴交界区逸搏。逸搏心律QRS波形态正常，频率多为40～60次/分。"},{"q":"患者，女，30岁。近2个月盘状红斑，辅助检查提示抗核抗体阳性，抗sm抗体阳性，抗双链DNA阳性。最可能的诊断是","o":["类风湿性关节炎","骨关节炎","系统性红斑狼疮","干燥综合征","感染性关节炎"],"a":2,"e":"盘状红斑伴抗核抗体、抗Sm抗体及抗双链DNA抗体阳性，符合系统性红斑狼疮。抗Sm抗体特异性高，抗双链DNA抗体与疾病活动度相关。"},{"q":"老年男性，78岁，胸痛24小时，下列哪项心电图改变提示急诊介入治疗指征","o":["V2～V5QS型","新发左束支传导阻滞","V1～V5T波深大倒置","V1～V3ST段抬高0.3mv","V1～V4ST段压低0.2mv"],"a":1,"e":"胸痛24小时出现新发左束支传导阻滞，属急性心肌梗死等危症，应按ST段抬高型心肌梗死处理行急诊介入治疗。新发左束支阻滞可掩盖ST段改变。"},{"q":"患者，女，78岁，起搏器植入术后8年。根据以下心电图，最可能的诊断是","o":["感知异常","起搏异常","感知及起搏均异常","正常起搏器功能伴室性期前收缩","急性心肌梗死"],"a":1,"e":"官方题库缺失图片"},{"q":"患者，男，66岁，因头晕半年来诊。查体：血压180/95mmHg，心界扩大，未及杂音。临床诊断原发性高血压，则下列体征最可能出现的是","o":["奇脉","Duroziez双重杂音","烧瓶心","P2增强","靴形心"],"a":4,"e":"长期高血压致左心室肥厚扩大，心浊音界向左下扩大、心腰加深，呈靴形心。主动脉瓣关闭不全亦呈靴形心，但伴舒张期叹气样杂音。"},{"q":"一患者受凉后咳嗽、高热、咯铁锈色痰，胸痛，随呼吸运动而加重，屏住呼吸时减轻。胸片示右肺下野外带近胸膜处均匀一致大片状影。此患者在听诊时最易出现的体征为","o":["羊鸣音","硬币叩击征","胸膜摩擦音","捻发音","哨笛音"],"a":2,"e":"累及胸膜的大叶性肺炎使胸膜表面粗糙，呼吸时脏、壁胸膜摩擦产生胸膜摩擦音，屏气时消失。胸痛随呼吸加重、屏气减轻亦提示胸膜受累。"},{"q":"患儿，女，2岁，因出生1个月感冒发现心脏杂音来诊。查体：胸骨左缘2肋间闻及3级柔和吹风样收缩期杂音，伴P2增强，S2分裂且不受呼吸影响。最可能的诊断是","o":["S2通常分裂","肺动脉瓣狭窄","S2生理性分裂和生理性杂音","房间隔缺损","S2反常分裂"],"a":3,"e":"胸骨左缘第2肋间收缩期吹风样杂音伴肺动脉瓣区第二心音亢进及固定分裂，为房间隔缺损的典型体征。左向右分流使右心容量负荷增加，肺动脉瓣关闭延迟且不受呼吸影响。"},{"q":"患者，女，50岁。突发眩晕伴呕吐，不能睁眼，伴听力下降，无视物模糊，无头痛。查体：BP 120/70mmHg，可见眼球水平方向震颤，HR 70次/min，鼻窦无压痛，全腹无压痛。血常规正常，腹部B超未见异常。可能的诊断是","o":["青光眼","脑肿瘤","耳石症","鼻窦炎","急性胆囊炎"],"a":2,"e":"头部位置变动诱发短暂眩晕伴水平眼震，无耳鸣及听力下降，为良性阵发性位置性眩晕即耳石症。前庭神经元炎眩晕持续数天，无位置诱发特点。"},{"q":"患者，女，24岁，发热1天后出现肉眼血尿，无尿频、尿急、尿痛。尿常规：尿蛋白（＋），红细胞30～40个/HPF，白细胞10～20个/HPF。为明确诊断，应进行的检查是","o":["尿蛋白定量","膀胱镜","肾盂造影","尿细菌培养","血常规检查"],"a":3,"e":"发热后出现肉眼血尿伴白细胞尿而无膀胱刺激征，应首先排除尿路感染，尿细菌培养可明确病原。尿蛋白定量与影像学检查用于评估肾损害程度。"},{"q":"青春期女性，自月经来潮，经量明显多于同龄人，幼时常有皮肤黏膜出血表现，检查发现血小板计数正常，vWD:Ag减低，该患者最可能的诊断是","o":["血友病A","血友病B","血友病C","血管性血友病","以上均不是"],"a":3,"e":"自幼皮肤黏膜出血、月经量多而血小板计数正常、血管性血友病因子抗原减低，符合血管性血友病。血友病A、B为凝血因子缺乏，以男性为主，其抗原不降低。"},{"q":"患者，男，45岁。便秘1年，一直服用含硫药物，发绀持续数月。当血中硫化血红蛋白超过（ ）时，可引起皮肤黏膜青紫","o":["1g/L","3g/L","5g/L","30g/L","50g/L"],"a":2,"e":"血中硫化血红蛋白达5g/L即可出现发绀，其发绀持续时间长、血液呈蓝褐色。本病多为获得性，常以便秘或服用含硫药物为诱因。"},{"q":"患者，男，54岁。突发抽搐8小时。查体：四肢肌肉呈持续性强直性痉挛，肌肉压痛剧烈。该患者最可能的诊断是","o":["癫痫","高血压脑病","蛛网膜下腔出血","破伤风","颅内占位"],"a":3,"e":"四肢肌肉持续性强直痉挛伴剧烈肌肉疼痛为破伤风所致，毒素作用于中枢使肌张力显著增高。典型者尚有牙关紧闭、苦笑面容及角弓反张。"},{"q":"患者，男，18岁，间断活动后胸痛来诊，入室心电图如下所示，进一步问诊及查体应注意包括如下方面，除了","o":["猝死家族史","既往用药史","有无晕厥史","既往心电图","听诊有无心脏杂音"],"a":1,"e":"官方题库缺失图片"},{"q":"患者，男，70岁。因头晕胸痛半月来诊，既往有10年高血压病史。查体血压160/75mmHg，心率102次/min，S1增强，心界左侧扩大，伴抬举样搏动。与该患者S1增强无关的是","o":["心室肥厚收缩有力","心动过速","左心室充盈不足","二尖瓣狭窄","舒张期变短"],"a":3,"e":"该患者第一心音增强系左心室肥厚收缩有力、心率快使舒张期缩短及左室充盈不足所致。二尖瓣狭窄虽可致第一心音亢进，但本例无此病变，与其无关。"},{"q":"患者，女，67岁。活动后心悸、气短3年，有慢性支气管炎病史10年。查体：心脏听诊发现心率127次/min，心律不齐。心电图P波消失代之f波，心室律绝对不规律，QRS波群形态正常。该患者心律不齐最可能的诊断是","o":["室性期前收缩","心房颤动","阵发性室性心动过速","阵发性室上性心动过速","二度Ⅰ型房室传导阻滞"],"a":1,"e":"P波消失代以f波、心室律绝对不规则而QRS波形态正常，为心房颤动的典型心电图。高龄及慢性支气管炎所致心房结构改变是其常见诱因。"},{"q":"患者，24岁，女性。消瘦、乏力半年，心慌、手抖1月就诊。查体：T 36.4℃，P 99次/min，R 21次/min，Bp 140/62mmHg，甲状腺激素增高。该患者不大可能出现的体征是","o":["奇脉","水冲脉","Duroziez双重杂音","枪击音","毛细血管搏动征"],"a":0,"e":"甲状腺功能亢进呈高动力循环、脉压增大，可出现水冲脉、枪击音、Duroziez双重杂音及毛细血管搏动征。奇脉见于心脏压塞、缩窄性心包炎及严重哮喘。"},{"q":"下列哪位患者最可能诊断为先天性心脏病，动脉导管未闭","o":["患儿，男，6岁，胸骨左缘2肋间3级粗糙吹风样杂音，伴P2增强，S2固定分裂","患者，女，3岁，胸骨左缘2肋间闻及连续性粗糙响亮机器样杂音，伴震颤","患者，38岁，胸骨左缘3/4肋间闻及舒张期哈气样递减杂音","患儿，男，1岁，胸骨左缘3/4肋间隙闻及粗糙响亮的4级全收缩期杂音伴震颤","患者，男，27岁，胸骨右缘2肋间粗糙喷射性收缩期递增递减性杂音伴震颤"],"a":1,"e":"胸骨左缘第2肋间连续性粗糙响亮的机器样杂音伴震颤，是动脉导管未闭的特征。杂音持续于收缩与舒张期而不中断，并掩盖第二心音。"},{"q":"患者突感呼吸困难，气喘、胸闷。对于确诊支气管哮喘最有意义的是","o":["气管移位","双肺叩诊呈过清音","两肺有干啰音","肺肝界下移","心界缩小"],"a":2,"e":"支气管哮喘发作时气道广泛痉挛狭窄，双肺满布干啰音即哮鸣音，呼气相更明显。过清音、肺肝界下移及心界缩小属肺气肿体征，诊断特异性不及干啰音。"},{"q":"患者，女，32岁。阵发性心悸3个月。发作时心电图示：心室率240次/分，Ⅱ、Ⅲ、aVF导联P波倒置，QRS波群正常，并与P波保持固定关系。预防室上性心动过速最有效的方法是","o":["口服维拉帕米","口服胺碘酮","口服地高辛","射频消融术","口服美托洛尔"],"a":3,"e":"阵发性室上速由房室结双径路或旁路折返引起，射频消融可阻断折返环而根治，是最有效的预防方法。药物只能减少发作，不能消除病灶。"},{"q":"患者，女，50岁，糖尿病3年。口服降糖药治疗，血糖控制良好。那么患者的空腹血糖范围应是","o":["3.3～3.9mmol/L","3.9～6.1mmol/L","6.1～7.0mmol/L","7.0～7.8mmol/L","7.8～8.4mmol/L"],"a":1,"e":"成人空腹血浆葡萄糖参考区间为3.9～6.1mmol/L，血糖控制良好者应处于此范围。低于3.9mmol/L即诊断为低血糖。"},{"q":"患者，男，32岁，上腹胀痛，伴恶心、呕吐大量隔宿食物，呕吐后腹胀痛减轻，最可能的诊断是","o":["青光眼","急性胃炎","幽门梗阻","癔症","急性胰腺炎"],"a":2,"e":"上腹胀痛伴呕吐大量隔夜宿食、吐后腹胀减轻，是幽门梗阻的典型表现。长期梗阻致胃扩张与潴留，可见胃型、振水音及消瘦脱水。"},{"q":"患者，男，52岁，以“间断胸痛5年，加重2小时”收入院。平素体力活动、锻炼等无明显胸闷、胸痛，多于凌晨睡眠时心前区不适、胸痛，10余分钟可自行缓解。今日凌晨再次发作，持续半小时未缓解。根据心电图最可能的诊断是","o":["胃食管反流","急性下壁心梗","心包积液","变异型心绞痛","主动脉夹层"],"a":3,"e":"静息及凌晨发作、持续时间较长的心前区疼痛，结合心电图ST段暂时性抬高，符合变异型心绞痛。其由冠状动脉痉挛引起，ST段持续抬高则提示心肌梗死。"},{"q":"一瘫痪患者入院时查体发现其左侧肢体肌力3级，左侧巴宾斯基征阳性，左侧中枢性面瘫。考虑患者损伤以下哪个部位","o":["颈段脊髓","左侧基底节区","右侧基底节区","左侧小脑","脑桥"],"a":2,"e":"左侧偏瘫、左侧中枢性面瘫及左侧巴宾斯基征阳性，为右侧上运动神经元损害，病变定位于右侧基底节区。颈髓病变表现为四肢瘫且不伴面瘫。"},{"q":"患者，女，26岁，腹痛、腹泻入院。粪便呈果酱样便，镜检粪便中出现夏科-莱登结晶，考虑该患者为","o":["细菌性痢疾","阿米巴痢疾","溃疡性结肠炎","直肠息肉","重症霍乱"],"a":1,"e":"果酱样便伴夏科-莱登结晶是阿米巴痢疾的典型粪便改变。溶组织内阿米巴侵袭肠壁形成烧瓶样溃疡，镜检可找到滋养体。"},{"q":"患者，女，20岁。突然发冷发热，体温达39.0℃，面色潮红，伴右胸呼吸运动减弱，可听到管状呼吸音。其诊断首先考虑","o":["胸腔积液","大叶性肺炎","肺梗死","肺结核","肺癌"],"a":1,"e":"青年突然寒战高热、患侧呼吸运动减弱并闻及管状呼吸音，符合大叶性肺炎实变期。肺炎链球菌是最常见病原，可伴胸痛及铁锈色痰。"},{"q":"患者，男，48岁。“双侧股骨干骨折2小时”收入住院。入院查体：体温36.5℃，脉搏细弱，血压60/40mmHg，四肢冰冷，并出现发绀、无尿。该患者出现的发绀是","o":["肺性发绀","心性混合性发绀","淤血性周围性发绀","缺血性周围性发绀","混合性发绀"],"a":3,"e":"股骨干骨折后血压骤降、四肢冰冷伴发绀，系休克致心排血量减少、末梢灌注不足，属缺血性周围性发绀。按摩或加温使皮肤转暖后发绀可减轻。"},{"q":"患者，男，70岁。已确诊为冠心病，近日出现夜间呼吸困难，咯粉红色泡沫样痰。查体：BP 120/90mmHg，心率104次/min，律齐，心界向左下扩大，心音低钝。还可出现的体征是","o":["水冲脉","奇脉","脱落脉","交替脉","短绌脉"],"a":3,"e":"急性左心衰竭肺水肿时左心室收缩力强弱交替，出现节律规则而脉搏强弱交替的交替脉，是左心衰竭的重要体征。奇脉见于心脏压塞，短绌脉见于心房颤动。"},{"q":"患者，男，30岁，上腹部规律性疼痛反复发作10年，加重1周，呕血、黑便2天。最可能的诊断是","o":["出血性胃炎","消化性溃疡出血","胃癌出血","食管-胃底静脉曲张破裂出血","胆道出血"],"a":1,"e":"长期规律性上腹痛近期加重并出现呕血、黑便，符合消化性溃疡出血，出血后腹痛常减轻。食管胃底静脉曲张破裂多有肝硬化病史，出血量大且凶险。"},{"q":"患者，26岁。近1个月来低热、盗汗，伴咳嗽，痰中带血丝。应首先考虑的是","o":["肺结核","支气管扩张","肺癌","风湿性心脏病二尖瓣狭窄","急性肺水肿"],"a":0,"e":"在我国咯血的首要病因为肺结核，浸润型与空洞型肺结核多表现为痰中带血；午后低热、盗汗、乏力等结核毒血症状是与其他咯血病因鉴别的关键。"},{"q":"患者，女，72岁。心慌3天，突发头痛，右侧面瘫，伴有右侧肢体活动不灵1天。既往房颤病史20年。复查心电图显示心率54次/min，窦性节律。患者最可能发生的是","o":["蛛网膜下腔出血","急性脑栓塞","急性脑膜炎","高血压脑病","脑肿瘤"],"a":1,"e":"长期心房颤动使左心房血流淤滞形成附壁血栓，脱落入脑动脉即致脑栓塞，表现为突发偏瘫、面瘫而无先兆；蛛网膜下腔出血以剧烈头痛和脑膜刺激征为主。"},{"q":"患者，男，28岁，因尿频、尿急、尿痛4个月、加重伴尿失禁1周就诊。尿常规检查提示白细胞（＋＋），尿潜血（＋＋＋），多种抗生素治疗无明显缓解。该患者的诊断最有可能是","o":["急性膀胱炎","泌尿系结核","间质性膀胱炎","慢性膀胱炎","腺性膀胱炎"],"a":1,"e":"慢性膀胱刺激征、脓尿与血尿而普通抗菌治疗无效，是泌尿系结核的特点；结核肉芽肿与瘢痕挛缩使膀胱容量缩小，晚期出现尿失禁，尿沉渣找抗酸杆菌可确诊。"},{"q":"患者，男，69岁，检测发现单克隆Ig明显升高。M蛋白增高所导致的疾病，不包括下列哪种","o":["重链病","轻链病","原发性巨球蛋白血症","真性红细胞增多症","多发性骨髓瘤"],"a":3,"e":"M蛋白为单克隆浆细胞异常增殖的产物，见于多发性骨髓瘤、原发性巨球蛋白血症、重链病与轻链病；真性红细胞增多症属骨髓增殖性肿瘤，无单克隆免疫球蛋白增多。"},{"q":"患者，男，59岁。阴部肿胀、疼痛3个月。查体：精索部位呈串珠样肿胀。该患者最可能的诊断是","o":["输精管结核","精索静脉曲张","腹股沟斜疝","鞘膜积液","睾丸癌"],"a":0,"e":"正常精索为柔软条索状、无压痛；呈串珠样肿胀是输精管结核的特征性体征，由输精管多发结核结节与纤维化狭窄交替形成。"},{"q":"患者，男，34岁，因预计综合征行射频消融术，术后2天心电图示delta波消失，但多个导联T波仍倒置，其原因可能为","o":["心肌受损","射频消融未成功","电张调整性T波改变","急性冠脉综合征","心血管神经症"],"a":2,"e":"预激综合征射频消融阻断旁路后，心室除极顺序改变可引起T波倒置，称电张调整性T波改变，属功能性改变，多可自行恢复，不提示心肌损伤。"},{"q":"患者，女，35岁。有糖尿病家族史。实验室检查：空腹血糖6.8mmol/L。为确诊糖尿病，最有意义的检查是","o":["重复测空腹血糖","测餐后2h血糖","多次测任意血糖","口服葡萄糖耐量试验","糖化血红蛋白"],"a":3,"e":"空腹血糖6.8mmol/L属空腹血糖调节受损，需行75g口服葡萄糖耐量试验，以服糖后2小时血糖≥11.1mmol/L作为糖尿病诊断依据；糖化血红蛋白只反映近2～3个月的平均血糖。"},{"q":"患者，女，20岁。因进行性呼吸困难3个月来诊。查体发现BP 90/70mmHg，心界双侧扩大，随体位改变，心率120次/min，律齐，心音低弱遥远，无病理性杂音。患者不可能出现","o":["水冲脉","颈静脉怒张","奇脉","肝大","移动性浊音"],"a":0,"e":"大量心包积液时心室舒张充盈受限、每搏量下降，脉压减小并出现奇脉，不会出现水冲脉；颈静脉怒张、肝大与移动性浊音均为体循环淤血的表现。"},{"q":"患者，男，67岁。长期吸烟，有重度高血压、冠心病及糖尿病病史，未服用药物治疗。生气后突发剧烈头痛，继而意识丧失，伴有呕血，起病前无发热症状。其最可能的诊断是","o":["高血压脑病","急性脑炎","颅内肿瘤","急性脑出血","急性脑梗死"],"a":3,"e":"长期未控制的高血压在情绪激动后突发剧烈头痛并迅速昏迷，是基底节区脑出血的典型经过；呕吐咖啡样物为并发应激性溃疡所致，起病前不发热可与感染鉴别。"},{"q":"患者，男，20岁。单杠运动后突发右侧胸痛，伴咳嗽时加剧，渐感呼吸困难。最可能是","o":["自发性气胸","心绞痛","肋间神经痛","肋骨骨折","肺栓塞"],"a":0,"e":"青壮年剧烈运动时胸膜下肺大疱破裂，气体进入胸膜腔形成自发性气胸，表现为突发一侧撕裂样胸痛、继之呼吸困难，患侧呼吸音减弱。"},{"q":"患者，男，49岁，规律性夜间腹痛5年，近1个月疼痛节律性消失，变为餐后腹痛伴呕吐，吐出大量隔夜宿食，应考虑并发","o":["大出血","慢性穿孔","急性穿孔","幽门梗阻","溃疡癌变"],"a":3,"e":"溃疡疼痛的节律性消失、转为餐后呕吐大量隔夜宿食，是幽门梗阻的表现，由溃疡瘢痕收缩或炎性水肿致幽门通过障碍、胃潴留所致。"},{"q":"患者，男，32岁，在其左边第3肋间可闻及典型的早期舒张期杂音，被认为具有主动脉瓣关闭不全。以下哪项支持主动脉瓣关闭不全的诊断，可以将其与肺动脉瓣关闭不全的早期舒张期杂音（Graham Stell杂音）区分开来","o":["左方第2肋间杂音最响亮","左心室长大","杂音在吸气末最明显","血压无变化","第一心音增强"],"a":1,"e":"主动脉瓣关闭不全的反流使左心室舒张末期容量增加，出现代偿性左心室增大；Graham Steell杂音由肺动脉扩张引起，于吸气末增强并常伴P2亢进。"},{"q":"患儿，女，1岁。前额左右突出，头顶平坦呈方形，夜间易惊醒，出汗多。该患儿最可能患的疾病是","o":["小儿佝偻病","变形性骨炎","脑积水","肢端肥大症","Marfan综合征"],"a":0,"e":"方颅表现为前额左右突出、头顶平坦呈方形，系佝偻病骨样组织堆积于额骨与顶骨所致；巨颅见于脑积水，伴落日现象与头皮静脉怒张。"},{"q":"患者，男，40岁。10年前有风湿性关节炎史。近2周来有心悸、气促，伴夜间阵发性呼吸困难。查体：心尖部第一心音减弱，可闻及4/6级全收缩期吹风样杂音和舒张期隆隆样杂音，最可能是","o":["风湿性心脏病，二尖瓣狭窄伴关闭不全","风湿性心脏病，二尖瓣狭窄伴肺动脉瓣狭窄","风湿性心脏病，二尖瓣狭窄伴主动脉瓣狭窄","风湿性心脏病，二尖瓣狭窄伴主动脉瓣关闭不全","风湿性心脏病，二尖瓣狭窄伴三尖瓣狭窄"],"a":0,"e":"心尖区舒张期隆隆样杂音为二尖瓣狭窄的特征，4/6级全收缩期吹风样杂音提示二尖瓣关闭不全；第一心音减弱说明瓣叶增厚、活动受限。"},{"q":"患者，男，40岁，主诉乏力、酱油色尿2周。2周前曾因“感冒”服用对乙酰氨基酚类药物，期间曾发现尿色呈酱油色。查体见贫血外貌，巩膜轻度黄染。血常规示Hb 65g/L，WBC 18×109/L，PLT 104×109/L。对其诊断最有价值的检测项目是","o":["抗核抗体检测","过敏原皮肤试验","Coombs实验","血清免疫复合物测定","骨髓穿刺"],"a":2,"e":"服药后出现酱油色尿伴贫血、巩膜黄染，提示免疫性溶血；Coombs试验阳性证实红细胞表面结合有不完全抗体，是自身免疫性溶血的直接证据。"},{"q":"患者，男，38岁。不明原因发热、胸痛、咳嗽2天。下列哪项体征有助于肺炎与胸腔积液的鉴别诊断","o":["语颤增强","呼吸急促","呼吸音减低","叩诊为浊音","捻发音"],"a":0,"e":"肺实变时肺泡含气减少、声波传导增强，故语颤增强；胸腔积液将肺组织与胸壁隔开，语颤与语音共振均减弱，是二者鉴别的关键体征。"},{"q":"患者，男，50岁。反复乏力、消瘦，食欲缺乏10年。查体：肝脾未见异常。实验室检查：ALP升高，HBsAg（＋），HBeAg（＋）。保肝治疗后好转。为明确有无肝硬化，首选的实验室检查项目是","o":["GPT","GOT","AFP","MAO","R-GT"],"a":3,"e":"血清MAO活性与体内结缔组织增生程度正相关，80%以上重症肝硬化及伴肝硬化的肝癌患者升高，故用于判断有无肝硬化及纤维化程度；急性肝炎时多正常。"},{"q":"患者，女，42岁，诊断类风湿性关节炎10年。近1个月来乏力，烦渴，伴有腰痛。查尿常规：pH 6.0，WBC 4个/HPF，RBC 1个/HPF，蛋白（-）。肾功能：血肌酐94μmol/L，尿素氮7.2mmol/L。电解质：钙2.0mmol/L，钠138mmol/L，钾3.2mmol/L，氯108mmol/L，HCO3-27mmol/L。最可能的诊断是","o":["泌尿系感染","Ⅰ型肾小管酸中毒","Ⅱ型肾小管酸中毒","Fanconi综合征","Bartter综合征"],"a":1,"e":"类风湿关节炎可继发远端肾小管酸中毒，表现为尿pH不能降至5.5以下、低钾、低钙与肾钙化；Ⅱ型者尿pH可＜5.5，并伴尿糖及尿氨基酸阳性。"},{"q":"患者，女，23岁。因呼吸困难、头晕就诊，其他症状包括指尖和口周围的刺痛和麻木，动脉血气：pH 7.54，PaCO2 22mmHg，HCO3－ 22mEq/L，PaO2 115mmHg。该患者可能发生了","o":["呼吸性碱中毒失代偿期","抽取的是静脉血","代谢性酸中毒部分代偿期","呼吸性酸中毒和低氧血症代偿期","代谢性碱中毒部分代偿期"],"a":0,"e":"PaCO2降至22mmHg使pH升至7.54，超出代偿所能维持的范围，HCO3-尚在正常低限，符合急性呼吸性碱中毒；过度通气伴口周及指尖麻木为其典型表现。"},{"q":"患者，女，40岁，发热牙龈出血伴月经量增多2周。查体：体温39、2℃，贫血貌，浅表淋巴结未及，胸骨压痛，肝肋下1cm，脾肋下2cm。RBC 3.0×1012/L，Hb 72g/L，WBC 32×109/L，BPC 28×109/L。为明确诊断，最有必要进行下列哪项检查","o":["骨髓涂片检查","肝肾功能检查","骨髓活检组织学检查","X线检查","血培养"],"a":0,"e":"胸骨压痛、肝脾肿大伴白细胞显著增高、贫血与血小板减少提示急性白血病，骨髓涂片细胞形态学检查是确诊及分型的首选方法。"},{"q":"患者，男，67岁。外出旅游中突发高热，寒战，伴腰痛、尿急、尿痛。最先考虑的检查是","o":["尿常规","尿细菌培养","泌尿系超声","静脉肾盂造影","肾功能"],"a":0,"e":"高热寒战、腰痛伴膀胱刺激征提示急性肾盂肾炎，首选尿常规加镜检，可见大量白细胞或白细胞管型，是筛选与初步定位最简便的检查。"},{"q":"患者，男，56岁，诉咳嗽3个月、咯血2天。既往多年吸烟史。右锁骨上窝触及1枚1cm×1cm质硬淋巴结。胸片提示右肺门包块。下一步最佳检查是","o":["胸部CT","胸部增强CT","胸部磁共振","纤维支气管镜检查及活检","同位素骨扫描"],"a":3,"e":"中心型肺部肿块伴咯血及锁骨上淋巴结肿大，纤维支气管镜可直接窥视病变并取活检获得病理诊断，是明确组织学类型的首选检查。"},{"q":"患儿，男，5个月，出生时诊断为法洛四联症。近2天常于哭闹时突发四肢抽搐，青紫加重，神志不清，呼吸急促，持续时间约1～2min。首先考虑为","o":["脑栓塞","心力衰竭","缺氧发作","休克","脑脓肿"],"a":2,"e":"法洛四联症患儿哭闹时右室流出道痉挛、右向左分流骤增，出现突发青紫加重、呼吸急促甚至抽搐，称缺氧发作，重者意识丧失。"},{"q":"患者，男，45岁，自述头昏。体检测血压，上肢血压为21、3/13、3kPa（1kPa≈7、5mmHg），下肢血压为18、7/13、3kPa。该患者最可能的诊断为","o":["血管闭塞性脉管炎","甲状腺功能亢进症","动脉导管未闭","主动脉缩窄","主动脉瓣关闭不全"],"a":3,"e":"上肢血压明显高于下肢是主动脉缩窄的特征，因缩窄段近端血压升高、远端灌注减少；正常人下肢血压应比上肢高20～40mmHg。"},{"q":"一老年患者，发现尿色呈鲜红色2天，每次排尿为开始尿色正常，末段尿为红色，有排尿困难，无发热和腹痛。该患者尿色呈鲜红色，最有可能为","o":["真性血尿","血红蛋白尿","卟啉尿","进食某些食物和药物引起","梗阻性黄疸"],"a":0,"e":"排尿终末段呈红色提示出血来自膀胱颈部、三角区或后尿道，尿中确有红细胞，属真性血尿；血红蛋白尿呈均匀酱油色而镜检无红细胞。"},{"q":"患者，男，15岁，乏力、面色苍白，酱油色尿，巩膜黄染，肝脾不大。外周血：RBC 3、90×1012/L，Hb 100g/L，MCV 88fl，MCHC 320g/L，WBC 4.0×109/L，PLT 100×109/L，RC 16%。最可能的诊断是","o":["缺铁性贫血","溶血性贫血","再生障碍性贫血","白血病","巨幼红细胞贫血"],"a":1,"e":"血红蛋白100g/L而网织红细胞高达16%，伴黄疸与酱油色尿，提示红细胞破坏增多、骨髓红系代偿增生，符合溶血性贫血；缺铁性贫血网织红细胞不增高。"},{"q":"60岁老年男性患者出现无症状性肉眼血尿，首先应考虑","o":["膀胱炎","膀胱结核","前列腺增生","肾结石","膀胱癌"],"a":4,"e":"60岁以上男性出现无痛性肉眼血尿，应首先考虑膀胱癌；膀胱炎与膀胱结核均伴膀胱刺激征，前列腺增生以进行性排尿困难为主。"},{"q":"患者，女，50岁。20年前曾患甲亢，行131I治疗后痊愈。近半年开始出现面色苍白、颜面水肿、皮肤干燥、注意力不集中。该患者的面容是","o":["慢性病容","贫血面容","黏液性水肿面容","肾病面容","甲状腺功能亢进面容"],"a":2,"e":"131I治疗后甲状腺组织被破坏，出现面色苍黄、颜面水肿、皮肤干燥与反应迟钝，为黏液性水肿面容；贫血面容仅有面色苍白而无颜面水肿。"},{"q":"患儿，男，5岁，玩积木玩具时突发呼吸困难，胸骨上窝、锁骨上窝和肋间隙明显凹陷。下列最有可能的疾病是","o":["室间隔缺损","肺栓塞","神经肌肉疾病","肺炎","气道阻塞"],"a":4,"e":"突发吸气性呼吸困难伴三凹征，提示上气道梗阻，婴幼儿异物吸入最多见；三凹征为吸气时胸骨上窝、锁骨上窝及肋间隙凹陷。"},{"q":"患者，男，40岁，反复饥饿时中上腹部隐痛10年，伴反酸嗳气，在进食和服制酸剂后可缓解，今晨中上腹剧痛后腹痛持续存在。为确诊疾病，应选择的检查手段是","o":["血清淀粉酶测定","癌胚抗原测定","胃镜检查","X线腹部平片","腹部超声检查"],"a":2,"e":"胃镜可直接观察溃疡的部位、大小与分期，并取活检排除恶性，是确诊消化性溃疡的首选检查；X线钡餐仅适用于不能耐受胃镜者。"},{"q":"患者，女，28岁。恶心、尿色变黄6天，体检发现巩膜中度黄染，肝肋下2cm可及，血谷丙转氨酶840U/L，总胆红素85μmol/L。最可能的诊断是","o":["急性胆道感染","病毒性肝炎","钩体病","遗传性胆道疾病","原发性胆汁性肝硬化"],"a":1,"e":"ALT升高达正常上限20倍以上、伴黄疸与肝区轻触痛，符合急性病毒性肝炎，且ALT升高比AST更明显；急性胆道感染以寒战发热、右上腹痛及白细胞增高为主。"},{"q":"患者，女，66岁，来到急诊室，有明显的肺水肿。动脉血气：pH 7.10，HCO3－ 8mEq/L，PaCO2 25mmHg，BE -20mEq/L，脉搏140/min，PaO2 40mmHg，SO2 52%。该患者可能发生了","o":["呼吸性酸中毒和低氧血症代偿期","呼吸性碱中毒失代偿期","代谢性碱中毒部分代偿期","代谢性酸中毒失代偿期和Ⅰ型呼吸衰竭","抽取的是静脉血"],"a":3,"e":"HCO3- 8mmol/L、BE -20mmol/L示重度代谢性酸中毒，pH 7.10属失代偿；PaO2 40mmHg＜60mmHg而PaCO2不升高，符合Ⅰ型呼吸衰竭。"},{"q":"患者，男，40岁。反复左上腹疼痛4年，消瘦，乏力，经常腹泻，稀水样便。大便镜检：无RBC和WBC，有较多的脂肪小滴和肌肉纤维。结肠镜：全结肠未见改变。B超：肝胆正常，胰腺回声粗糙。应首先考虑哪种疾病","o":["慢性胆囊炎","慢性结肠炎","急性胰腺炎","慢性胰腺炎","急性胆囊炎"],"a":3,"e":"反复上腹痛、消瘦伴脂肪泻，粪中见脂肪小滴与肌纤维，胰腺回声粗糙，提示胰腺外分泌功能不全，符合慢性胰腺炎；结肠病变不能解释脂肪泻。"},{"q":"一高血压病患者因口角流涎入院检查。接诊医生查体发现存在左侧中枢性面瘫。以下不是该患者临床表现的是","o":["左侧鼻唇沟浅","左侧露齿浅","左侧鼓腮漏气","左额额纹浅","不能吹口哨"],"a":3,"e":"中枢性面瘫因上半部面肌受双侧皮质脑干束支配，蹙额、皱眉不受影响，故额纹不浅；仅出现病灶对侧下半部面肌瘫痪，表现为鼻唇沟浅、鼓腮漏气。"},{"q":"患者，男，71岁，退休机械师。患者有呼吸困难、咳嗽和痰液增多的病史，有120包/年的吸烟史，5年前戒烟，现被送往ICU。检查中使用了呼吸机辅助，仍存在通气不足，肢端发绀。动脉血气：pH 7、21，PaCO2 75mmHg，HCO3－ 30mEq/L，PaO2 41mmHg。此时患者最可能发生了","o":["急性呼吸性酸中毒并发慢性呼吸性酸中毒","呼吸性碱中毒失代偿期","代谢性酸中毒部分代偿期","代谢性碱中毒部分代偿期","抽取的是静脉血"],"a":0,"e":"PaCO2 75mmHg伴pH 7.21，HCO3-升至30mmol/L已超出急性呼吸性酸中毒3～4mmol/L的代偿限度，提示在慢性CO2潴留基础上叠加急性加重。"},{"q":"患者，女，62岁，夜间看电视时出现头痛，随后恶心、呕吐胃内容物，呕吐呈喷射样，最可能的诊断为","o":["幽门梗阻","胃潴留","霍乱","脑出血","急性心肌梗死"],"a":3,"e":"头痛后出现喷射性呕吐提示颅内压增高，中老年夜间突发者以脑出血多见；幽门梗阻的呕吐为餐后迟发、含隔夜宿食，并非喷射性。"},{"q":"患者，男，82岁，喘憋1周，加重1天。查体：心率56次/min，呼吸20次/min，血压137/64mmHg。既往有冠状动脉粥样硬化性心脏病，高血压。这样的心电图比较常见下列哪种情况","o":["血钾6.0mmol/L","血钾2.1mmol/L","血钠130mmol/L","血钠160mmol/L","洋地黄中毒"],"a":4,"e":"官方题库缺失图片"},{"q":"患儿，女，2岁，在幼儿园进食后出现腹痛、血便和肾衰竭。同时进食儿童也有数人出现相同的症状，被诊断为出血性结肠炎。细菌培养只有大肠埃希菌生长，可能的病原菌是","o":["肠毒素性大肠埃希菌","肠出血性大肠埃希菌","肠致病性大肠埃希菌","肠侵袭性大肠埃希菌","肠凝聚性大肠埃希菌"],"a":1,"e":"肠出血性大肠埃希菌（O157:H7）产生志贺样毒素，引起出血性结肠炎，并可并发溶血尿毒综合征导致急性肾衰竭；集体进食后发病提示食源性暴发。"},{"q":"一年轻女性因下肢无力入院。查体发现患者上腹壁反射存在，中腹壁反射及下腹壁反射消失。推测脊髓损伤以下哪个节段","o":["胸髓第2～4节段","胸髓第6～7节段","胸髓第7～8节段","胸髓第9～10节段","胸髓第11～12节段"],"a":3,"e":"腹壁反射上、中、下部分别由胸髓7～8、9～10、11～12节段支配；上腹壁反射存在而中、下消失，提示病损位于胸髓9～10节段。"},{"q":"患者，男，68岁。突然发生寒战、高热（体温39℃）、咳嗽、咳痰，痰呈黏稠、砖红色、胶冻状。引起感染最可能的病原菌是","o":["克雷伯杆菌","流感嗜血杆菌","铜绿假单胞菌","葡萄球菌","肺炎球菌"],"a":0,"e":"砖红色胶冻样痰是肺炎克雷伯菌肺炎的特征，该菌为有荚膜的革兰阴性杆菌，好发于中老年及酗酒者，易致叶间裂下坠。"},{"q":"患者，男，40岁，患慢性乙型肝炎10余年。近2个月出现大量腹水，腹部膨隆。欲查清该患者的脾大情况，最宜选择下列哪种检查方法","o":["浅部触诊法","双手触诊法","深部滑行触诊法","深压触诊法","浮沉触诊法"],"a":4,"e":"大量腹水时深部触诊无法触及肝脾，需用浮沉（冲击）触诊法，以并拢的三指急速冲击腹壁，排开腹水后指端可感受浮起的脏器。"},{"q":"患有糖尿病的30岁男性患者因为急性呼吸困难来到急诊室，动脉血气为：pH 7.33，PaCO2 24mmHg，PaO2 111mmHg，HCO3－ 12mEq/L","o":["代谢性酸中毒部分代偿期","呼吸性碱中毒失代偿期","代谢性碱中毒部分代偿期","呼吸性酸中毒和低氧血症代偿期","抽取的是静脉血"],"a":0,"e":"HCO3- 12mmol/L明显降低、pH 7.33接近正常下限，PaCO2 24mmHg系过度通气的代偿反应，符合代谢性酸中毒部分代偿，见于糖尿病酮症酸中毒。"},{"q":"患者，男，38岁。3年前患结核性心包炎，近1～2个月呼吸困难伴腹胀、水肿。该患者最可能出现的体征是","o":["颈静脉怒张","颈静脉塌陷","颈动脉搏动增强","颈动脉搏动消失","颈部血管杂音"],"a":0,"e":"结核性心包炎后出现呼吸困难、腹胀与水肿，提示心包增厚缩窄致体循环淤血；颈静脉怒张是最早出现的体征，吸气时更明显。"},{"q":"一肺癌患者，病灶直径为4cm，距体表距离为4cm，其叩诊音应为","o":["清音","浊音","实音","浊鼓音","过清音"],"a":1,"e":"直径4cm的病灶已超过3cm的叩诊分辨限度，距体表4cm可被叩出，肺组织含气量减少故呈浊音；实音见于大面积实变或大量胸腔积液。"},{"q":"一尿毒症患者，随呼吸运动胸痛明显，在肺部听诊时，最可能出现的体征为","o":["胸语音","耳语音","羊鸣音","支气管语音","胸膜摩擦音"],"a":4,"e":"尿毒症时胸膜受尿素刺激发生纤维蛋白性炎症，表面粗糙，随呼吸产生胸膜摩擦音，吸气末或呼气初明显，屏气即消失，前下侧胸壁最易闻及。"},{"q":"患者，女，50岁。劳累后心前区疼痛2小时，休息后可自行缓解。既往高血压病史3年，未行诊治。心电图检查：V1～V3导联ST段压低。该患者危险分级所应用的生化指标为","o":["CKMB 乳酸脱氢酶","乳酸脱氢酶 肌红蛋白","肌红蛋白 AST","AST 肌钙蛋白","CKMB 肌钙蛋白"],"a":4,"e":"cTnI、cTnT与CK-MB特异度高，是急性冠脉综合征危险分层的指标；肌红蛋白升高最早但特异性差，仅用于早期排除心肌梗死。"},{"q":"患者，女，68岁，外阴瘙痒1个月。阴道分泌物发现线索细胞，考虑诊断为","o":["滴虫性阴道炎","真菌性阴道炎","细菌性阴道炎","淋菌性阴道炎","慢性宫颈炎"],"a":2,"e":"线索细胞是阴道加德纳菌等大量附着于鳞状上皮细胞表面形成的颗粒状细胞，其检出是细菌性阴道病的诊断依据，同时阴道杆菌明显减少。"},{"q":"患者，男，70岁。患高血压合并左心衰竭，长期口服ACEI类药物及利尿剂，1周前自行调整用药剂量后自觉乏力、腹胀。今日来院复查，行血电解质检查，最符合该患者目前情况的检查结果是","o":["血钾3.0mmol/L","血钠150mmol/L","血氯115mmol/L","血钙2.09mmol/L","血磷1.7mmol/L"],"a":0,"e":"长期服用排钾利尿剂并自行加量易致低钾血症，表现为乏力、腹胀与肠鸣减弱；血钾3.0mmol/L低于3.5mmol/L的参考下限，需及时补钾。"},{"q":"患者，男，60岁，主诉：血压偏高2年，近1周头晕、胸闷、心悸。患者脉压增大，应考虑","o":["主动脉瓣狭窄","主动脉瓣关闭不全","贫血","动脉硬化","心肌梗死"],"a":3,"e":"老年高血压患者脉压增大主要因大动脉粥样硬化、血管弹性减退，收缩压升高而舒张压不高；主动脉瓣关闭不全虽也致脉压增大，但伴舒张期叹气样杂音。"},{"q":"患者，男，64岁。排尿不畅1年余。直肠指检：前列腺增大，表面光滑，按压前列腺，无明显压痛。该患者最可能的诊断是","o":["正常前列腺","前列腺肥大","前列腺癌","急性前列腺炎","慢性前列腺炎"],"a":1,"e":"良性前列腺肥大时前列腺增大、表面光滑、有韧感、无压痛及结节，中央沟变浅；前列腺癌则质硬、表面有硬结节，需穿刺活检鉴别。"},{"q":"患者，男，34岁。面黄1周。查体：皮肤及巩膜黄染，心肺无异常，肝肋下2cm，轻触痛。实验室检查：ALT 300U/L。其他最可能出现的实验室检查结果是","o":["血中结合胆红素和游离胆红素均增多","尿三胆试验均阳性","粪便颜色变深","血清总胆红素升高，结合胆红素减少","血中结合胆红素显著增加，而未结合胆红素减少"],"a":0,"e":"ALT显著升高伴肝大轻触痛提示肝细胞损伤，肝细胞性黄疸时摄取、结合与排泄均障碍，血中非结合与结合胆红素同时升高，尿胆红素阳性。"},{"q":"患者，男，58岁。进行性排尿困难1年，伴无痛性肉眼血尿、尿频、夜尿增多。查体未见明显异常。尿常规示尿蛋白（-），镜检WBC 0～4个/HPF，RBC（+++）。该患者最可能的诊断是","o":["尿路感染","泌尿系结石","膀胱肿瘤","前列腺增生症","前列腺炎"],"a":2,"e":"老年人无痛性肉眼血尿是膀胱肿瘤的特点，肿瘤位于膀胱颈或体积较大时可致进行性排尿困难；尿路感染则伴白细胞增多与膀胱刺激征。"},{"q":"患者，女，45岁。双腕关节指间关节肿痛伴晨僵半年，查体示手指关节呈梭形改变。最可能的疾病是","o":["骨关节炎","类风湿关节炎","系统性红斑狼疮","代谢性骨病","痛风性关节炎"],"a":1,"e":"双手近端指间关节与腕关节对称性肿痛、晨僵超过1小时并出现梭形指，是类风湿关节炎的典型表现，源于滑膜炎致关节周围软组织肿胀。"},{"q":"患者，男，50岁，喜食肥肉。心前区阵发性疼痛2个月，活动后加重。查体：心率83次/min，律齐。心电图示ST段下移，冠脉CTA示冠脉降支80%狭窄，TG 6.8mmol/L。该患者引起冠状动脉狭窄最可能的原因是","o":["冠心病","高脂血症","高尿酸血症","糖尿病","肥胖"],"a":1,"e":"甘油三酯6.8mmol/L远高于1.70mmol/L的合适水平，高脂血症是动脉粥样硬化的主要危险因素，脂质沉积于内膜下形成斑块致管腔狭窄。"},{"q":"患者，男，35岁，经常发生无明确诱因的上腹部疼痛，左侧卧位可使疼痛减轻。查体：巩膜无黄染，全腹无肌紧张、无压痛、肝脾未触及。最可能的诊断为","o":["胃黏膜脱垂","溃疡性结肠炎","血卟啉病","胰腺癌","肠扭转"],"a":0,"e":"胃黏膜脱垂时左侧卧位可使脱垂的黏膜复位、疼痛减轻，是其特点；十二指肠壅滞症则在膝胸位或俯卧位缓解，两者体位关系不同。"},{"q":"年轻男性，发热5天，每天体温维持在39～41℃，24小时内体温波动相差不超过1℃。体检发现腹部玫瑰疹，肝脾肿大。该患者的热型是","o":["间歇热","波状热","回归热","稽留热","弛张热"],"a":3,"e":"体温持续39～41℃、24小时内波动不超过1℃，符合稽留热，见于伤寒高热期，与玫瑰疹、肝脾肿大同为伤寒的典型表现；弛张热波动常超过2℃。"},{"q":"患者，女，47岁，胆囊结石取出术后第2天，诉胸痛。床旁血气：pH 7.45，PaCO2 25mmHg，HCO3- 17mEq/L，PaO2 58mmHg。此时患者最可能发生了","o":["呼吸性碱中毒与低氧血症代偿期","呼吸性碱中毒失代偿期","代谢性碱中毒部分代偿期","呼吸性酸中毒与低氧血症代偿期","抽成了静脉血"],"a":0,"e":"PaCO2降低使pH处于正常高限，HCO3-相应下降为代偿性改变，PaO2 58mmHg＜60mmHg提示低氧血症；术后突发胸痛伴低氧需警惕肺栓塞。"},{"q":"患者，女，25岁，因“双下肢水肿半个月”入院。查BP 150/70mmHg，尿蛋白（＋＋＋），尿红细胞（＋＋），血WBC降低，血Cr 110μmol/L，Coombs试验阳性，补体降低，抗核抗体阳性，类风湿因子阳性。最可能的诊断是","o":["慢性肾小球肾炎","急性肾小球肾炎","类风湿关节炎","系统性红斑狼疮","IgA肾病"],"a":3,"e":"育龄女性出现蛋白尿、血尿伴抗核抗体阳性、补体降低及Coombs试验阳性，符合系统性红斑狼疮的多系统受累，肾脏是最常受累的器官。"},{"q":"患者，男，18岁，学校体检心电图发现异常，如下，最可能的诊断是","o":["窦性心动过缓","三度房室传导阻滞，交界区逸搏心律","窦性心律，频发交界区期前收缩","三度房室传导阻滞，室性逸搏心律","二度Ⅱ型房室传导阻滞"],"a":1,"e":"官方题库缺失图片"},{"q":"患者，男，晨起尿液呈红色，遂就诊。尿常规：尿潜血（＋＋＋），镜检发现尿中出现大量均一性红细胞，关于红细胞来源，错误的是","o":["肾脏","输尿管","膀胱","前列腺","尿道"],"a":0,"e":"均一性红细胞提示出血来自肾小球以外的泌尿系统，如结石、炎症、损伤；肾小球源性血尿的红细胞经基底膜挤压变形，呈非均一性。"},{"q":"患者，女，43岁，慢性乙型肝炎20年。近期恶心、食欲减退，查体：心肺无异常，脾肋下3cm，双下肢凹陷性水肿。该患者不会出现的情况是","o":["凝血因子缺乏","血红蛋白减少","雌激素增加","醛固酮增加","肾上腺皮质激素减少"],"a":3,"e":"官方答案为【醛固酮增加】，但依据教材，正确答案为【肾上腺皮质激素减少】。门静脉高压与低蛋白血症时继发性醛固酮增多是腹水形成的重要机制，醛固酮必然升高。"},{"q":"患者，女，25岁。近年来多次于情绪激动或生气后出现四肢抽搐，两眼紧闭，每次发作时间较长。抽搐发作时，无舌咬伤及大、小便失禁。该患者最可能的诊断是","o":["晕厥","癫痫小发作","癫痫大发作","癔症性发作","短暂性脑缺血发作"],"a":3,"e":"发作前有生气、情绪激动等诱因，形式不固定、持续时间长，且无舌咬伤与大小便失禁，符合癔症性发作；癫痫大发作常有舌咬伤与尿失禁。"},{"q":"患者，男，54岁。右肋痛４个月，食欲减退。查体：巩膜轻度黄染，肝肋下1cm，质中等，未触及结节。肝CT扫描见肝有大小不等的斑块放射性缺损区，边缘不整齐。实验室检查：AFP 540μg/L，HBsAg（＋）。该患者最可能的诊断是","o":["乙型肝炎","阿米巴肝脓肿","肝硬化","原发性肝癌","淤胆性肝炎"],"a":3,"e":"AFP 540μg/L远超400μg/L的诊断界值，伴HBsAg阳性与肝内边缘不整的占位，符合原发性肝癌；阿米巴肝脓肿CT呈低密度囊腔而非斑块状缺损。"},{"q":"患者，男，46岁，长期大量饮酒史，腹胀1个月入院。近2天尿量200ml/d。查体：巩膜黄染，颈部见蜘蛛痣，颈静脉不充盈，腹部膨隆，移动性浊音阳性。该患者少尿的原因首先考虑","o":["心功能不全","慢性肾炎","肝肾综合征","前列腺肥大","急性肾炎"],"a":2,"e":"肝硬化失代偿期出现少尿、腹水与黄疸，而颈静脉不充盈，提示肾前性肾灌注不足，属肝肾综合征；心功能不全者应有颈静脉怒张。"},{"q":"患者，男，神经系统查体发现眼球受压30s后心率减少达15次/min。这提示","o":["迷走神经功能增强","迷走神经功能麻痹","交感神经亢进","深感觉过敏","深反射活跃"],"a":0,"e":"压迫眼球后心率减慢超过12次/分，提示副交感（迷走）神经功能增强；迷走神经麻痹时该反射消失，交感神经亢进则心率加快。"},{"q":"患者，女，22岁。2个月前开始无明显诱因出现怕热多汗、心悸手抖、烦躁易怒、体重下降。查体脉搏100次/min，双眼凸出、睑裂增大、瞬目减少。最可能的诊断是","o":["眼球筋膜炎","肢端肥大症","破伤风","甲状腺功能亢进","库欣综合征"],"a":3,"e":"怕热多汗、心悸手抖、烦躁易怒伴体重下降及双眼突出、睑裂增大，是甲状腺激素分泌过多所致的高代谢与交感兴奋表现，符合甲状腺功能亢进。"},{"q":"患者，男，35岁。眩晕1天，伴恶心、呕吐，无耳鸣及听力减退，有近期上呼吸道感染史。查体：T 36.5℃，神志清，四肢肌力及腱反射正常。该患者最可能的诊断是","o":["梅尼埃病","多发性硬化","前庭神经元炎","颅内感染性疾病","癫痫"],"a":0,"e":"官方答案为【梅尼埃病】，但依据教材，正确答案为【前庭神经元炎】。上呼吸道感染后突发眩晕、恶心呕吐而无耳鸣及听力减退是前庭神经元炎的特点，梅尼埃病必伴耳鸣与听力下降。"},{"q":"患者，男，55岁。近两年有夜间阵发性呼吸困难，入院前2小时出现呼吸困难，咳粉红色泡沫痰。患者最可能出现呼吸困难的原因是","o":["急性左心衰竭","心肌梗死","支气管哮喘","气胸","肺炎"],"a":0,"e":"夜间阵发性呼吸困难基础上咳浆液性粉红色泡沫痰，是急性左心衰竭肺水肿的表现，因肺毛细血管压骤升致血浆与红细胞渗入肺泡。"},{"q":"年轻女性，反复发作咳嗽、胸闷4年，常在春夏之交发作，夜间重，并有鼻痒、喷嚏等症。听诊双肺较多干性啰音，呼气延长。最可能的诊断为","o":["肺气肿","气胸","胸腔积液","支气管哮喘","慢性支气管炎"],"a":3,"e":"青少年反复发作性咳嗽、胸闷，春秋季好发、夜间加重，伴鼻痒喷嚏等过敏表现，听诊双肺干啰音与呼气延长，符合支气管哮喘的气道高反应性。"},{"q":"患者，男，42岁，急性白血病（M5）化疗后缓解，拟行骨髓移植。移植配型时，HLA各位点中抗原相配程度最为重要的是","o":["人类白细胞抗原-D和DR","人类白细胞抗原-B","人类白细胞抗原-A","人类白细胞抗原-C","人类白细胞抗原-DN"],"a":0,"e":"HLA-DR的配合对提高移植物存活率尤为重要，HLA-A、B、D、DR完全相合者存活率明显高于不相合者，故配型以D与DR位点最为关键。"},{"q":"患者，男，16岁。自幼常有鼻出血，3天前踢球时外伤，右大腿肿胀，活动受限，有家族史。为确诊应做的检查是","o":["毛细血管脆性试验","出血时间","凝血酶凝固时间","部分凝血活酶时间","抗凝血酶Ⅲ活性"],"a":3,"e":"自幼鼻出血、外伤后大腿深部血肿且有家族史，提示血友病；内源凝血系统缺陷使活化部分凝血活酶时间延长，而出血时间与血小板计数正常。"},{"q":"患者，男，46岁。活动耐力进行性下降5年。近半年来平地步行50m左右即感呼吸急促，并出现双下肢水肿。1周前上呼吸道感染后症状加重，伴夜间阵发性呼吸困难。查体：平卧位，颈静脉怒张，肝颈静脉反流征阳性，双肺可闻及细湿啰音，双下肢凹陷性水肿。目前该患者的心力衰竭类型为","o":["急性右心衰竭","急性左心衰竭","全心衰竭","慢性左心衰竭","慢性右心衰竭"],"a":2,"e":"患者既有左心衰竭的肺淤血表现（夜间阵发性呼吸困难、双肺细湿啰音），又有体循环淤血表现（颈静脉怒张、肝颈静脉反流征阳性、下肢水肿），故为全心衰竭。"},{"q":"患者，男，32岁，低热、乏力，盗汗1个月余。近日胸闷呼吸困难，X线示胸腔积液，考虑为渗出液。下列描述正确的是","o":["置入试管内不自凝","蛋白定量＜25g/L","葡萄糖定量与血糖相近","细胞计数常＞500×106/L","以淋巴细胞、间皮细胞为主"],"a":3,"e":"结核性渗出液的细胞计数常＞500×10⁶/L，以淋巴细胞为主；漏出液蛋白定量＜25g/L、细胞数＜100×10⁶/L，且置入试管内不自凝。"},{"q":"患者，男，50岁，肝硬化病史10年，以严重腹水3周来诊。肝脾触诊应采用哪种方法","o":["单手触诊法","双手触诊法","滑动触诊法","钩指触诊法","冲击触诊法"],"a":4,"e":"大量腹水时肝脾被腹水托起、深部触诊难以触及，需用冲击（浮沉）触诊法，以并拢三指垂直冲击腹壁，排开液体后触及脏器。"},{"q":"患者，男，24岁。1个月前无明显诱因出现咳嗽、乏力、盗汗，伴胸痛，随呼吸或咳嗽加重，查体示气管向右侧移位。该患者最可能的疾患是","o":["自发性气胸","胸膜粘连","结核性胸膜炎并左侧胸腔积液","结核性胸膜炎并右侧胸腔积液","大叶性肺炎"],"a":2,"e":"结核毒血症状伴胸痛随呼吸加重，气管移向右侧即被推向健侧，提示左侧大量胸腔积液将纵隔推开；胸膜粘连则使气管移向患侧。"},{"q":"患者，男，40岁，饥饿时中上腹部隐痛10年，伴反酸嗳气，在进食和服制酸剂后可缓解。今晨中上腹剧痛后腹痛持续存在。该患者最可能患的基础疾病是","o":["急性胰腺炎","胰腺癌","胃癌","消化性溃疡","急性胆囊炎"],"a":3,"e":"饥饿痛、进食或服制酸剂可缓解的节律性上腹痛是十二指肠溃疡的特点；突发持续剧痛提示溃疡穿孔，胃内容物刺激腹膜致腹肌紧张。"},{"q":"患者，男，65岁，诊断乙肝肝硬化失代偿期，有门静脉高压。其查体腹壁静脉血流方向正确的是","o":["与正常的血流方向相同","与正常的血流方向相反","方向不固定","肚脐以下向上流","肚脐以上向下流"],"a":0,"e":"门静脉高压时腹壁曲张静脉以脐为中心向四周伸展，血流方向仍与正常一致，即脐以上向上、脐以下向下；下腔静脉阻塞时脐以下血流转向向上。"},{"q":"患者，男，50岁，患肝硬化5年。肝脏超声为：肝脏缩小，表面不平，内部回声粗糙。近1个月，肝脏增大，肋下可及。应首选复查的化验检查是","o":["GPT","A/G","GOT","AFP","ALP"],"a":3,"e":"肝硬化患者肝脏短期内增大需警惕肝癌，AFP是辅助诊断原发性肝癌最常用的标志物，≥400μg/L持续1个月应高度怀疑并进一步影像学检查。"},{"q":"患者，男，51岁，曾患急性乙型病毒性肝炎，近期发现皮肤黏膜发黄。该患者首先出现黄染的部位可能是","o":["前额","巩膜","鼻部","手掌","足底"],"a":1,"e":"黄疸时胆红素与弹性蛋白结合，巩膜富含弹性蛋白且对比明显，故黄染最先出现于巩膜，且近角巩膜缘轻、远角巩膜缘重。"},{"q":"患者，女，52岁。2个月前无明显诱因出现乏力、食欲缺乏、消瘦，半月前开始出现腹胀、腹围增大、尿量减少、尿色黄。该患者最可能的面容是","o":["贫血面容","肝病面容","肾病面容","黏液性水肿面容","二尖瓣面容"],"a":1,"e":"乏力、食欲缺乏、消瘦伴腹胀、腹围增大、尿少与尿黄提示肝硬化失代偿，患者面色晦暗、额部鼻背及双颊褐色色素沉着，呈肝病面容。"},{"q":"患者，男，低热1个月，右侧胸痛3天，胸部X线可见右侧肋膈角少量胸腔积液。关于该患者体征描述正确的是","o":["气管移向左侧","右侧胸廓饱满","右侧叩诊呈过清音","右侧可触及胸膜摩擦感","右侧肺泡呼吸音增强"],"a":3,"e":"少量胸腔积液时脏、壁两层胸膜被纤维蛋白分隔而仍相接触，呼吸时相互摩擦，可触及胸膜摩擦感；积液增多将两层胸膜分开后该体征消失。"},{"q":"患者，女，无发热和腰痛，有膀胱刺激征和血尿，可能的诊断是","o":["急性膀胱炎","急性肾盂肾炎","泌尿系结核","膀胱结石","膀胱肿瘤"],"a":0,"e":"膀胱刺激征伴血尿而无发热、腰痛，提示感染局限于膀胱黏膜，符合急性膀胱炎；急性肾盂肾炎常伴寒战高热与肾区叩击痛。"},{"q":"患者，女，30岁。劳累性呼吸困难2年。查体：心尖部闻及舒张中、晚期隆隆样杂音，胸骨左缘第2肋间舒张期递减型叹气样杂音。最可能诊断为","o":["二尖瓣狭窄合并主动脉瓣器质性关闭不全","二尖瓣狭窄合并肺动脉瓣器质性关闭不全","二尖瓣狭窄合并肺动脉瓣相对性关闭不全","二尖瓣狭窄合并肺动脉瓣相对性狭窄","二尖瓣狭窄合并肺动脉瓣器质性狭窄"],"a":2,"e":"二尖瓣狭窄致肺动脉高压、肺动脉扩张，产生Graham Steell杂音，位于胸骨左缘第2肋间、吸气末增强，属相对性关闭不全；器质性肺动脉瓣关闭不全极少见。"},{"q":"患者，女，16岁，胸痛，呼吸困难。查体：气管向左侧移位，语颤右侧减弱，叩之实音。最可能的诊断是","o":["气胸","胸腔积液","肺气肿","支气管扩张","支气管哮喘"],"a":1,"e":"气管移向健侧、患侧语颤减弱、叩诊实音，是大中量胸腔积液的典型体征，因液体将胸膜腔撑开并压迫纵隔移位；气胸叩诊呈鼓音。"},{"q":"患者，女，18岁，发热、咽痛、鼻黏膜出血10天。查体：浅表淋巴结、肝、脾大，胸骨压痛，右下肢皮肤可见3cm×3cm大小肿块，质硬。实验室检查：RBC 3、1×1012/L，Hb 85g/L，WBC 45×109/L，BPC 20×109/L；骨髓增生极度活跃，原始细胞占80%，部分原始细胞胞质中可见Auer小体，原始细胞POX染色弱阳性，PAS染色胞质淡红色，胞质边缘有细小的阳性颗粒，α-NAE染色阳性，能被氟化钠抑制。应诊断为","o":["急性粒细胞白血病","急性早幼粒细胞白血病","急性单核细胞白血病","急性红白血病","急性淋巴细胞白血病"],"a":2,"e":"α-NAE染色阳性且能被氟化钠抑制是急性单核细胞白血病的细胞化学特征；原始细胞含Auer小体、POX弱阳性可排除急性淋巴细胞白血病。"},{"q":"患者，女，72岁。4小时前做家务时突然倒地不省人事，家属发现后呼120送入医院。查体意识丧失，唤之不醒，各种生理反射均消失。其意识障碍程度属","o":["嗜睡","意识模糊","昏睡","浅昏迷","深昏迷"],"a":4,"e":"意识完全丧失、对任何刺激无反应且深浅反射均消失，属深昏迷；浅昏迷时对疼痛刺激尚有防御反应，腱反射与瞳孔对光反射可存在。"},{"q":"患者，女，51岁，下蹲或腹部用力时，出现不自主地流尿。初步考虑是","o":["充盈性尿失禁","急迫性尿失禁","反射性尿失禁","真性尿失禁","压力性尿失禁"],"a":4,"e":"腹压突然增高（下蹲、咳嗽、用力）时尿液不自主流出，为压力性尿失禁，因盆底肌与尿道括约肌张力减退、膀胱颈支持结构松弛所致。"},{"q":"某患者体检发现心尖部递减型舒张早期隆隆杂音，胸骨左缘第3肋间可闻递减型舒张期叹气样杂音，血压140/50mmHg。其最可能的诊断为","o":["二尖瓣狭窄合并主动脉瓣关闭不全","二尖瓣狭窄合并肺动脉瓣关闭不全","严重二尖瓣狭窄","二尖瓣狭窄合并主动脉瓣狭窄","主动脉瓣关闭不全"],"a":4,"e":"胸骨左缘第3肋间舒张期叹气样杂音伴脉压增大是主动脉瓣关闭不全的特征；心尖部递减型舒张早期杂音为反流束限制二尖瓣开放形成的Austin Flint杂音。"},{"q":"患者，男，30岁。反复头痛，前额痛为主，午后头痛加重，平卧位时头痛减轻，无呕吐及视物模糊。家族中无类似病史。查体：BP 130/70mmHg，双瞳孔等大等圆，颈软，上颌窦区有压痛。检查眼压不高。可能的诊断是","o":["青光眼","高血压","鼻窦炎","颅内压升高","偏头痛"],"a":2,"e":"前额痛、午后加重伴上颌窦区压痛，提示上颌窦炎；鼻窦引流不畅致窦内压升高，头痛多于晨起或上午明显，低头时加重。"},{"q":"患者，女，30岁，发热1周，左腹股沟区可扪及5cm×4cm×3cm大小肿物，有压痛，有波动感。切开发现其肿物为脓液，黏稠有粪臭。首选的抗菌药物是","o":["青霉素","庆大霉素","红霉素","链霉素","甲硝唑"],"a":1,"e":"脓液稠厚伴粪臭是大肠埃希菌感染的特点，庆大霉素等氨基糖苷类对革兰阴性杆菌有效；青霉素、红霉素主要针对革兰阳性菌。"},{"q":"患者，男，22岁，发热、咳嗽、胸痛3天。查体：右下肺呼吸音减弱，语颤减弱，叩诊呈实音。最有可能的疾病是","o":["气胸","胸腔积液","肺脓肿","支气管哮喘","肺气肿"],"a":1,"e":"患侧语颤减弱、呼吸音减弱伴叩诊实音，是胸腔积液的典型体征；肺实变时语颤增强并闻及支气管呼吸音，二者可据此鉴别。"},{"q":"患者，男，66岁，因“反复间断呼吸困难10年，加重6小时”收入住院。有冠心病病史9年，平时未规律服药控制。此次急性加重，端坐呼吸，咳粉红色泡沫痰，双肺均可闻及呼吸音，可闻及较多湿啰音及哮鸣音，心率快。入院肌钙蛋白及D-二聚体未见特殊异常，心电图提示窦性心动过速，NT-proBNP 8643ng/ml。该患者考虑","o":["支气管哮喘急性发作","张力性气胸","急性肺水肿","气管异物","大面积肺栓塞"],"a":2,"e":"冠心病患者突发端坐呼吸、咳粉红色泡沫痰、双肺满布湿啰音，NT-proBNP显著升高，符合急性左心衰竭所致急性肺水肿；肌钙蛋白正常可除外心梗。"},{"q":"患者，女，32岁，有尿频、尿急、尿痛症状2天，尿量正常，无发热，伴腰痛，要明确诊断，首选的检查是","o":["尿常规＋镜检","肾功能","泌尿系CT","膀胱镜","静脉肾炎造影"],"a":0,"e":"膀胱刺激征伴腰痛需先确定有无脓尿与血尿，尿常规加镜检可发现白细胞、红细胞及白细胞管型，是尿路感染筛选与定位的首选检查。"},{"q":"患者，男，22岁。长期食用辛辣刺激性食物，间断腹痛。今日饮用大量酒后出现呕血，后持续性腹痛，不缓解。查体：腹部柔韧，腹肌紧张，全腹压痛。行腹部平片可见膈下游离气体。可能的诊断为","o":["急性胰腺炎","消化性溃疡穿孔","急性肠梗阻","胆道蛔虫症","结核性腹膜炎"],"a":1,"e":"饮大量酒后突发持续上腹痛、腹肌紧张伴全腹压痛，立位腹平片见膈下游离气体，是消化性溃疡急性穿孔的确诊依据。"},{"q":"患者，女，32岁，进行性膀胱刺激征，经抗生素治疗不见好转，伴右侧腰部胀痛及午后潮热。对诊断有决定性意义的检查是","o":["尿普通细菌培养","尿细胞学检查","膀胱B超","逆行尿路造影","尿沉渣找结核杆菌"],"a":4,"e":"膀胱刺激征进行性加重、抗生素治疗无效并伴午后潮热与腰部胀痛，提示泌尿系结核；尿沉渣抗酸染色找结核分枝杆菌对诊断有决定性意义。"},{"q":"患者，男，32岁，低热、头痛2天。行腰穿术取得脑脊液后，静置24小时表面出现薄膜状，考虑为","o":["结核性脑膜炎","病毒性脑膜炎","化脓性脑膜炎","新型隐球菌脑炎","流行性乙型脑炎"],"a":0,"e":"脑脊液静置12～24小时后表面形成纤维蛋白薄膜，是结核性脑膜炎的特征，因纤维蛋白原含量增高；化脓性脑膜炎外观呈乳白色浑浊。"},{"q":"患者，男，59岁。逐渐消瘦，咳嗽，左胸痛，气短逐渐加重，低热，无咯血，胸透左胸腔中等量积液。该患叩诊最可能出现的是","o":["清音","鼓音","过清音","浊鼓音","实音"],"a":4,"e":"中等量胸腔积液时积液区下部叩诊呈实音、上部为浊音，呼吸音与语音共振减弱；积液上界呈外高内低的Damoiseau曲线。"},{"q":"患者，66岁，既往5年高血压病史。心悸1年，劳力性心累胸闷2个月。查体：心音强弱快慢绝对不齐。常规心电图示心室率，125次/min，等电位线消失，P波不可见，QRS呈正常形态。该患者的心电图诊断是","o":["窦性心律，频发室性期前收缩","心房颤动","心房扑动","阵发性室上性心动过速","阵发性室性心动过速"],"a":1,"e":"心律绝对不齐、第一心音强弱不等伴脉搏短绌，心电图P波消失代以大小不等的f波、QRS形态正常，是心房颤动的诊断依据。"},{"q":"患者，女，17岁，以周期性鼻出血2年为主诉来诊。双鼻腔内检查未见异常。血常规：WBC 7.5×109/L，Hb 130g/L，RBC 4.0×1012/L，血小板计数 250×109/L。最可能的诊断是","o":["血小板减少性紫癜","白血病","子宫内膜异位症","再生障碍性贫血","缺铁性贫血"],"a":2,"e":"鼻出血与月经周期同步、反复周期性发作，而血小板计数与凝血功能正常，提示子宫内膜异位症累及鼻黏膜；血液病所致出血无周期性。"},{"q":"患者，女，22岁。近5天来发烧寒战，头痛，尿呈酱油色。查体：巩膜黄染，心肺未见异常，腹软，无压痛，肝脾未触及。下列哪项检查支持溶血性贫血的诊断","o":["血清非结合胆红素正常","血清结合胆红素增加","尿胆红素阳性","尿胆原增加","血清碱性磷酸酶增加"],"a":3,"e":"溶血时非结合胆红素升高，排入肠道的结合胆红素增多使尿胆原生成与回吸收增加，尿中排出增多；尿胆红素阴性是溶血性黄疸的特点。"},{"q":"患者，男，48岁，10年少量饮酒史。近1个月上腹疼痛，饥饿时加重，呈现疼痛－进食－缓解的规律。如为活动期溃疡，其内镜下的表现是","o":["直径0.5～1.5cm椭圆形凹陷，底部覆以白苔，其上可见出血点或血痂，周围黏膜充血、水肿，呈堤状隆起","溃疡缩小、变浅、白苔边缘光滑变薄，周边水肿，再生上皮明显呈红色栅状，可见黏膜皱襞集中，达溃疡边缘","溃疡面消失被再生上皮覆盖，黏膜皱襞呈放射状集中","黏膜充血、斑片状发红，黏膜水肿、反光增强","黏膜肥厚、水肿，皱襞粗大似脑回状"],"a":0,"e":"活动期溃疡内镜下为圆形或椭圆形凹陷，直径0.5～1.5cm，底覆白苔、血痂或血凝块，周围黏膜充血水肿呈堤状隆起。愈合期才表现为溃疡缩小变浅、再生上皮呈红色栅状并向中心集中。"},{"q":"患者，女，24岁发热、乏力、盗汗，胸痛伴呼吸困难1周，听诊可闻及胸膜摩擦音。该患最有可能的诊断是","o":["大叶性肺炎","大量胸腔积液","渗出性胸膜炎","支气管扩张","慢性支气管炎"],"a":2,"e":"午后低热、乏力盗汗伴胸痛与呼吸困难，听诊闻及胸膜摩擦音，符合渗出性胸膜炎。大叶性肺炎多起病急、高热咳铁锈色痰；大量胸腔积液使两层胸膜分开，摩擦音反而消失。"},{"q":"患者，男，80岁，慢性阻塞性肺疾病病史20年。关于该患者的叩诊，说法错误的是","o":["叩诊呈过清音","Kronig峡增宽","肺下界下移","肺下界移动度减弱","肝浊音界上移"],"a":4,"e":"慢性阻塞性肺疾病肺气肿时膈肌下降，肝浊音界应下移而非上移，故此说错误。叩诊过清音、Kronig峡增宽、肺下界下移及移动度减弱均为肺气肿的典型改变。"},{"q":"患者，女，23岁。因心悸1个月就诊。查体：血压120/80mmHg，心率85次/min，律不齐。心电图示：窦性心律，可见提前出现的P波，形态与窦性P波不同，P-R间期0.14s，QRS波群形态正常。心悸最可能的原因是","o":["窦性心动过速","心房颤动","窦性心动过缓","室性期前收缩","房性期前收缩"],"a":4,"e":"提前出现的异位P′波形态与窦性P波不同，P′R间期0.14s＞0.12s，QRS波群形态正常，为房性期前收缩的心电图特征。室性期前收缩QRS波群宽大畸形且其前无相关P波。"},{"q":"患者，女，50岁。风湿性心脏病病史10年，心慌气短14天。查心电图：P波消失，代之以大小不等、形状各异的f波，频率为400次/min，心室律绝对不规则，心率130次/min，脉率110次/min。应考虑为","o":["室性期前收缩二联律","心房扑动","室上性心动过速","心房颤动","窦性心律不齐"],"a":3,"e":"P波消失代之以大小不等、形状各异的f波，心室律绝对不规则，脉率少于心率形成脉搏短绌，为心房颤动的典型表现。心房扑动则为形态规则的锯齿状F波。"},{"q":"患者，女，24岁，反复无诱因心悸，持续时间不等，症状自行恢复；晕厥1次。体格检查示心率170次/min，心律齐，无杂音。该患者最可能的诊断是","o":["心房颤动","心房扑动","阵发性室上性心动过速","窦性心动过速","预激综合征"],"a":2,"e":"心悸反复发作、突发突止，心率170次/min而心律齐、无杂音，符合阵发性室上性心动过速。窦性心动过速多有发热、运动等诱因且渐起渐止，心率一般不超过150次/min。"},{"q":"患者，男，29岁，因午后低热10天，左侧胸痛伴活动后气紧5天入院。胸片示左侧中量胸腔积液。为减轻症状，该患者采取的体位最有可能是","o":["被动体位","强迫坐位","强迫停立位","强迫蹲位","强迫侧卧位"],"a":4,"e":"胸腔积液患者常取病侧卧位，可限制患侧胸廓活动、减轻胸痛并利于健侧代偿呼吸，属强迫侧卧位。强迫坐位多见于心肺功能不全者，强迫停立位见于心绞痛。"},{"q":"某风湿性心脏病患者，心电图表现为：P波增宽，呈双峰型，P波时限0.12s，两峰间距0.05s，以Ⅰ、Ⅱ、aVL导联明显，应考虑为","o":["左室肥大","双房肥大","左房肥大","右房肥大","右室肥大"],"a":2,"e":"P波增宽≥0.12秒、呈双峰型且两峰间距≥0.04秒，以Ⅰ、Ⅱ、aVL导联明显，为左心房肥大表现，常见于二尖瓣疾病，又称二尖瓣型P波。右心房肥大则表现为P波高尖。"},{"q":"患者，男，45岁。车祸伤后出现尿痛，血尿3小时。查体：阴茎和阴囊部出现蝴蝶形血肿。该患者最可能的诊断是","o":["急性膀胱炎","急性前列腺炎","尿道破裂","急性附睾炎","睾丸外伤"],"a":2,"e":"会阴部外伤后出现阴茎、阴囊蝴蝶形血肿，伴血尿与尿痛，提示球部尿道破裂，尿液沿会阴浅筋膜间隙外渗。急性膀胱炎以尿频尿急尿痛为主，无外伤及血肿形成。"},{"q":"患儿，女，14岁，学生，发现脱发1周余。查体：左侧淋巴结肿大，有轻压痛；头皮数个脱发区，有白色鳞屑粘着，头发上可见鳞屑。诊断考虑","o":["石棉状糠疹","头皮银屑病","头癣","头皮脂溢性皮炎","斑秃"],"a":2,"e":"头皮出现覆有白色鳞屑的脱发区，发干附着鳞屑即菌鞘，伴局部淋巴结轻压痛肿大，符合白癣型头癣。斑秃为边界清楚的圆形脱发，无鳞屑、无炎症及淋巴结肿大。"},{"q":"患者，女，32岁，进行性膀胱刺激征，经抗生素治疗不见好转，伴右侧腰部胀痛及午后潮热。为了解患者肾功能及形态的病理改变，最有价值的检查是","o":["超声检查","静脉尿路造影","逆行尿路造影","CT","MRI"],"a":1,"e":"静脉尿路造影可显示肾盏虫蚀样破坏、空洞及肾积水等形态改变，并反映分肾功能，对肾结核价值最大。逆行尿路造影在膀胱挛缩时插管困难，超声与CT主要观察形态。"},{"q":"患者，男，60岁，食欲缺乏、腹胀，考虑酒精性肝硬化失代偿来诊。下列查体可见，但应除外","o":["蛙状腹","水母头样腹壁静脉","肚脐突出","腹式呼吸增强","肝掌"],"a":3,"e":"大量腹腔积液使膈肌上抬、腹壁张力增高，腹式呼吸应减弱而非增强，故为应除外者。蛙状腹、脐突出、腹壁静脉水母头样曲张及肝掌均为失代偿期肝硬化的体征。"}];
